window.SCENES_B1 = [
{"id":"sc-u28-a","unit":"u28","band":"B1","title":"The meeting","brief":"You're Tomás, at the neighbourhood meeting about Altamira's hotel. Doña Gloria, the loud neighbour from the bakery, is running things. She is older, so use usted. Say what you think, and say what you don't think.","turns":[{"id":"t1","npc":"Buenas noches, Tomás. Ya casi empezamos. ¿Usted va a hablar esta noche?","npcEn":"Good evening, Tomás. We're about to start. Are you going to speak tonight?","intent":"Say yes, and say it's important that the neighbours speak tonight.","accept":["Buenas noches, señora. Sí, voy a hablar. Es importante que hablemos esta noche.","Sí, señora. Es importante que todos los vecinos hablen hoy.","Sí. Es importante que los vecinos opinen esta noche."],"require":[{"type":"subjunctiveAfter","trigger":"es importante que","within":5,"label":"after es importante que, the verb changes: hablemos"}],"focus":"g:subj-value","next":"t2"},{"id":"t2","npc":"Eso mismo digo yo. Altamira quiere comprar toda la cuadra para hacer un hotel. ¿Usted qué opina?","npcEn":"I say the same. Altamira wants to buy the whole block to make a hotel. What do you think?","intent":"Say you don't think it's fair for the neighbourhood.","accept":["No creo que sea justo para el barrio.","Yo no creo que ese hotel sea justo.","No me parece que sea justo. Esa esquina tiene cien años."],"require":[{"type":"regex","pattern":"\\bno (creo|pienso|me parece) que","flags":"i","label":"say you don't think so: no creo que..."},{"type":"subjunctiveAfter","trigger":"que","within":3,"label":"after no creo que, the verb changes: sea"}],"focus":"g:subj-opinion-negated","next":"t3"},{"id":"t3","npc":"Pues el señor de la tienda de al lado cree que el hotel es una gran idea. Dice que habrá trabajo para todos.","npcEn":"Well, the man from the shop next door thinks the hotel is a great idea. He says there will be work for everyone.","intent":"Say the worst thing is that your café would close.","accept":["Lo peor es que mi café va a cerrar.","Lo peor es que van a cerrar el café.","Lo peor es que cerrarían el café y la panadería."],"require":[{"type":"regex","pattern":"\\blo peor\\b","flags":"i","label":"start with lo peor"}],"focus":"g:lo-adjective","next":"t4"},{"id":"t4","npc":"Entonces usted no quiere que el barrio mejore, ¿cierto?","npcEn":"So you don't want the neighbourhood to get better, right?","intent":"Say you do want the neighbourhood to improve, but you don't think a hotel is the answer.","accept":["Sí, señora, quiero que mejore. Pero no creo que un hotel sea la solución.","No, para nada. Quiero que mejore, pero no creo que un hotel sea lo mejor para el barrio.","Sí, señora. Pero no creo que un hotel sea una buena idea."],"require":[{"type":"regex","pattern":"\\bno (creo|pienso|me parece) que","flags":"i","label":"say you don't think so: no creo que..."},{"type":"subjunctiveAfter","trigger":"que","within":3,"label":"after no creo que, the verb changes: sea"}],"focus":"g:subj-opinion-negated","next":"t5"},{"id":"t5","npc":"Bien dicho. Ahora todos quieren oírlo. ¿Quiere decirles algo a los vecinos?","npcEn":"Well said. Now everyone wants to hear you. Do you want to say something to the neighbours?","intent":"Thank her, and say the good thing is that you're not alone.","accept":["Gracias, señora. Estoy nervioso, pero lo bueno es que no estoy solo.","Con gusto. Lo bueno es que todo el barrio está aquí.","Gracias. Lo mejor es que los vecinos quieren escuchar."],"require":[{"type":"regex","pattern":"\\blo (bueno|mejor)\\b","flags":"i","label":"start with lo bueno or lo mejor"}],"focus":"g:lo-adjective","next":null}],"r":["g:gender-articles","g:lo-adjective","g:present-ar","g:stem-boot","g:subj-opinion-negated","g:subj-value","g:that-clauses","g:verb-infinitive"],"d":null},
{"id":"sc-u28-b","unit":"u28","band":"B1","title":"Cold coffee, hot night","brief":"You're Tomás, back at the café after the meeting. Vale missed it and wants the story. She's your friend, so use tú. Tell her the best and worst parts, and what you think.","turns":[{"id":"t1","npc":"Jefe, ¿cómo estuvo la reunión? Yo me quedé en la cocina toda la noche.","npcEn":"Boss, how was the meeting? I stayed in the kitchen all night.","intent":"Say the best thing was that the whole neighbourhood came.","accept":["Lo mejor fue que vino todo el barrio.","Lo bueno es que vino mucha gente.","Lo mejor fue que casi todos los vecinos hablaron."],"require":[{"type":"regex","pattern":"\\blo (mejor|bueno)\\b","flags":"i","label":"start with lo mejor or lo bueno"}],"focus":"g:lo-adjective","next":"t2"},{"id":"t2","npc":"¿Y lo peor?","npcEn":"And the worst part?","intent":"Say the worst thing was that nobody listened to anybody.","accept":["Lo peor fue que nadie escuchó a nadie.","Lo peor fue el ruido. Todos gritaban.","Lo malo es que nadie quería escuchar."],"require":[{"type":"regex","pattern":"\\blo (peor|malo)\\b","flags":"i","label":"start with lo peor or lo malo"}],"focus":"g:lo-adjective","next":"t3"},{"id":"t3","npc":"El señor de la tienda de al lado dice que el hotel es una gran idea para el barrio. ¿Tú qué piensas de eso?","npcEn":"The man from the shop next door says the hotel is a great idea for the neighbourhood. What do you think of that?","intent":"Say you don't think so, and that it's a pity the old corner will disappear.","accept":["No creo. Es una pena que desaparezca la esquina.","No, no creo. Es una pena que cierren tantas tiendas viejas.","No, para nada. Es una pena que el barrio pierda su historia."],"require":[{"type":"regex","pattern":"\\bno\\b","flags":"i"},{"type":"subjunctiveAfter","trigger":"una pena que","within":4,"label":"after es una pena que, the verb changes: desaparezca"}],"focus":"g:subj-value","next":"t4"},{"id":"t4","npc":"Pues yo llevé veinte empanadas a la reunión. ¿Sabes quién las comió? El señor de la tienda.","npcEn":"Well, I took twenty empanadas to the meeting. Do you know who ate them? The man from the shop.","intent":"Say you don't think he's a bad person, but you find it funny.","accept":["No creo que ese señor sea malo, pero lo encuentro muy gracioso.","Lo encuentro muy gracioso. No creo que él sea tan malo.","No creo que sea mala persona, pero lo encuentro gracioso."],"require":[{"type":"regex","pattern":"\\bno (creo|pienso|me parece) que","flags":"i","label":"say you don't think so: no creo que..."},{"type":"subjunctiveAfter","trigger":"que","within":3,"label":"after no creo que, the verb changes: sea"}],"focus":"p:encontrar-ver-adj","next":"t5"},{"id":"t5","npc":"Bueno, te guardé una empanada en la cocina. ¿Un tinto antes de cerrar?","npcEn":"Well, I saved you an empanada in the kitchen. A coffee before we close?","intent":"Thank her, say yes, and say what you like most about the end of the day.","accept":["Gracias, Vale. Sí, claro. Lo que más me gusta de la noche es un tinto contigo.","Sí, gracias. Lo que más me gusta es terminar el día con un tinto.","Claro. Lo que más me gusta de este café es la hora de cerrar."],"require":[{"type":"regex","pattern":"\\blo que más me gusta","flags":"i","label":"start with lo que más me gusta"}],"focus":"p:lo-que-mas-me-gusta","next":null}],"r":["g:gender-articles","g:lo-adjective","g:preterite-ar","g:questions","g:subj-value","p:encontrar-ver-adj","p:lo-que-mas-me-gusta"],"d":null},
{"id":"sc-u28-c","unit":"u28","band":"B1","title":"For the article","brief":"You're Tomás. Mariana, the journalist, calls the morning after the meeting for a quote. She's a friend, so use tú. Give your opinion clearly, say what you don't think, and describe how it felt.","turns":[{"id":"t1","npc":"Tomás, soy Mariana. Escribo sobre la reunión de anoche para el periódico. ¿Tienes cinco minutos?","npcEn":"Tomás, it's Mariana. I'm writing about last night's meeting for the paper. Do you have five minutes?","intent":"Say yes, and say it's important that the article tells the truth.","accept":["Sí, claro. Es importante que el artículo diga la verdad.","Tengo cinco minutos. Es importante que escribas lo que pasó de verdad.","Claro, Mariana. Es importante que hablemos ahora, antes de abrir el café."],"require":[{"type":"subjunctiveAfter","trigger":"que","within":5,"label":"after es importante que, the verb changes: diga"}],"focus":"g:subj-value","next":"t2"},{"id":"t2","npc":"Claro. Primero, ¿qué piensas del plan de Altamira? La gente del barrio opina cosas muy distintas.","npcEn":"Of course. First, what do you think of Altamira's plan? People in the neighbourhood have very different opinions.","intent":"Say that you think it's a bad idea, because of the old businesses.","accept":["Me parece una mala idea, porque los negocios viejos van a sufrir.","Creo que es un error, porque el café es viejo.","No estoy a favor, porque los negocios pequeños no tienen futuro."],"require":[{"type":"containsAny","words":["porque"],"label":"give a reason with porque"}],"focus":"c:porque","next":"t3"},{"id":"t3","npc":"Entiendo. Pero el señor de la tienda de al lado dice que el hotel traerá trabajo y turistas. ¿Qué le respondes?","npcEn":"I see. But the man from the shop next door says the hotel will bring work and tourists. What do you say to him?","intent":"Say you don't think more tourists are the solution for the neighbourhood.","accept":["No creo que más turistas sean la solución para el barrio.","No creo que un hotel ayude con la inseguridad ni la basura.","No me parece que los turistas sean la solución."],"require":[{"type":"regex","pattern":"\\bno (creo|pienso|me parece) que","flags":"i","label":"say you don't think so: no creo que..."},{"type":"subjunctiveAfter","trigger":"que","within":3,"label":"after no creo que, the verb changes: sean"}],"focus":"g:subj-opinion-negated","next":"t4"},{"id":"t4","npc":"Interesante. Gloria me dijo que te levantaste y hablaste sin papeles, y que nadie lo esperaba. ¿Cómo fue?","npcEn":"Interesting. Gloria told me you stood up and spoke without notes, and that nobody expected it. How was it?","intent":"Say the hard part was speaking in front of everybody.","accept":["Lo difícil fue hablar delante de todos. Estaba muy nervioso.","Lo más difícil fue empezar. Todo lo demás fue fácil.","Lo difícil fue la primera frase, pero me escucharon."],"require":[{"type":"regex","pattern":"\\blo (más )?difícil\\b","flags":"i","label":"start with lo difícil"}],"focus":"g:lo-adjective","next":"t5"},{"id":"t5","npc":"Perfecto, esa es mi cita. El artículo sale el domingo. Oye, quiero pasar por el café para una foto. ¿Qué día es mejor?","npcEn":"Perfect, that's my quote. The article comes out on Sunday. Listen, I want to come by the café for a photo. Which day is best?","intent":"Say come by, and say you'd say Saturday is best because there are more people.","accept":["Claro. Yo diría que el sábado es mejor, porque hay más gente.","Sí, ven. Yo diría que el sábado, cuando hay más clientes.","Por supuesto. Yo diría que mejor el sábado por la mañana."],"require":[{"type":"regex","pattern":"\\byo diría\\b","flags":"i","label":"start with yo diría"}],"focus":"p:yo-diria-que","next":null}],"r":["c:porque","g:gender-articles","g:lo-adjective","g:present-er-ir","g:questions","g:ser-identity","g:stem-boot","g:subj-opinion-negated","g:subj-value","g:that-clauses","p:yo-diria-que"],"d":null},
{"id":"sc-u28-d","unit":"u28","band":"B1","title":"The bench outside","brief":"You're Tomás, opening the café early. Don Hernando, the retired taxi driver, is outside complaining about the street. He is older and courtly, so use usted. Share your view of the city, and find out his.","turns":[{"id":"t1","npc":"Buenos días, joven. Mire esa basura en la calle, otra vez. ¿Qué le parece?","npcEn":"Good morning, young man. Look at that rubbish in the street, again. What do you think?","intent":"Greet him and say you see it looking bad too.","accept":["Buenos días, don Hernando. Yo también la veo muy mal.","Buenos días. La veo peor que ayer, sí.","Don Hernando, buenos días. Sí, yo la veo mucho peor."],"require":[{"type":"regex","pattern":"\\b(la|lo) veo\\b","flags":"i","label":"say how you see it: la veo..."},{"type":"avoidsAny","words":["ves"],"label":"use usted, not tú"}],"focus":"p:encontrar-ver-adj","next":"t2"},{"id":"t2","npc":"En general, Bogotá mejora. Pero hay mucha inseguridad, sobre todo de noche.","npcEn":"In general, Bogotá is getting better. But there is a lot of crime, especially at night.","intent":"Say you agree, and that it's important he doesn't go out alone at night.","accept":["Sí, señor. Es importante que usted no salga solo de noche.","Es importante que no camine solo de noche, don Hernando.","Tiene razón. Es importante que no salga solo."],"require":[{"type":"subjunctiveAfter","trigger":"es importante que","within":5,"label":"after es importante que, the verb changes: salga"}],"focus":"g:subj-value","next":"t3"},{"id":"t3","npc":"Ay, joven, eso dice mi hija. Pero yo manejé un taxi cuarenta años y nunca me pasó nada. Bueno, una vez un ladrón me robó el radio.","npcEn":"Oh, young man, that's what my daughter says. But I drove a taxi for forty years and nothing ever happened to me. Well, once a thief stole my radio.","intent":"Ask him what he thinks the biggest problem in the neighbourhood is.","accept":["¿Y usted qué opina? ¿Cuál es el problema más grande del barrio?","¿Cuál cree usted que es el peor problema del barrio?","¿Qué es lo que más le molesta del barrio, don Hernando?"],"require":[{"type":"question","label":"ask a question"}],"focus":"p:que-opinas-de","next":"t4"},{"id":"t4","npc":"Para mí, el tráfico. Y no creo que el alcalde haga algo pronto. ¿Usted cree que la gente puede cambiar algo?","npcEn":"For me, the traffic. And I don't think the mayor will do anything soon. Do you think people can change anything?","intent":"Say yes, you think the neighbours can propose solutions to the alcaldía.","accept":["Sí, creo que los vecinos pueden proponer soluciones a la alcaldía.","Claro. Creo que una comunidad unida puede cambiar muchas cosas.","Yo pienso que sí, si todos hablamos juntos."],"require":[{"type":"regex","pattern":"\\b(creo|pienso|me parece) que","flags":"i","label":"say you think so: creo que (no subjunctive here)"}],"focus":"g:subj-opinion-negated","next":"t5"},{"id":"t5","npc":"Entonces yo voy. Iré a la próxima reunión, con mi chaqueta y todo.","npcEn":"Then I'm going. I'll go to the next meeting, jacket and all.","intent":"Thank him and say you like it that he is coming.","accept":["Gracias, don Hernando. Me gusta que usted venga. Le guardo la mejor silla.","Qué bueno. Me gusta que usted nos acompañe.","Muchas gracias. Me gusta que venga, de verdad."],"require":[{"type":"subjunctiveAfter","trigger":"me gusta que","within":3,"label":"after me gusta que, the verb changes: venga"}],"focus":"p:me-encanta-que","next":null}],"r":["g:gender-articles","g:present-ar","g:present-er-ir","g:subj-opinion-negated","g:subj-value","p:encontrar-ver-adj","p:me-encanta-que","p:que-opinas-de"],"d":263,"spare":true},
{"id":"sc-u28-e","unit":"u28","band":"B1","title":"The neighbour's side","brief":"You're Tomás. Don Arturo, who runs the shop next door and is in favour of the hotel, walks into your café to talk. He is older than you, so use usted. Stay polite while you disagree, and look for something you can do together.","turns":[{"id":"t1","npc":"Buenas, vecino. Anoche usted habló muy bonito, pero yo no pienso igual.","npcEn":"Hello, neighbour. Last night you spoke very nicely, but I don't see it the same way.","intent":"Say you're glad he came, and ask why he's in favour of the hotel.","accept":["Buenas, don Arturo. Me alegra que quiera hablar conmigo. ¿Por qué está a favor del hotel?","Buenas, don Arturo. Me alegra que venga a hablar. ¿Por qué usted está a favor del hotel?","Buenas tardes. Me alegra que usted esté aquí. ¿Está a favor del hotel? ¿Por qué?"],"require":[{"type":"subjunctiveAfter","trigger":"me alegra que","within":3,"label":"after me alegra que, the verb changes: venga"},{"type":"question","label":"ask why"}],"focus":"g:subj-emotion-intro","next":"t2"},{"id":"t2","npc":"Porque mi tienda casi no vende. Qué bueno que lleguen más personas al barrio.","npcEn":"Because my shop hardly sells anything. It's great that more people are coming to the neighbourhood.","intent":"Say you understand, but you don't think the tourists will buy in his shop.","accept":["Entiendo, pero no creo que los turistas compren en su tienda.","Lo entiendo, don Arturo, pero no creo que el hotel traiga clientes a su tienda.","Entiendo. No creo que ellos compren aquí, porque el hotel tendrá restaurante."],"require":[{"type":"regex","pattern":"\\bno (creo|pienso|me parece) que","flags":"i","label":"say you don't think so: no creo que..."},{"type":"subjunctiveAfter","trigger":"que","within":4,"label":"after no creo que, the verb changes: compren"}],"focus":"g:subj-opinion-negated","next":"t3"},{"id":"t3","npc":"¿Cómo? ¿Usted dice que mi tienda no es buena?","npcEn":"What? Are you saying my shop isn't any good?","intent":"Say no, you don't think that: his shop is the best in the barrio.","accept":["No, para nada. Su tienda es la mejor del barrio.","No, don Arturo. No creo que su tienda sea mala, al contrario.","No, para nada. Su tienda es la mejor de La Candelaria."],"require":[{"type":"negation","label":"start by saying no"}],"focus":"g:subj-opinion-negated","next":"t4"},{"id":"t4","npc":"Ah, bueno. Pero lo viejo no dura, joven. Lo importante es que el barrio cambie, ¿no?","npcEn":"Ah, good. But old things don't last, young man. What matters is that the neighbourhood changes, right?","intent":"Say what matters is that the change is good for everyone.","accept":["Lo importante es que el cambio ayude a todos.","Sí, pero lo importante es que todos ganen, no solo Altamira.","Lo importante es que el barrio cambie, pero para bien."],"require":[{"type":"regex","pattern":"\\blo importante\\b","flags":"i","label":"start with lo importante"},{"type":"subjunctiveAfter","trigger":"es que","within":4,"label":"after lo importante es que, the verb changes: sea"}],"focus":"g:lo-adjective","next":"t5"},{"id":"t5","npc":"Entonces tenemos algo en común. ¿Quiere que vayamos juntos a la alcaldía con otra idea?","npcEn":"Then we have something in common. Do you want us to go to the alcaldía together with another idea?","intent":"Say it sounds good to you, and offer him a coffee.","accept":["Me parece muy bien. Estoy a favor de ir juntos. ¿Le sirvo un tinto?","Claro, me parece muy bien. ¿Quiere un tinto?","Sí, don Arturo. Estoy a favor de proponer algo juntos. Lo invito a un tinto."],"require":[{"type":"containsAny","words":["me parece muy bien","a favor","de acuerdo"],"label":"say it sounds good: me parece muy bien"}],"focus":"p:me-parece-bien-que","next":null}],"r":["g:gender-articles","g:lo-adjective","g:stem-boot","g:subj-emotion-intro","g:subj-opinion-negated","g:subj-wanting","g:that-clauses","p:me-parece-bien-que"],"d":null,"spare":true},
{"id":"sc-u28-f","unit":"u28","band":"B1","title":"Window number twelve","brief":"You're Tomás, at a counter in the alcaldía with a ticket in your hand. The clerk is a stranger and an official, so use usted. Explain your position and your idea, politely and clearly.","turns":[{"id":"t1","npc":"Siguiente, por favor. Dígame, ¿qué necesita?","npcEn":"Next, please. Tell me, what do you need?","intent":"Say you came to propose a solution, and that it's important that the alcaldía listens to the neighbours.","accept":["Buenas tardes. Vengo a proponer una solución. Es importante que la alcaldía escuche a los vecinos.","Buenas. Quiero proponer una solución para la esquina del café. Es importante que escuchen a los vecinos.","Buenas tardes, señora. Vengo a proponer algo. Es importante que ustedes escuchen a la comunidad."],"require":[{"type":"regex","pattern":"propon\\w+","flags":"i","label":"say you came to propose something"},{"type":"subjunctiveAfter","trigger":"es importante que","within":4,"label":"after es importante que, the verb changes: escuche"}],"focus":"g:subj-value","next":"t2"},{"id":"t2","npc":"Muy bien. Necesito su posición por escrito. ¿Está a favor o en contra del hotel?","npcEn":"Very well. I need your position in writing. Are you for or against the hotel?","intent":"Say you're against it, and you don't think a hotel is best for that corner.","accept":["Estoy en contra. No creo que un hotel sea lo mejor para esa esquina.","Estoy en contra, señora. No creo que el hotel sea lo mejor para el barrio.","Estoy en contra del hotel, porque no me parece que sea lo mejor para esa esquina."],"require":[{"type":"containsAny","words":["en contra"],"label":"say you're en contra"},{"type":"regex","pattern":"\\bno (creo|pienso|me parece) que","flags":"i","label":"say you don't think so: no creo que..."}],"focus":"p:estar-a-favor-de","next":"t3"},{"id":"t3","npc":"Anotado. ¿Y qué propone usted? Una solución real, por favor.","npcEn":"Noted. And what do you propose? A real solution, please.","intent":"Say you've been thinking about a library for the community.","accept":["Pienso en una biblioteca para la comunidad.","Pensé en una biblioteca con un café para los vecinos.","Estoy pensando en una biblioteca para la comunidad."],"require":[{"type":"regex","pattern":"\\b(pienso|pensando|pensé|pensamos) en\\b","flags":"i","label":"say you're thinking of it: pienso en..."},{"type":"containsWord","word":"biblioteca","label":"mention the library"}],"focus":"p:pensar-en","next":"t4"},{"id":"t4","npc":"Qué buena idea. Pero hay un problema: la ventanilla cierra a las cinco, y ya son las cinco y diez.","npcEn":"What a good idea. But there's a problem: the window closes at five, and it's already ten past.","intent":"Say it's a pity, and politely ask if she can take your idea anyway.","accept":["Es una pena que cierre tan temprano. ¿Podría recibir mi idea?","Qué pena. ¿Podría recibirla ahora, por favor?","Es una pena, señora. ¿Puede recibirla, por favor?"],"require":[{"type":"regex","pattern":"\\b(una pena|qué pena|lástima)\\b","flags":"i","label":"say it's a pity: es una pena..."},{"type":"question","label":"ask politely"}],"focus":"g:subj-value","next":"t5"},{"id":"t5","npc":"Está bien, por esta vez. Aquí tiene su número, el 214. Y no le digo más: aquí nadie opina.","npcEn":"All right, just this once. Here's your number, 214. And I won't say more: nobody here gives opinions.","intent":"Thank her, and ask what she herself thinks of your idea.","accept":["Muchas gracias. Y usted, ¿qué opina de mi idea?","Gracias, señora. ¿Qué piensa usted de la biblioteca?","Muchas gracias. Pero dígame, ¿qué opina usted de mi idea?"],"require":[{"type":"question","label":"ask a question"},{"type":"regex","pattern":"qué (opina|piensa|cree)","flags":"i","label":"ask: ¿qué opina usted?"}],"focus":"p:que-opinas-de","next":null}],"r":["g:estar-location-states","g:gender-articles","g:por-para-1","g:present-ar","g:questions","g:stem-boot","g:subj-value","p:estar-a-favor-de","p:pensar-en","p:que-opinas-de"],"d":199,"spare":true},
{"id":"sc-u29-a","unit":"u29","band":"B1","title":"Not for sale, maybe","brief":"You're Tomás. Altamira has made an offer for the café, and Vale says no way. She's your friend and works beside you, so use tú. Say what you doubt, concede a point and keep it friendly.","turns":[{"id":"t1","npc":"Altamira quiere comprar el café. Yo digo que ni hablar. ¿Tú qué piensas?","npcEn":"Altamira wants to buy the café. I say no way. What do you think?","intent":"Tell her you doubt that you can win the fight against Altamira.","accept":["Dudo que podamos ganar, Vale.","Sinceramente, dudo que ganemos contra ellos.","Yo dudo que le ganemos a Altamira."],"require":[{"type":"subjunctiveAfter","trigger":"dudo que","within":3,"label":"after dudo que, the verb changes: ganemos, podamos"}],"focus":"g:subj-doubt","next":"t2"},{"id":"t2","npc":"¿Tú crees? Yo creo que todavía tenemos una oportunidad.","npcEn":"You think so? I think we still have a chance.","intent":"Say that perhaps she's right, though you're not sure (use quizás with the subjunctive), but that you want to hear the offer.","accept":["Quizás tengas razón, pero quiero escuchar la oferta.","Pues quizás tengas razón, Vale, pero la oferta me interesa.","Quizás sea así, pero tenemos que escuchar la oferta."],"require":[{"type":"subjunctiveAfter","trigger":"quizás","within":3,"label":"after quizás, the verb changes: tengas, sea"}],"focus":"g:quizas-a-lo-mejor","next":"t3"},{"id":"t3","npc":"Qué raro. El abogado no contestó ayer. ¿Dónde estaría?","npcEn":"How strange. The lawyer didn't answer yesterday. Where could he have been?","intent":"Guess where the lawyer was yesterday: say he was probably in another meeting.","accept":["Estaría en otra reunión.","Estaría en su oficina con otro cliente.","Yo creo que estaría en una reunión."],"require":[{"type":"verbFormAny","inf":"estar","tense":"condicional","label":"to guess about the past, use estaría"}],"focus":"g:conditional-past-guess","next":"t4"},{"id":"t4","npc":"Lo peor es que el abogado cobra mucho y casi no tenemos pruebas. Yo creo que debemos vender.","npcEn":"The worst part is that the lawyer charges a lot and we have almost no proof. I say we sell.","intent":"Concede that she's right and the lawyer costs a lot, but say you don't agree on selling.","accept":["Tienes razón, el abogado cobra mucho, pero no estoy de acuerdo en vender.","Tienes razón, el abogado cuesta mucho. Pero no estoy de acuerdo en vender el café.","Sí, es cierto, pero no estoy de acuerdo en vender."],"require":[{"type":"containsAny","words":["tienes razón","es cierto","es verdad"],"label":"concede her point first: tienes razón"},{"type":"containsAny","words":["no estoy de acuerdo"],"label":"say you don't agree: no estoy de acuerdo"}],"focus":"p:tener-razon-pero","next":"t5"},{"id":"t5","npc":"Bueno, no peleemos más. ¿Café con leche o tinto?","npcEn":"OK, let's not fight any more. Coffee with milk or black coffee?","intent":"Say you don't mind which one, and thank her.","accept":["Me da igual, Vale. Gracias.","Gracias. Me da lo mismo, tú decides.","Me da igual, de verdad. Gracias por todo."],"require":[{"type":"containsAny","words":["me da igual","me da lo mismo"],"label":"say you don't mind: me da igual"}],"focus":"p:dar-igual","next":null}],"r":["g:conditional-past-guess","g:gender-articles","g:questions","g:quizas-a-lo-mejor","g:subj-doubt","g:that-clauses","p:dar-igual","p:tener-razon-pero"],"d":272},
{"id":"sc-u29-b","unit":"u29","band":"B1","title":"The permits","brief":"You're Tomás, talking with Mariana, the journalist. She has checked Altamira's permits and has doubts. She's your age and a friend, so use tú. Agree with her, guess, and push back on a rumour.","turns":[{"id":"t1","npc":"Revisé los papeles de Altamira. Dudo que sean legales. ¿Tú qué piensas?","npcEn":"I checked Altamira's papers. I doubt they're legal. What do you think?","intent":"Say you agree with her, and that you doubt it too.","accept":["Estoy de acuerdo contigo, Mariana. Yo también dudo que sean legales.","Sí, estoy de acuerdo. Dudo que todo sea legal.","Estoy de acuerdo contigo. Yo también dudo que estén bien."],"require":[{"type":"containsAny","words":["de acuerdo"],"label":"say you agree: estoy de acuerdo"},{"type":"subjunctiveAfter","trigger":"dudo que","within":3,"label":"after dudo que, the verb changes: sean"}],"focus":"p:estar-de-acuerdo-con-en","next":"t2"},{"id":"t2","npc":"Alguien firmó todo en un solo día. ¿Quién sería?","npcEn":"Someone signed everything in a single day. Who could it have been?","intent":"Guess who it was: say it was probably a friend of Altamira.","accept":["Sería un amigo de Altamira.","Sería alguien de la alcaldía, un amigo de Altamira.","Yo creo que sería algún amigo suyo."],"require":[{"type":"verbFormAny","inf":"ser","tense":"condicional","label":"to guess about the past, use sería"}],"focus":"g:conditional-past-guess","next":"t3"},{"id":"t3","npc":"Puede ser. Pero no tengo pruebas todavía. ¿Publico la noticia ya?","npcEn":"Could be. But I don't have proof yet. Do I publish the story now?","intent":"Say that maybe it's better to wait (use a lo mejor).","accept":["A lo mejor es mejor esperar.","A lo mejor debemos esperar unos días.","A lo mejor debes esperar un poco más."],"require":[{"type":"regex","pattern":"a lo mejor","flags":"i","label":"say maybe with a lo mejor"}],"focus":"g:quizas-a-lo-mejor","next":"t4"},{"id":"t4","npc":"Vale me dijo que tú ya decidiste vender el café. ¿Es verdad?","npcEn":"Vale told me you've already decided to sell the café. Is it true?","intent":"Tell her she's wrong: you don't want to sell the café.","accept":["Te equivocas, Mariana. No quiero vender el café.","Creo que te equivocas. Yo no quiero vender.","No quiero vender el café. Vale se equivocó, Mariana."],"require":[{"type":"regex","pattern":"equivoc","flags":"i","label":"say she's wrong: te equivocas, estás equivocada"},{"type":"negation","label":"say you don't want to sell"}],"focus":"p:equivocarse","next":"t5"},{"id":"t5","npc":"Entonces fue un error. Gracias, Tomás. ¿Nos vemos mañana en el café?","npcEn":"Then it was a mistake. Thanks, Tomás. Shall we meet tomorrow at the café?","intent":"Say that's fine by you and tell her to come at ten for a coffee.","accept":["Me parece bien. Ven a las diez y te regalo un tinto.","Sí, me parece bien. Te espero a las diez con un tinto.","Me parece bien, Mariana. Nos vemos a las diez en el café."],"require":[{"type":"containsAny","words":["me parece bien"],"label":"say it's fine by you: me parece bien"}],"focus":"x:dar-igual-parecer-bien","next":null}],"r":["g:conditional-past-guess","g:gender-articles","g:present-ar","g:preterite-ar","g:questions","g:quizas-a-lo-mejor","g:ser-identity","g:that-clauses","p:equivocarse","p:estar-de-acuerdo-con-en","x:dar-igual-parecer-bien"],"d":369},
{"id":"sc-u29-c","unit":"u29","band":"B1","title":"Both of you","brief":"You're Tomás. Don Hernando, the retired taxi driver, has heard you and Vale argued. He is much older and courtly, so use usted with him. Answer his questions and keep the peace.","turns":[{"id":"t1","npc":"Tomás, ¿qué tal? Usted y Vale discutieron hoy, ¿verdad?","npcEn":"Tomás, how are you? You and Vale argued today, didn't you?","intent":"Say yes, you argued, and that you doubt Vale is right.","accept":["Sí, don Hernando. Dudo que Vale tenga razón.","Sí, es cierto. Discutimos, y dudo que ella tenga razón.","Sí, discutimos sobre Altamira. Yo dudo que ella tenga razón."],"require":[{"type":"subjunctiveAfter","trigger":"dudo que","within":3,"label":"after dudo que, the verb changes: tenga"}],"focus":"g:subj-doubt","next":"t2"},{"id":"t2","npc":"Yo creo que los dos tienen razón. Es posible que ella vea el dinero y usted vea el café de su abuela.","npcEn":"I think you're both right. It's possible she sees the money and you see your grandmother's café.","intent":"Say it's possible he is right (es posible que).","accept":["Es posible que tenga razón.","Sí, es posible que los dos tengamos razón.","Es posible que usted tenga razón, señor."],"require":[{"type":"subjunctiveAfter","trigger":"es posible que","within":3,"label":"after es posible que, the verb changes: tenga, tengamos"}],"focus":"g:subj-doubt","next":"t3"},{"id":"t3","npc":"Dudo que ustedes dos almuercen cuando discuten. ¿Ya almorzó usted? ¿Y adónde se fue Vale después?","npcEn":"I doubt you two have lunch when you argue. Have you had lunch? And where did Vale go afterwards?","intent":"Say you haven't had lunch, and guess that afterwards Vale was probably in the kitchen.","accept":["No, no almorcé. Vale estaría en la cocina, creo.","No almorcé. Y Vale estaría en la cocina con sus postres.","Todavía no almorcé. Vale estaría en la cocina, supongo."],"require":[{"type":"verbFormAny","inf":"estar","tense":"condicional","label":"to guess, use estaría"},{"type":"negation","label":"say you haven't eaten"}],"focus":"g:conditional-past-guess","next":"t4"},{"id":"t4","npc":"Entonces tengo una idea: primero comen y después hablan. ¿Está de acuerdo?","npcEn":"Then I have an idea: first you eat and then you talk. Do you agree?","intent":"Say you agree, and that you don't mind where you eat.","accept":["Estoy de acuerdo, señor. Me da igual el lugar.","Sí, estoy de acuerdo con usted. Me da lo mismo el lugar.","Estoy de acuerdo con usted. Me da igual comer aquí o allá."],"require":[{"type":"containsAny","words":["de acuerdo"],"label":"say you agree: estoy de acuerdo"},{"type":"containsAny","words":["me da igual","me da lo mismo"],"label":"say you don't mind: me da igual"},{"type":"avoidsAny","words":["eres","tú","tienes"],"label":"use usted with Hernando"}],"focus":"p:dar-igual","next":"t5"},{"id":"t5","npc":"Perfecto. Yo invito el primer tinto. ¿Cree que Vale va a venir a comer?","npcEn":"Perfect. The first coffee is on me. Do you think Vale will come and eat?","intent":"Thank him, and say you suppose she'll come (use supongo que), using usted.","accept":["Gracias, don Hernando. Supongo que viene, tiene hambre.","Muy amable, señor. Supongo que va a venir.","Muchas gracias. Supongo que sí viene, pero no estoy seguro."],"require":[{"type":"containsAny","words":["supongo que"],"label":"say what you guess with supongo que"},{"type":"avoidsAny","words":["venga"],"label":"a guess keeps the ordinary form: supongo que viene"},{"type":"avoidsAny","words":["eres","tú","tienes"],"label":"use usted with Hernando"}],"focus":"x:supongo-vs-dudo","next":null}],"r":["g:conditional-past-guess","g:gender-articles","g:present-ar","g:present-er-ir","g:questions","g:subj-doubt","g:subj-wanting","g:that-clauses","p:dar-igual","x:supongo-vs-dudo"],"d":null,"spare":true},
{"id":"sc-u30-a","unit":"u30","band":"B1","title":"Doña Gloria's questions","brief":"You're Tomás, spending your day off with doña Gloria, an old friend of your grandmother's. She wants to know how you are now that you have said no to Altamira. She is much older than you, so use usted.","turns":[{"id":"t1","npc":"Mijo, qué alegría verlo. Me dicen que usted le dijo que no a Altamira. ¿Cómo está?","npcEn":"Son, how lovely to see you. They tell me you said no to Altamira. How are you?","intent":"Say you are fine, but it bothers you that Altamira wants to buy the block.","accept":["Bien, pero me molesta que Altamira quiera comprar la cuadra.","Estoy bien, pero me molesta que Altamira quiera comprar todo.","Bien. Me molesta que quieran comprar toda la cuadra."],"require":[{"type":"subjunctiveAfter","trigger":"molesta que","within":3,"label":"after me molesta que, the verb changes: quiera"}],"focus":"g:subj-emotion","next":"t2"},{"id":"t2","npc":"¿Y los vecinos? Yo los veo muy tristes.","npcEn":"And the neighbours? They look very sad to me.","intent":"Say it makes you sad that the neighbours might sell their houses or leave.","accept":["Me da pena que los vecinos vendan sus casas.","A mí me da pena que los vecinos se vayan.","Me da pena que vendan todo y se vayan."],"require":[{"type":"regex","pattern":"\\b(me da (mucha )?(pena|tristeza|lástima)|qu[eé] (pena|lástima)|siento( mucho)?|lamento) que\\b","flags":"i","label":"me da pena que, siento que"},{"type":"anyVerbInTense","tense":"presubj","label":"after me da pena que, the verb changes: vendan, se vayan"}],"focus":"p:me-da-pena-que","next":"t3"},{"id":"t3","npc":"Rosa me decía que usted era un niño muy alegre. ¿Todavía es así?","npcEn":"Rosa used to tell me you were a very cheerful boy. Are you still like that?","intent":"Say you have changed: say what makes you sad or nervous now, with me pongo and cuando.","accept":["No tanto. Ahora me pongo triste cuando pienso en mi abuela.","Ya no. Me pongo triste cuando veo la silla de Rosa.","No mucho. Me pongo muy serio cuando alguien habla de Altamira."],"require":[{"type":"regex","pattern":"\\bme pongo\\b","flags":"i","label":"say how you react now: me pongo + a feeling"},{"type":"regex","pattern":"\\bcuando\\b","flags":"i","label":"say when: cuando..."}],"focus":"p:me-pongo-triste-cuando","next":"t4"},{"id":"t4","npc":"¿Y usted se va a quedar en Bogotá, o se va para Toronto?","npcEn":"And are you going to stay in Bogotá, or are you going back to Toronto?","intent":"Say you are staying in Bogotá, and that you are not leaving.","accept":["Me quedo en Bogotá. No me voy.","Me voy a quedar en Bogotá. No me voy para Toronto.","Me quedo aquí. No me voy a ir."],"require":[{"type":"regex","pattern":"\\bme qued|\\bquedarme\\b|\\bvoy a quedar","flags":"i","label":"say you are staying: me quedo"},{"type":"regex","pattern":"\\bno me voy\\b","flags":"i","label":"say you are not leaving: no me voy"}],"focus":"g:se-meaning-change","next":"t5"},{"id":"t5","npc":"Ay, mijo, qué alivio. Rosa estaría muy contenta.","npcEn":"Oh, son, what a relief. Rosa would be very happy.","intent":"Thank her, and say you are glad that she is here with you.","accept":["Gracias, de verdad. Me alegro de que usted esté aquí.","Muchas gracias. Me alegro de que usted esté conmigo.","Gracias. Me alegro de que usted sea mi amiga."],"require":[{"type":"regex","pattern":"\\bme alegr(a|o de) que\\b","flags":"i","label":"me alegra que or me alegro de que"},{"type":"anyVerbInTense","tense":"presubj","label":"after me alegra que, the verb changes: esté, sea"}],"focus":"p:alegrarse-de-que","next":null}],"r":["g:adjective-agreement","g:direct-objects","g:estar-location-states","g:gender-articles","g:se-meaning-change","g:subj-emotion","g:that-clauses","p:alegrarse-de-que","p:me-da-pena-que","p:me-pongo-triste-cuando"],"d":null},
{"id":"sc-u30-b","unit":"u30","band":"B1","title":"Day off","brief":"You're Tomás, and it's your day off. Vale calls you from the café, bored. Explain why you're home, react to how she feels and own up to the way you've changed lately. She's your friend, so use tú.","turns":[{"id":"t1","npc":"Oye, ¿dónde estás? Hoy no viniste al café.","npcEn":"Hey, where are you? You didn't come to the café today.","intent":"Say you stayed home today because it's your day off.","accept":["Me quedé en casa porque hoy no trabajo.","Hoy me quedé en casa. Es mi día libre.","Me quedé en casa, no trabajo hoy."],"require":[{"type":"regex","pattern":"me qued","flags":"i","label":"say you stayed home with quedarse: me quedé"}],"focus":"g:se-meaning-change","next":"t2"},{"id":"t2","npc":"Ah, claro. Aquí me aburro sin ti.","npcEn":"Oh, right. I get bored here without you.","intent":"Say you are sorry that she is bored (it gives you sadness).","accept":["Me da pena que te aburras.","Me da pena que te aburras sola.","Qué pena que te aburras."],"require":[{"type":"regex","pattern":"\\b(me da (mucha )?(pena|tristeza|lástima)|qu[eé] (pena|lástima)|siento( mucho)?|lamento) que\\b","flags":"i","label":"me da pena que, siento que"},{"type":"anyVerbInTense","tense":"presubj","label":"after me da pena que, the verb changes: te aburras"}],"focus":"p:aburrir-aburrirse","next":"t3"},{"id":"t3","npc":"Estás muy serio estos días. ¿Qué te pasó?","npcEn":"You've been very serious these days. What happened to you?","intent":"Admit you became more serious (use volverse or ponerse), because you care about the café.","accept":["Es verdad, me volví muy serio. Quiero mucho el café.","Sí, me puse serio. Quiero mucho este café.","Me volví muy serio, pero es porque quiero el café."],"require":[{"type":"regex","pattern":"\\bme (volv|pus|hic)","flags":"i","label":"say how you changed with a verb of change: me volví, me puse"}],"focus":"g:verbs-of-change","next":"t4"},{"id":"t4","npc":"¿Y qué vas a hacer hoy? ¿Te vas a quedar en casa todo el día?","npcEn":"And what are you going to do today? Are you going to stay home all day?","intent":"Say no, you are leaving for downtown, and ask her to come after work.","accept":["No, ya me voy al centro. ¿Quieres venir después del trabajo?","No, me voy al centro un rato. ¿Vienes después del trabajo?","No me quedo, me voy al centro. ¿Quieres venir después?"],"require":[{"type":"regex","pattern":"\\bme voy\\b","flags":"i","label":"say you are leaving with irse: me voy"},{"type":"question","label":"ask her to come: a question"}],"focus":"x:ir-irse","next":"t5"},{"id":"t5","npc":"Sí, claro. Qué alivio. Pensé que estabas bravo conmigo.","npcEn":"Yes, of course. What a relief. I thought you were angry with me.","intent":"Tell her you are not angry with her, and say goodbye.","accept":["Para nada. No estoy bravo contigo. Hasta luego.","No, no estoy bravo contigo. Nos vemos en el centro.","No estoy bravo contigo. Nos vemos luego.","No, no estoy enojado contigo. Chao."],"require":[{"type":"negation","label":"say you are NOT angry: no estoy bravo"},{"type":"regex","pattern":"contigo","flags":"i","label":"with you: bravo contigo"}],"focus":"p:enojarse-con","next":null}],"r":["g:estar-location-states","g:gender-articles","g:prep-pronouns","g:preterite-ar","g:questions","g:se-meaning-change","g:verbs-of-change","p:aburrir-aburrirse","p:enojarse-con","x:ir-irse"],"d":null},
{"id":"sc-u30-c","unit":"u30","band":"B1","title":"Closing time","brief":"You're Tomás. The café is closing and Vale stays behind, scared about what Altamira could do. Listen to her, tell her what worries you, say how you've changed and cheer her up. She's your friend, so use tú.","turns":[{"id":"t1","npc":"Tomás, ¿tienes un minuto? No puedo dejar de pensar en el café. Tengo mucho miedo.","npcEn":"Tomás, do you have a minute? I can't stop thinking about the café. I'm very scared.","intent":"Say of course, and that you imagine how scared she is.","accept":["Claro que sí. Me imagino, qué miedo.","Claro, Vale. Me imagino, yo también tengo miedo.","Sí, claro. Me imagino que no dormiste nada."],"require":[{"type":"regex","pattern":"me imagino","flags":"i","label":"use the chunk: me imagino"}],"focus":"c:me-imagino","next":"t2"},{"id":"t2","npc":"Es que este café es mi vida. Si lo perdemos, ¿dónde voy a trabajar?","npcEn":"It's just that this café is my life. If we lose it, where am I going to work?","intent":"Say you feel sorry that she is so sad (or doesn't sleep, or works so much).","accept":["A mí también me da pena. Me da pena que estés tan triste.","Me da pena que no duermas, Vale.","Yo también tengo miedo, y me da pena que trabajes tanto."],"require":[{"type":"regex","pattern":"\\b(me da (mucha )?(pena|tristeza|lástima)|qu[eé] (pena|lástima)|siento( mucho)?|lamento) que\\b","flags":"i","label":"me da pena que, siento que"},{"type":"anyVerbInTense","tense":"presubj","label":"after me da pena que, the verb changes: estés, duermas, trabajes"}],"focus":"p:me-da-pena-que","next":"t3"},{"id":"t3","npc":"Y ayer, con el abogado, no dijiste nada. ¿Qué te pasó?","npcEn":"And yesterday, with the lawyer, you didn't say a thing. What happened to you?","intent":"Say you were left speechless (use quedarse) when the lawyer talked about the money.","accept":["Me quedé sin palabras cuando habló de la plata.","No sé, me quedé frío. Me dio miedo.","Me quedé sin palabras cuando dijo el precio."],"require":[{"type":"regex","pattern":"\\bme qued","flags":"i","label":"say how you reacted with quedarse: me quedé sin palabras"}],"focus":"g:verbs-of-change","next":"t4"},{"id":"t4","npc":"Yo también cambié. Antes me iba temprano, y ahora me quedo hasta tarde porque no puedo dormir.","npcEn":"I've changed too. I used to leave early, and now I stay until late because I can't sleep.","intent":"Cheer her up: tell her it will be fine, you'll see.","accept":["Ánimo, Vale. Ya verás que todo sale bien.","No te preocupes, ya verás que todo sale bien.","Tranquila, ya verás que todo sale bien. Estamos juntos."],"require":[{"type":"regex","pattern":"(ya ver[aá]s.*\\bbien\\b|\\bbien\\b.*ya ver[aá]s)","flags":"i","label":"say it will be fine: ya verás que todo sale bien"}],"focus":"c:ya-veras-que-todo-sale-bien","next":"t5"},{"id":"t5","npc":"Gracias, Tomás. Qué alivio hablar contigo. ¿Quieres un tinto antes de irnos?","npcEn":"Thanks, Tomás. What a relief to talk to you. Do you want a coffee before we go?","intent":"Say yes, and that you are glad she is here.","accept":["Sí, gracias. Me alegro de que estés aquí.","Claro que sí. Me alegro de que hablemos.","Con gusto. Me alegro de que seas mi amiga."],"require":[{"type":"regex","pattern":"\\bme alegr(a|o de) que\\b","flags":"i","label":"me alegra que or me alegro de que"},{"type":"anyVerbInTense","tense":"presubj","label":"after me alegra que, the verb changes: estés, hablemos, seas"}],"focus":"p:alegrarse-de-que","next":null}],"r":["c:me-imagino","c:ya-veras-que-todo-sale-bien","g:gender-articles","g:preterite-ar","g:questions","g:stem-boot","g:verb-infinitive","g:verbs-of-change","p:alegrarse-de-que","p:me-da-pena-que"],"d":556,"spare":true},
{"id":"sc-u31-a","unit":"u31","band":"B1","title":"Before 1978","brief":"You're Tomás. Mariana, the journalist, has come by the café to hear what happened between Rosa and Joaquín. Tell her the story in order, starting from before the fight, and finish with what you understood in the end. She's your friend, so use tú.","turns":[{"id":"t1","npc":"Mariana: Tomás, ya leíste las cartas. ¿Cómo estaban las cosas en 1978?","npcEn":"Mariana: Tomás, you've read the letters. How were things in 1978?","intent":"Say that by 1978 Rosa and Joaquín had already bought the building.","accept":["En 1978 Rosa y Joaquín ya habían comprado el edificio.","Para 1978, ya habían comprado el edificio juntos.","Ya habían comprado el edificio cuando todo pasó."],"require":[{"type":"anyVerbInTense","tense":"plusc","label":"before 1978: había comprado / habían comprado"}],"focus":"g:pluperfect","next":"t2"},{"id":"t2","npc":"Mariana: ¿Y cómo lo pagaron?","npcEn":"Mariana: And how did they pay for it?","intent":"Say they paid with their parents' money, but Joaquín had borrowed money and couldn't pay it back.","accept":["Con la plata de sus padres, pero Joaquín había pedido plata prestada y no podía pagarla.","Pagaron con la plata de sus papás. Pero Joaquín había pedido plata y no podía devolverla.","Con la plata de sus padres. Joaquín había pedido más plata y no podía pagarla."],"require":[{"type":"anyVerbInTense","tense":"plusc","label":"the loan came first: había pedido"}],"focus":"g:pluperfect","next":"t3"},{"id":"t3","npc":"Mariana: ¿Y qué pasó esa noche?","npcEn":"Mariana: And what happened that night?","intent":"Tell what happened in order: he wanted to sell, Rosa refused, they fought, and he left. Use entonces, luego, de repente or de pronto.","accept":["Joaquín quiso vender. Rosa no aceptó, entonces se pelearon y él se fue esa noche.","Primero Joaquín quiso vender el edificio. Rosa no quiso y luego se pelearon. Esa misma noche él se fue.","Joaquín quería vender, pero Rosa no aceptó. De repente empezaron a gritar y él se fue."],"require":[{"type":"containsAny","words":["entonces","luego","de repente","de pronto"],"label":"link the events: entonces, luego or de repente"},{"type":"anyVerbInTense","tense":"preterito","label":"the events themselves use the preterite"}],"focus":"p:entonces-de-repente","next":"t4"},{"id":"t4","npc":"Mariana: Y tú, ¿qué sentiste al terminar la última carta?","npcEn":"Mariana: And you, how did you feel when you finished the last letter?","intent":"Say that in the end you understood that Rosa never stopped missing her brother. Open with al final.","accept":["Al final entendí que Rosa nunca dejó de extrañar a su hermano.","Al final, entendí que ella extrañaba a su hermano todos los días.","Al final entendí que Rosa extrañaba mucho a Joaquín."],"require":[{"type":"containsAny","words":["al final"],"label":"close the story with al final"}],"focus":"p:al-final-en-resumen","next":"t5"},{"id":"t5","npc":"Mariana: Gracias por contármelo. Ya es tarde.","npcEn":"Mariana: Thanks for telling me. It's late.","intent":"Say the two of you have been talking for two hours, and invite her for a coffee.","accept":["Llevamos dos horas hablando. ¿Me acompañas a tomar un tinto?","Ya llevamos dos horas hablando, ¿quieres un tinto?","Llevamos dos horas hablando. ¿Tomamos un café?"],"require":[{"type":"verbFormAny","inf":"llevar","tense":"presente","label":"how long you have been at it: llevamos dos horas"},{"type":"question"}],"focus":"p:llevar-tiempo-gerundio","next":null}],"r":["g:direct-objects","g:gender-articles","g:pluperfect","g:preterite-er-ir","g:questions","p:al-final-en-resumen","p:entonces-de-repente","p:llevar-tiempo-gerundio"],"d":279},
{"id":"sc-u31-b","unit":"u31","band":"B1","title":"What Hernando said","brief":"You're Tomás. Jhon Fredy saw you talking with Hernando for half an hour, and he missed the night you all read the letters. Tell him what Hernando said: when you report it, the verbs shift back into the past. He's your friend, so use tú.","turns":[{"id":"t1","npc":"Jhon Fredy: Oye, te vi con Hernando media hora. ¿Qué te dijo?","npcEn":"Jhon Fredy: Hey, I saw you with Hernando for half an hour. What did he tell you?","intent":"Say he told you that Rosa wrote to Joaquín every year.","accept":["No te lo vas a creer. Me dijo que Rosa le escribía a Joaquín todos los años.","Hernando me dijo que Rosa le había escrito a Joaquín todos los años.","Me contó que Rosa le escribía todos los años a Joaquín."],"require":[{"type":"regex","pattern":"\\b(escribía|había escrito)\\b","flags":"i","label":"what he said, now in the past: escribía or había escrito"}],"focus":"g:reported-backshift","next":"t2"},{"id":"t2","npc":"Jhon Fredy: ¿Todos los años? ¿Y se las mandaba?","npcEn":"Jhon Fredy: Every year? And did she send them to him?","intent":"Say no: he told you she never sent them.","accept":["No. Me dijo que nunca se las mandaba.","Hernando me dijo que no, que ella nunca las mandaba.","No. Me contó que nunca había mandado ninguna."],"require":[{"type":"regex","pattern":"\\b(dijo|contó) que\\b","flags":"i","label":"report it with dijo que or contó que"},{"type":"negation","label":"she never sent them: nunca, ninguna"}],"focus":"g:reported-backshift","next":"t3"},{"id":"t3","npc":"Jhon Fredy: Uy. ¿Y por qué no las mandaba?","npcEn":"Jhon Fredy: Wow. And why didn't she send them?","intent":"Say you asked him the same thing, and he said she was afraid.","accept":["Le pregunté lo mismo. Me dijo que tenía miedo.","Le pregunté lo mismo, y me dijo que Rosa tenía mucho miedo.","Yo le pregunté lo mismo. Dijo que a ella le daba miedo la respuesta."],"require":[{"type":"regex","pattern":"\\b(tenía|daba) (mucho )?miedo","flags":"i","label":"what she felt, in the past: tenía miedo or le daba miedo"}],"focus":"p:miedo-a","next":"t4"},{"id":"t4","npc":"Jhon Fredy: Qué raro. Ayer en la cocina me dijo que Rosa ya no pensaba en Joaquín.","npcEn":"Jhon Fredy: That's strange. Yesterday in the kitchen he told me that Rosa no longer thought about Joaquín.","intent":"Say that's not what he told you: he told you she missed him a lot.","accept":["Pues a mí me dijo que ella lo extrañaba mucho.","No, a mí me dijo que Rosa lo extrañaba muchísimo.","A mí me contó que lo extrañaba todos los días."],"require":[{"type":"verbForm","inf":"extrañar","tense":"imperfecto","person":"él/ella","label":"what he said, in the past: extrañaba"}],"focus":"p:extranar","next":"t5"},{"id":"t5","npc":"Jhon Fredy: Entonces yo quiero leer esas cartas. Yo traigo el pan.","npcEn":"Jhon Fredy: Then I want to read those letters. I'll bring the bread.","intent":"Say yes, thanks, and that tonight the two of you will get down to reading them.","accept":["Sí, gracias. Esta noche nos ponemos a leerlas juntos.","Perfecto. Esta noche nos ponemos a leer las cartas.","Gracias. Nos ponemos a leerlas después de cerrar."],"require":[{"type":"regex","pattern":"\\bpon\\w* a leer","flags":"i","label":"start reading with ponerse a: nos ponemos a leer"}],"focus":"p:ponerse-a","next":null}],"r":["g:gender-articles","g:imperfect-habitual","g:preterite-irregular-strong","g:questions","g:reported-backshift","p:extranar","p:miedo-a","p:ponerse-a"],"d":300},
{"id":"sc-u31-c","unit":"u31","band":"B1","title":"The light at three","brief":"You're Tomás. Don Hernando, a retired taxi driver, drops by early and starts remembering the café as it was in 1978. Ask him questions and react as the story unfolds. He's much older than you, so use usted.","turns":[{"id":"t1","npc":"Hernando: Buenos días, Tomás. Hoy me acordé del café en 1978. Yo era taxista y pasaba por aquí todas las noches.","npcEn":"Hernando: Good morning, Tomás. Today I remembered the café in 1978. I was a taxi driver and I came past here every night.","intent":"Say good morning and ask him what the café was like then.","accept":["Buenos días. ¿Cómo era el café en 1978?","Buenos días. ¿Cómo era este café en esa época?","Buenos días. ¿Y cómo era el café entonces?"],"require":[{"type":"question","label":"ask him a question"},{"type":"avoidsPerson","person":"tú","label":"use usted with him, not tú"}],"focus":"g:narrative-pasts","next":"t2"},{"id":"t2","npc":"Hernando: Pequeño y siempre lleno. Rosa les servía tinto a todos y el pan salía caliente a todas horas. Pero la última noche de Joaquín, vi luz en el café a las tres de la mañana.","npcEn":"Hernando: Small and always full. Rosa served coffee to everyone and the bread came out warm at all hours. But on Joaquín's last night, I saw a light in the café at three in the morning.","intent":"Ask what he did when he saw the light on.","accept":["¿Y qué hizo usted cuando vio la luz?","¿Qué hizo usted al ver la luz?","Y usted, ¿qué hizo cuando vio la luz?"],"require":[{"type":"question","label":"ask a question"},{"type":"verbForm","inf":"hacer","tense":"preterito","person":"él/ella","label":"what did you do: qué hizo usted"}],"focus":"g:narrative-pasts","next":"t3"},{"id":"t3","npc":"Hernando: Paré el taxi. En la esquina estaba Joaquín, sin chaqueta, y le presté la mía. Después toqué la puerta. Rosa tenía una taza fría en la mano y me dijo que él no iba a volver.","npcEn":"Hernando: I stopped the taxi. Joaquín was on the corner, without a jacket, and I lent him mine. Then I knocked on the door. Rosa had a cold cup in her hand and she told me he wasn't going to come back.","intent":"Say how sad, and that you were planning to ask her about Joaquín one day, but you never did.","accept":["Qué triste. Yo pensaba preguntarle por Joaquín, pero nunca lo hice.","Qué triste. Iba a preguntarle por Joaquín, pero nunca le pregunté.","Ay, qué triste. Pensaba preguntarle por su hermano algún día, pero nunca lo hice."],"require":[{"type":"regex","pattern":"\\b(pensaba|iba a)\\b","flags":"i","label":"the plan you had: pensaba or iba a"},{"type":"regex","pattern":"\\bpero\\b","flags":"i","label":"then what got in the way: pero"}],"focus":"p:pensaba-pero","next":"t4"},{"id":"t4","npc":"Hernando: Ella se puso a llorar y yo me quedé hasta que salió el sol. Después me hizo un tinto. Años más tarde me dijo que nunca había mandado ninguna carta.","npcEn":"Hernando: She started to cry and I stayed until the sun came up. Then she made me a coffee. Years later she told me she had never sent a single letter.","intent":"Thank him, and say Rosa had never told you any of this.","accept":["Gracias. Rosa nunca me había contado nada de esto.","Muchas gracias. Mi abuela nunca me había contado eso.","Gracias por contármelo. Ella nunca me había dicho nada."],"require":[{"type":"anyVerbInTense","tense":"plusc","label":"she had never told you: nunca me había contado"}],"focus":"g:pluperfect","next":"t5"},{"id":"t5","npc":"Hernando: Era una mujer muy fuerte. Y ahora, ¿me invita un tinto, o lo pago yo?","npcEn":"Hernando: She was a very strong woman. And now, will you buy me a coffee, or do I pay?","intent":"Say of course, and that you are inviting him.","accept":["Claro que sí. Hoy lo invito yo.","Por supuesto. Lo invito a un tinto.","Con mucho gusto. Hoy lo invito yo."],"require":[{"type":"regex","pattern":"\\binvit","flags":"i","label":"say you're inviting him: lo invito"}],"focus":"g:narrative-pasts","next":null}],"r":["g:gender-articles","g:imperfect-habitual","g:imperfect-states","g:indirect-objects","g:narrative-pasts","g:pluperfect","g:present-ar","g:preterite-ar","g:preterite-er-ir","g:preterite-irregular-strong","g:reflexive-routine","g:ser-identity","p:pensaba-pero"],"d":275,"spare":true},
{"id":"sc-u32-a","unit":"u32","band":"B1","title":"Before the trial","brief":"You're Tomás, visiting the lawyer Dra. Beatriz Uribe about the building. You only met her this week, so use usted. Get her advice, promise what you will do and when, and don't sign anything yet.","turns":[{"id":"t1","npc":"Buenos días, señor Herrera. Cuénteme, ¿qué necesita?","npcEn":"Good morning, Mr. Herrera. Tell me, what do you need?","intent":"Greet her and ask what she recommends that you do before the trial.","accept":["¿Qué me recomienda que haga antes del juicio?","Buenos días, doctora. ¿Qué me aconseja que haga antes del juicio?","Buenos días. Necesito ayuda: ¿qué me recomienda que haga antes del juicio?"],"require":[{"type":"subjunctiveAfter","trigger":"que","label":"after recomienda que / aconseja que, the verb changes: haga"}],"focus":"g:subj-influence","next":"t2"},{"id":"t2","npc":"Le recomiendo que busque a Joaquín o a sus herederos esta semana. Si los encuentra, la familia puede quedarse con el edificio.","npcEn":"I recommend that you look for Joaquín or his heirs this week. If you find them, the family can keep the building.","intent":"Promise to call her when you find Joaquín.","accept":["Cuando encuentre a Joaquín, la llamo.","La llamo cuando lo encuentre.","Sí, doctora. Cuando encuentre a sus herederos, la llamo hoy mismo."],"require":[{"type":"subjunctiveAfter","trigger":"cuando","label":"after cuando, talking about the future, the verb changes: encuentre"}],"focus":"g:subj-cuando-future","next":"t3"},{"id":"t3","npc":"Muy bien. Y necesito leer todos los papeles de Rosa antes del juicio.","npcEn":"Very good. And I need to read all of Rosa's papers before the trial.","intent":"Tell her you will bring the papers tomorrow so that she can read them in good time.","accept":["Los traigo mañana para que usted los lea con tiempo.","Sí, doctora. Los traigo mañana para que los lea con tiempo.","Mañana mismo traigo todo para que usted pueda leerlo."],"require":[{"type":"subjunctiveAfter","trigger":"para que","label":"after para que (so that), the verb changes: lea"}],"focus":"g:subj-purpose-full","next":"t4"},{"id":"t4","npc":"Una cosa más. Altamira ofrece comprar su parte del edificio, y quiere una respuesta pronto.","npcEn":"One more thing. Altamira is offering to buy your share of the building, and it wants an answer soon.","intent":"Say you will not sell until the trial is over.","accept":["No voy a vender hasta que termine el juicio.","No, doctora. No firmo nada hasta que usted me diga que es seguro.","No vendo hasta que encontremos a Joaquín."],"require":[{"type":"negation"},{"type":"subjunctiveAfter","trigger":"hasta que","label":"after no... hasta que, the verb changes: termine"}],"focus":"p:no-hasta","next":"t5"},{"id":"t5","npc":"Perfecto. Confío en que todo salga bien, pero hay que moverse rápido.","npcEn":"Perfect. I'm confident everything will go well, but we have to move fast.","intent":"Say you are confident too, and thank her.","accept":["Yo también confío en que todo salga bien. Muchas gracias, doctora.","Gracias, doctora. Confío en que salga bien.","Muchas gracias por todo. Confío en que podamos ganar."],"require":[{"type":"subjunctiveAfter","trigger":"confío en que","label":"after confío en que, the verb changes: salga"}],"focus":"p:confiar-en-que","next":null}],"r":["g:gender-articles","g:present-ar","g:stem-boot","g:subj-cuando-future","g:subj-influence","g:subj-purpose-full","g:subj-wanting","g:that-clauses","g:verb-infinitive","p:confiar-en-que","p:no-hasta"],"d":null},
{"id":"sc-u32-b","unit":"u32","band":"B1","title":"Rainy-season menu","brief":"You're Tomás, closing the café with Vale. She has a plan for the rainy season and you are her partner, so use tú. Give your opinion, suggest a fix and agree on timing.","turns":[{"id":"t1","npc":"Tomás, necesito que me escuches un minuto. Tengo una idea para la temporada de lluvias.","npcEn":"Tomás, I need you to listen to me for a minute. I have an idea for the rainy season.","intent":"Say you're listening and ask what the idea is.","accept":["Te escucho. ¿Cuál es la idea?","Claro, Vale. ¿Qué idea tienes?","Dime. ¿De qué se trata?"],"require":[{"type":"question"}],"focus":"g:subj-influence","next":"t2"},{"id":"t2","npc":"Quiero que cambiemos el menú. Pan de queso caliente todo el día y chocolate con queso.","npcEn":"I want us to change the menu. Hot cheese bread all day and hot chocolate with cheese.","intent":"Say you like it, but she should do a test so that the regulars can taste it first.","accept":["Me gusta, pero haz una prueba para que los clientes la prueben primero.","Suena bien. Hagamos una prueba para que los clientes habituales la prueben.","Me parece bien. Primero haz una prueba para que Hernando la pruebe."],"require":[{"type":"subjunctiveAfter","trigger":"para que","label":"after para que (so that), the verb changes: prueben"}],"focus":"g:subj-purpose-full","next":"t3"},{"id":"t3","npc":"Hecho. ¿Y cuándo lo servimos?","npcEn":"Done. And when do we serve it?","intent":"Say you will serve it when the rainy season starts.","accept":["Lo servimos cuando empiece la temporada de lluvias.","Cuando empiece la temporada, lo servimos.","Cuando llueva de verdad, lo servimos."],"require":[{"type":"subjunctiveAfter","trigger":"cuando","label":"after cuando, talking about the future, the verb changes: empiece"}],"focus":"g:subj-cuando-future","next":"t4"},{"id":"t4","npc":"Tengo un problema. El proveedor no trae el queso hasta el lunes, y la prueba es mañana.","npcEn":"I have a problem. The supplier doesn't bring the cheese until Monday, and the test is tomorrow.","intent":"Suggest that she call another supplier today (use: te propongo que).","accept":["Te propongo que llames a otro proveedor hoy.","Entonces te propongo que llames al proveedor de la plaza.","Te propongo que busquemos otro proveedor ahora mismo."],"require":[{"type":"subjunctiveAfter","trigger":"te propongo que","label":"after te propongo que, the verb changes: llames"}],"focus":"p:te-propongo-que","next":"t5"},{"id":"t5","npc":"Qué buena idea. ¿Y sigues haciendo las cuentas todas las noches?","npcEn":"Good idea. And are you still doing the accounts every night?","intent":"Say yes, you're still doing them every night.","accept":["Sí, sigo haciendo las cuentas todas las noches.","Sí, las sigo haciendo todas las noches.","Sí, sigo haciendo las cuentas, pero ya casi termino."],"require":[{"type":"verbFormAny","inf":"seguir","tense":"presente","label":"use seguir + a gerund: sigo haciendo"}],"focus":"p:seguir-gerundio","next":"t6"},{"id":"t6","npc":"Qué bueno. Quédate a tomar un tinto conmigo, que yo lo preparo.","npcEn":"Great. Stay and have a coffee with me, I'll make it.","intent":"Accept the coffee with a friendly 'if you insist'.","accept":["Bueno, si insistes.","Bueno, si insistes. Gracias, Vale.","Bueno, si insistes. Un tinto y nada más."],"require":[{"type":"regex","pattern":"si insistes","flags":"i","label":"say bueno, si insistes"}],"focus":"c:bueno-si-insistes","next":null}],"r":["c:bueno-si-insistes","g:direct-objects","g:gender-articles","g:present-ar","g:present-er-ir","g:questions","g:subj-cuando-future","g:subj-influence","g:subj-purpose-full","g:subj-wanting","g:that-clauses","g:yo-irregular","p:seguir-gerundio","p:te-propongo-que"],"d":null},
{"id":"sc-u32-c","unit":"u32","band":"B1","title":"The list","brief":"You're Tomás, working late on the list of everything to do before the lease ends. Don Hernando, who is much older than you, drops by, so use usted. Ask for his help, make a plan with him and correct a misunderstanding.","turns":[{"id":"t1","npc":"Joven Tomás, vi que había luz. ¿Todavía está trabajando a esta hora?","npcEn":"Young Tomás, I saw there was a light on. Are you still working at this hour?","intent":"Say yes, you're still working on the list, and ask him with usted to give you a hand.","accept":["Sí, sigo con la lista. ¿Me echa una mano?","Sí, estoy terminando la lista. ¿Me echa una mano?","Sí. Hay mucho que hacer. ¿Me echa una mano con la lista?"],"require":[{"type":"regex","pattern":"me echa una mano","flags":"i","label":"ask with usted: ¿me echa una mano?"}],"focus":"c:me-echas-una-mano","next":"t2"},{"id":"t2","npc":"Con mucho gusto. ¿Qué es lo primero?","npcEn":"With pleasure. What is the first thing?","intent":"Ask him to ask his taxi friends if anyone knew Joaquín.","accept":["Le pido que pregunte a sus amigos taxistas si alguien conoció a Joaquín.","Le pido que hable con los taxistas. Alguien debe conocer a Joaquín.","Le pido que pregunte por Joaquín en la parada de taxis."],"require":[{"type":"subjunctiveAfter","trigger":"le pido que","label":"after le pido que, the verb changes: pregunte"}],"focus":"g:subj-influence","next":"t3"},{"id":"t3","npc":"Ya lo hice esta tarde. Un colega conoció a un Joaquín en Santa Marta. Lo veo el viernes.","npcEn":"I already did it this afternoon. A colleague knew a Joaquín in Santa Marta. I'm seeing him on Friday.","intent":"Ask if he can give his colleague your number when he sees him on Friday.","accept":["Cuando lo vea el viernes, ¿le da mi número?","¿Le puede dar mi número cuando lo vea el viernes?","¿Le da mi número cuando lo vea? Es importante."],"require":[{"type":"question"},{"type":"subjunctiveAfter","trigger":"cuando","label":"after cuando, talking about the future, the verb changes: vea"}],"focus":"g:subj-cuando-future","next":"t4"},{"id":"t4","npc":"Con gusto. Perdone, ¿el contrato termina este mes?","npcEn":"Gladly. Excuse me, does the lease end this month?","intent":"Say no, it ends in November, and you must find Joaquín before it ends.","accept":["No, termina en noviembre. Tenemos que encontrar a Joaquín antes de que termine.","No, hay que encontrarlo antes de que termine el contrato.","No, es en noviembre. Debemos hablar con su familia antes de que termine."],"require":[{"type":"negation"},{"type":"subjunctiveAfter","trigger":"antes de que","label":"after antes de que, the verb changes: termine"}],"focus":"g:subj-purpose-full","next":"t5"},{"id":"t5","npc":"Para eso estamos, joven. Y ahora, ¿me regala un tinto?","npcEn":"That's what we're here for, young man. And now, would you give me a coffee?","intent":"Say of course, thank him, and tell him the coffee is for him, using usted.","accept":["Claro. Gracias por todo. El tinto es para usted.","Por supuesto. Muchas gracias.","Claro que sí. Gracias por su ayuda."],"require":[{"type":"avoidsAny","words":["tú","tu","tienes","eres","gracias a ti"],"label":"use usted with Don Hernando"}],"focus":"g:subj-influence","next":null}],"r":["c:me-echas-una-mano","g:estar-location-states","g:gender-articles","g:preterite-er-ir","g:subj-cuando-future","g:subj-influence","g:subj-purpose-full"],"d":null},
{"id":"sc-u32-d","unit":"u32","band":"B1","title":"The article","brief":"You're Tomás, on the phone with your friend Mariana, a journalist. She wants to write about Altamira and the block, and you are friends, so use tú. Say yes with conditions, explain your reasons and agree on what to publish now.","turns":[{"id":"t1","npc":"Hola, Tomás. Soy Mariana. Tengo que pedirte un favor.","npcEn":"Hi, Tomás. It's Mariana. I have to ask you a favour.","intent":"Greet her and ask what she needs.","accept":["Hola, Mariana. Dime, ¿qué necesitas?","Claro. ¿Qué pasa?","Hola. ¿En qué te puedo ayudar?"],"require":[{"type":"question"}],"focus":"c:tengo-que-pedirte-un-favor","next":"t2"},{"id":"t2","npc":"Quiero escribir un artículo sobre Altamira y la cuadra. Necesito que me des una entrevista.","npcEn":"I want to write an article about Altamira and the block. I need you to give me an interview.","intent":"Say yes, but ask her not to publish it until the trial is over.","accept":["Sí, pero te pido que no lo publiques hasta que sea el juicio.","Con gusto. Te pido que no publiques nada hasta que hablemos con la abogada.","Claro, pero te pido que no lo publiques todavía."],"require":[{"type":"negation"},{"type":"subjunctiveAfter","trigger":"te pido que","label":"after te pido que, the verb changes: publiques"}],"focus":"g:subj-influence","next":"t3"},{"id":"t3","npc":"¿Y por qué esperar? Si sale ya, más gente nos apoya.","npcEn":"And why wait? If it comes out now, more people support us.","intent":"Explain that you prefer to wait so that Altamira doesn't know your plan.","accept":["Prefiero esperar para que Altamira no sepa nuestro plan.","Es mejor esperar para que ellos no sepan lo que vamos a hacer.","Quiero esperar para que Altamira no sepa nada."],"require":[{"type":"subjunctiveAfter","trigger":"para que","label":"after para que (so that), the verb changes: sepa"}],"focus":"g:subj-purpose-full","next":"t4"},{"id":"t4","npc":"Bueno, tienes razón. Pero tengo que mandar algo a mi editor el viernes.","npcEn":"OK, you're right. But I have to send something to my editor on Friday.","intent":"Suggest that you could publish only Rosa's story now and the rest after the trial.","accept":["Podríamos publicar primero la historia de Rosa y lo otro después del juicio.","Podríamos publicar ahora la historia del café y lo otro cuando termine el juicio.","Podríamos sacar primero la historia de Rosa. Lo otro puede esperar."],"require":[{"type":"regex","pattern":"podr[ií]amos","flags":"i","label":"suggest it softly: podríamos + infinitive"}],"focus":"p:podriamos-deberiamos","next":"t5"},{"id":"t5","npc":"Me encanta. Una cosa: ¿te importaría salir en una foto con Simón?","npcEn":"I love it. One thing: would you mind being in a photo with Simón?","intent":"Say you don't mind at all and you're happy to (careful: after te importaría, a yes starts with no).","accept":["No, para nada. Con gusto.","No, para nada. Pero Simón va a querer hablar.","No, no me importa. Con gusto."],"require":[{"type":"regex","pattern":"^\\s*no\\b","flags":"i","label":"after te importaría, agree with no: No, para nada"}],"focus":"p:te-importaria-inf","next":null}],"r":["c:tengo-que-pedirte-un-favor","g:gender-articles","g:present-ar","g:stem-boot","g:subj-influence","g:subj-purpose-full","g:verb-infinitive","g:yo-irregular","p:podriamos-deberiamos","p:te-importaria-inf"],"d":null,"spare":true},
{"id":"sc-u32-e","unit":"u32","band":"B1","title":"A loan for the café","brief":"You're Tomás at the bank, asking about a loan for the café. The loan officer is a stranger, so use usted. Explain what you need the money for, ask for clarification and say what you'll do next.","turns":[{"id":"t1","npc":"Buenos días. Dígame, ¿en qué le puedo ayudar?","npcEn":"Good morning. Tell me, how can I help you?","intent":"Greet her and say you want to ask for a loan for the café.","accept":["Buenos días. Quiero pedir un préstamo para el café.","Buenos días, señora. Vengo a pedir un préstamo.","Hola. Necesito un préstamo para mi café."],"require":[{"type":"containsWord","word":"préstamo","label":"say préstamo (loan)"}],"next":"t2"},{"id":"t2","npc":"Con gusto. ¿Para qué lo va a usar?","npcEn":"Gladly. What will you use it for?","intent":"Say you need it so that the café can stay open this winter.","accept":["Lo necesito para que el café siga abierto este invierno.","Es para que el café siga abierto durante la temporada de lluvias.","Lo necesito para que mi café siga abierto."],"require":[{"type":"subjunctiveAfter","trigger":"para que","label":"after para que (so that), the verb changes: siga"}],"focus":"g:subj-purpose-full","next":"t3"},{"id":"t3","npc":"Entiendo. Le recomiendo que presente un presupuesto. Otra persona tiene que firmar con usted.","npcEn":"I see. I recommend that you present a budget. Another person has to sign with you.","intent":"Politely ask whether she'd mind explaining why you need another person.","accept":["¿Le importaría explicarme por qué necesito a otra persona?","Perdone, ¿le importaría explicarme por qué tiene que firmar otra persona?","¿Le importaría explicarlo más despacio? Quiero entenderlo bien."],"require":[{"type":"regex","pattern":"le importar[ií]a","flags":"i","label":"ask politely: ¿le importaría + infinitive?"}],"focus":"p:te-importaria-inf","next":"t4"},{"id":"t4","npc":"Es para que el banco pueda cobrar si algo sale mal. ¿Tiene a alguien?","npcEn":"It's so that the bank can collect if something goes wrong. Do you have someone?","intent":"Say you have nobody right now, but you plan to talk to a friend.","accept":["No tengo a nadie, pero pienso hablar con un amigo.","Ahora no tengo a nadie. Pienso pedirle ayuda a Hernando.","No tengo familia aquí, pero pienso hablar con mi socia."],"require":[{"type":"negation"},{"type":"verbFormAny","inf":"pensar","tense":"presente","label":"use pensar + infinitive: pienso pedir"}],"focus":"p:pensar-inf","next":"t5"},{"id":"t5","npc":"Muy bien. Cuando encuentre a esa persona, traiga los papeles y le damos una respuesta en una semana.","npcEn":"Very good. When you find that person, bring the papers and we'll give you an answer in a week.","intent":"Thank her and say you'll come back when you find that person.","accept":["Muchas gracias. Vuelvo cuando encuentre a esa persona.","Gracias, señora. Cuando tenga todos los papeles, vuelvo.","Perfecto. Muchas gracias. Vuelvo cuando tenga todo listo."],"require":[{"type":"subjunctiveAfter","trigger":"cuando","label":"after cuando, talking about the future, the verb changes: tenga"}],"focus":"g:subj-cuando-future","next":null}],"r":["g:gender-articles","g:indirect-objects","g:stem-boot","g:subj-cuando-future","g:subj-purpose-full","g:subj-wanting","g:verb-infinitive","p:pensar-inf","p:te-importaria-inf"],"d":null,"spare":true},
{"id":"sc-u32-f","unit":"u32","band":"B1","title":"Fifty kilos","brief":"You're Tomás, receiving a flour delivery at the café door. The driver is a stranger, so use usted. Tell him where to put it, spot the mistake in the order, sort it out and be kind about it.","turns":[{"id":"t1","npc":"Buenos días. Le traigo la harina. ¿Dónde la dejo?","npcEn":"Good morning. I've got your flour. Where do I leave it?","intent":"Greet him and say you want him to leave it in the kitchen.","accept":["Buenos días. Quiero que la deje en la cocina, por favor.","Hola. Quiero que la deje en la cocina, y gracias.","Buenos días. Quiero que usted la deje en la cocina, donde está el horno."],"require":[{"type":"subjunctiveAfter","trigger":"quiero que","label":"after quiero que, the verb changes: deje"}],"focus":"g:subj-influence","next":"t2"},{"id":"t2","npc":"Aquí tiene. Son cincuenta kilos.","npcEn":"Here you are. That's fifty kilos.","intent":"Say you ordered five kilos, not fifty.","accept":["Perdone, pero yo pedí cinco kilos, no cincuenta.","No, yo pedí cinco kilos. Hay un error.","Pedí cinco kilos, no cincuenta."],"require":[{"type":"verbForm","inf":"pedir","tense":"preterito","person":"yo","label":"say what you ordered: pedí"},{"type":"negation"}],"focus":"g:subj-influence","next":"t3"},{"id":"t3","npc":"Qué pena. Eso pasa cuando la oficina cambia el sistema. ¿Qué hacemos?","npcEn":"I'm sorry. That happens when the office changes the system. What do we do?","intent":"Suggest that he take back forty-five kilos today.","accept":["Le propongo que se lleve cuarenta y cinco kilos hoy.","Le propongo que deje cinco kilos y que se lleve lo otro.","Le propongo que devuelva cuarenta y cinco hoy mismo."],"require":[{"type":"subjunctiveAfter","trigger":"le propongo que","label":"after le propongo que, the verb changes: lleve"}],"focus":"p:te-propongo-que","next":"t4"},{"id":"t4","npc":"Es que no vuelvo a pasar por la Candelaria hasta el lunes.","npcEn":"The thing is, I won't be coming through La Candelaria again until Monday.","intent":"Ask him politely to call you when he arrives on Monday.","accept":["¿Me hace el favor de llamarme cuando llegue el lunes?","Entonces, ¿me hace el favor de avisarme cuando llegue?","Está bien. ¿Me hace el favor y me llama cuando llegue el lunes?"],"require":[{"type":"subjunctiveAfter","trigger":"cuando","label":"after cuando, talking about the future, the verb changes: llegue"}],"focus":"p:me-haces-el-favor-de","next":"t5"},{"id":"t5","npc":"Así quedamos. Oiga, hace mucho calor. ¿Me regala un vaso de agua?","npcEn":"That's settled, then. Listen, it's very hot. Would you give me a glass of water?","intent":"Say of course, and offer him a coffee too before he goes.","accept":["Claro. Tome un tinto antes de que se vaya.","Claro que sí. Y tome un tinto antes de que se vaya.","Por supuesto. Siéntese un momento antes de que se vaya."],"require":[{"type":"subjunctiveAfter","trigger":"antes de que","label":"after antes de que, the verb changes: vaya"}],"focus":"g:subj-purpose-full","next":null}],"r":["g:gender-articles","g:present-ar","g:present-er-ir","g:questions","g:stem-boot","g:subj-influence","g:subj-purpose-full","p:me-haces-el-favor-de","p:te-propongo-que"],"d":null,"spare":true},
{"id":"sc-u33-a","unit":"u33","band":"B1","title":"Una cocina de verdad","brief":"You're Tomás, calling a real-estate agency for Vale's new bakery space. The agent is a stranger, so use usted. Describe what you need, even if you don't know whether it exists.","turns":[{"id":"t1","npc":"Inmobiliaria Plaza, buenas tardes. ¿En qué le puedo ayudar?","npcEn":"Plaza Real Estate, good afternoon. How can I help you?","intent":"Say you're looking for premises that have a proper kitchen.","accept":["Busco un local que tenga una cocina de verdad.","Buenas tardes. Estamos buscando un local que tenga cocina.","Necesito un local que tenga una buena cocina."],"require":[{"type":"subjunctiveAfter","trigger":"que","within":3,"label":"premises that have a kitchen: un local que tenga"}],"focus":"g:subj-relative","next":"t2"},{"id":"t2","npc":"Tenemos varios. ¿Qué más necesita?","npcEn":"We have several. What else do you need?","intent":"Say you want something that is near La Candelaria.","accept":["Queremos algo que quede cerca de La Candelaria.","Algo que quede cerca de La Candelaria, por favor.","Busco un local que quede cerca de La Candelaria."],"require":[{"type":"subjunctiveAfter","trigger":"que","within":3,"label":"something near: algo que quede"}],"focus":"g:subj-relative","next":"t3"},{"id":"t3","npc":"Hay uno recién pintado, pero el arriendo es alto. ¿Cuánto pueden pagar?","npcEn":"There's one that's just been painted, but the rent is high. How much can you pay?","intent":"Say that any rent under three million is fine for you.","accept":["Cualquier arriendo menor de tres millones nos sirve.","Puedo pagar cualquier arriendo menor de tres millones.","Nos sirve cualquier arriendo menor de tres millones."],"require":[{"type":"regex","pattern":"\\bcualquier\\b","flags":"i","label":"say any at all: cualquier arriendo"}],"focus":"g:cada-cualquier","next":"t4"},{"id":"t4","npc":"Un detalle: ese edificio es de la empresa Altamira. ¿La conoce?","npcEn":"One detail: that building belongs to the company Altamira. Do you know it?","intent":"Say yes, it's the company that wants to buy the block where your café is.","accept":["Sí, es la empresa que quiere comprar la cuadra en la que está mi café.","Claro, es la empresa que quiere comprar la cuadra en la que tengo el café.","Sí, Altamira es la empresa que quiere comprar la cuadra en la que está nuestro café."],"require":[{"type":"regex","pattern":"\\b(en|con|de|a|para) (el|la|los|las) (que|cual)\\b","flags":"i","label":"after a preposition: la cuadra en la que"}],"focus":"g:relatives-prepositions","next":"t5"},{"id":"t5","npc":"Entiendo. Le mando otros locales por correo, ¿le parece?","npcEn":"I see. I'll email you other premises, is that all right?","intent":"Thank her, and say you'll talk to Vale, who is the one who needs the kitchen.","accept":["Gracias, señora. Voy a hablar con Vale, que es la que necesita la cocina.","Perfecto, muchas gracias. Le cuento a Vale, que es la que necesita la cocina.","Sí, gracias. Vale es la que necesita la cocina, y ella decide."],"require":[{"type":"regex","pattern":"\\bla que\\b","flags":"i","label":"the one who: la que necesita"}],"focus":"p:el-que-la-que","next":null}],"r":["g:cada-cualquier","g:gender-articles","g:present-ar","g:present-er-ir","g:relatives-prepositions","g:ser-identity","g:stem-boot","g:subj-relative","g:verb-infinitive","p:el-que-la-que"],"d":null},
{"id":"sc-u33-b","unit":"u33","band":"B1","title":"El mensaje","brief":"You're Tomás, helping Mariana write the Facebook post that looks for anyone who knew Joaquín Herrera. She's your friend, so use tú. Say exactly who and what you're looking for.","turns":[{"id":"t1","npc":"Estoy escribiendo el mensaje para Facebook. Ayúdame: ¿a quién buscamos exactamente?","npcEn":"I'm writing the Facebook message. Help me: who exactly are we looking for?","intent":"Say you're looking for anyone who knows something about Joaquín Herrera.","accept":["Buscamos a cualquier persona que sepa algo de Joaquín Herrera.","Buscamos a alguien que conozca a Joaquín Herrera.","Queremos encontrar a alguien que sepa algo de Joaquín Herrera."],"require":[{"type":"subjunctiveAfter","trigger":"que","within":3,"label":"someone who knows: alguien que sepa"}],"focus":"g:subj-relative","next":"t2"},{"id":"t2","npc":"Bien. Y hay que poner la ciudad. ¿Santa Marta?","npcEn":"Good. And we have to put the city. Santa Marta?","intent":"Say yes, Santa Marta, the city he arrived in around 1978.","accept":["Sí, Santa Marta. Es la ciudad a la que llegó más o menos en 1978.","Sí, Santa Marta, la ciudad a la que llegó Joaquín hacia 1978.","Sí. Santa Marta es la ciudad a la que llegó en 1978, creo."],"require":[{"type":"regex","pattern":"\\b(en|con|de|a|para) (el|la|los|las) (que|cual)\\b","flags":"i","label":"after a preposition: la ciudad a la que llegó"}],"focus":"g:relatives-prepositions","next":"t3"},{"id":"t3","npc":"¿Y qué les pedimos? ¿Fotos? ¿Cartas?","npcEn":"And what do we ask them for? Photos? Letters?","intent":"Tell her to ask for anything: any photo or letter will help.","accept":["Pídeles cualquier foto o carta, todo nos sirve.","Cualquier foto nos sirve, y cualquier carta también.","Que nos manden cualquier cosa: una foto, una carta, un nombre."],"require":[{"type":"regex","pattern":"\\bcualquier\\b","flags":"i","label":"anything at all: cualquier foto"}],"focus":"g:cada-cualquier","next":"t4"},{"id":"t4","npc":"Mira, ya hay un comentario. Una señora dice que su abuelo trabajó con un Joaquín. ¿Qué le preguntamos?","npcEn":"Look, there's already a comment. A lady says her grandfather worked with a Joaquín. What do we ask her?","intent":"Say she should tell you every detail, because each one matters.","accept":["Que nos cuente cada detalle, porque cada uno importa.","Pídele cada detalle, porque cada uno importa.","Que nos escriba cada detalle, porque cada detalle importa."],"require":[{"type":"regex","pattern":"\\bcada\\b","flags":"i","label":"each one: cada detalle"}],"focus":"g:cada-cualquier","next":"t5"},{"id":"t5","npc":"Listo, lo publico. Gracias por la ayuda. ¿Te invito un café?","npcEn":"Done, I'm posting it. Thanks for the help. Shall I buy you a coffee?","intent":"Say yes, and that you'll bring her a tinto to the table where she always sits.","accept":["Sí, claro. Yo te llevo un tinto a la mesa en la que siempre te sientas.","Con gusto. Te llevo un tinto a la mesa en la que siempre estás.","Sí, gracias. Te llevo un tinto a la mesa en la que siempre trabajas."],"require":[{"type":"regex","pattern":"\\b(en|con|de|a|para) (el|la|los|las) (que|cual)\\b","flags":"i","label":"after a preposition: la mesa en la que"}],"focus":"g:relatives-prepositions","next":null}],"r":["g:cada-cualquier","g:gender-articles","g:indirect-objects","g:present-ar","g:questions","g:relatives-prepositions","g:subj-relative"],"d":null},
{"id":"sc-u33-c","unit":"u33","band":"B1","title":"Medidas y fiador","brief":"You're Tomás, visiting an empty space with Don Hernando. He's older than you, so use usted with him. Talk about the size, where things fit, and what the owner wants.","turns":[{"id":"t1","npc":"Buenos días, Tomás. Vengo a ver el local de Vale. Es grande, ¿verdad?","npcEn":"Good morning, Tomás. I've come to see Vale's space. It's big, isn't it?","intent":"Say yes, it measures about eighty square metres.","accept":["Sí, don Hernando. El local mide ochenta metros cuadrados.","Sí, mide unos ochenta metros cuadrados.","Es grande: mide ochenta metros cuadrados, más o menos."],"require":[{"type":"verbFormAny","inf":"medir","tense":"presente","label":"size with medir: mide"}],"focus":"p:medir","next":"t2"},{"id":"t2","npc":"¿Y dónde van a poner el horno? Vale dice que es enorme.","npcEn":"And where will you put the oven? Vale says it's huge.","intent":"Say the oven fits at the back, next to the window.","accept":["El horno cabe al fondo, junto a la ventana.","Creo que cabe al fondo del local, junto a la ventana.","Cabe sin problema al fondo, junto a la ventana."],"require":[{"type":"verbFormAny","inf":"caber","tense":"presente","label":"fits: cabe"}],"focus":"p:caber","next":"t3"},{"id":"t3","npc":"Ojo: el propietario pide un fiador, alguien que tenga casa propia en Bogotá.","npcEn":"Careful: the owner asks for a guarantor, someone who owns a house in Bogotá.","intent":"Say you don't know anyone who owns a house, and ask if he does.","accept":["No conozco a nadie que tenga casa propia. ¿Usted tiene una?","No conozco a nadie que tenga casa en Bogotá. ¿Usted tiene casa propia, don Hernando?","No conozco a nadie que tenga casa propia. ¿Y usted?"],"require":[{"type":"subjunctiveAfter","trigger":"nadie que","within":2,"label":"nobody who owns: a nadie que tenga"},{"type":"question","label":"ask him a question"}],"focus":"g:subj-relative","next":"t4"},{"id":"t4","npc":"Yo vivo en una pieza arrendada, hijo. Pero hablaré con el propietario. ¿Cuánta plata les queda al mes después del arriendo?","npcEn":"I live in a rented room, son. But I'll talk to the owner. How much money do you have left each month after the rent?","intent":"Say you only have two hundred thousand pesos left each month.","accept":["Después del arriendo nos quedan solo doscientos mil pesos al mes.","Cada mes nos quedan doscientos mil pesos, nada más.","Nos quedan solo doscientos mil pesos cada mes."],"require":[{"type":"verbForm","inf":"quedar","tense":"presente","person":"ellos","label":"what is left: nos quedan"}],"focus":"p:quedar-faltar-sobrar","next":"t5"},{"id":"t5","npc":"Está bien. Mañana lo llamo. ¿Y ahora un tinto para celebrar?","npcEn":"Fine. I'll call him tomorrow. And now a coffee to celebrate?","intent":"Thank him, and say the café is full today but there's always a free table for him.","accept":["Muchas gracias, don Hernando. Hoy el café está lleno, pero siempre hay una mesa libre para usted.","Mil gracias. El café está lleno hoy, pero hay una mesa libre para usted.","Muchas gracias por todo. Está lleno el café, pero siempre hay una mesa libre para usted."],"require":[{"type":"containsWord","word":"libre","label":"a free table: una mesa libre"}],"focus":"p:lleno-libre","next":null}],"r":["g:gender-articles","g:present-ar","g:questions","g:ser-identity","g:stem-e-i","g:subj-relative","p:caber","p:lleno-libre","p:medir","p:quedar-faltar-sobrar"],"d":349,"spare":true},
{"id":"sc-u34-a","unit":"u34","band":"B1","title":"Una denuncia larga","brief":"You're Tomás, at the police station on a bad day. The officer is a stranger, so use usted. Explain what happened to your phone, say why you can't show your ID, and say what you think about the note.","turns":[{"id":"t1","npc":"Comisaría de La Candelaria, buenas tardes. Siéntese. ¿Qué le pasó?","npcEn":"La Candelaria police station, good afternoon. Have a seat. What happened to you?","intent":"Say that someone stole your phone on the bus.","accept":["Me robaron el celular en el bus.","Buenas tardes. En el bus me robaron el celular.","Me robaron el celular en un bus esta mañana."],"require":[{"type":"regex","pattern":"\\bme robaron(?![a-zñáéíóú])","flags":"i","label":"your phone was stolen from you: me robaron"}],"focus":"g:possessive-dative","next":"t2"},{"id":"t2","npc":"Lo siento mucho. ¿Me presta su cédula, por favor?","npcEn":"I'm very sorry. May I see your ID card, please?","intent":"Say you left your ID at the café by accident.","accept":["Ay, no. Se me quedó la cédula en el café.","Qué pena, se me olvidó la cédula en el café.","Perdón, se me quedó en el café."],"require":[{"type":"regex","pattern":"\\bse me (quedó|olvidó)(?![a-zñáéíóú])","flags":"i","label":"an accident happening to you: se me quedó"}],"focus":"g:se-accidental","next":"t3"},{"id":"t3","npc":"Bueno, la trae mañana. Hay otra cosa. Aquí está el papel que venía con la piedra de su ventana. Dice «Vendan». Un vecino cree que fue una broma.","npcEn":"All right, bring it tomorrow. There's something else. Here is the note that came with the stone from your window. It says \"Sell\". A neighbour thinks it was a joke.","intent":"Say you don't think it was a joke.","accept":["No creo que haya sido una broma.","Pues yo no creo que haya sido una broma.","Dudo que haya sido una broma."],"require":[{"type":"regex","pattern":"\\bha(ya|yas|yamos|yan)\\s+[a-zñáéíóú]+(ado|ido|to|cho)(?![a-zñáéíóú])","flags":"i","label":"doubting something that already happened: no creo que haya sido"}],"focus":"g:subj-perfect","next":"t4"},{"id":"t4","npc":"Entiendo. ¿Y usted se lastimó en el bus?","npcEn":"I understand. And did you get hurt on the bus?","intent":"Say that luckily you didn't get hurt.","accept":["No, por suerte no me lastimé.","Por suerte no me pasó nada, señor.","No, señor. Por suerte no me hice daño."],"require":[{"type":"regex","pattern":"por suerte","flags":"i","label":"use the chunk: por suerte"}],"focus":"c:por-suerte","next":"t5"},{"id":"t5","npc":"Qué bueno. Mañana por la tarde le damos la copia de la denuncia.","npcEn":"Good. Tomorrow afternoon we'll give you the copy of the report.","intent":"Thank the officer and say goodbye.","accept":["Muchas gracias, hasta mañana.","Gracias por su ayuda. Hasta mañana.","Gracias, señor. Hasta mañana por la tarde."],"require":[{"type":"containsWord","word":"gracias"}],"focus":"p:gracias-por","next":null}],"r":["c:por-suerte","g:gender-articles","g:indirect-objects","g:possessive-dative","g:present-ar","g:se-accidental","g:subj-perfect","p:gracias-por"],"d":342},
{"id":"sc-u34-b","unit":"u34","band":"B1","title":"Guayaba y cuchillo","brief":"You're Tomás in the café kitchen. Vale, your friend, has just cut her finger slicing mangoes, so use tú. Check on her, ask about the finger, and stay calm when the espresso machine dies too.","turns":[{"id":"t1","npc":"¡Ay! Me corté el dedo con el cuchillo.","npcEn":"Ouch! I cut my finger with the knife.","intent":"Say you hope she hasn't cut herself badly.","accept":["Espero que no te hayas cortado mucho.","Ay, Vale. Espero que no te hayas hecho daño.","Espero que no te hayas cortado muy fuerte."],"require":[{"type":"regex","pattern":"\\bha(ya|yas|yamos|yan)\\s+[a-zñáéíóú]+(ado|ido|to|cho)(?![a-zñáéíóú])","flags":"i","label":"hoping about something that already happened: espero que no te hayas"}],"focus":"g:subj-perfect","next":"t2"},{"id":"t2","npc":"Poco, pero sangra. Y se me cayó la fruta.","npcEn":"A little, but it's bleeding. And I dropped the fruit.","intent":"Ask if she has already washed her finger.","accept":["¿Ya te lavaste el dedo?","¿Te lavaste el dedo con agua?","Vale, ¿te lavaste el dedo?"],"require":[{"type":"question"},{"type":"regex","pattern":"\\bte lavaste (el|la)\\b","flags":"i","label":"body part with me/te: te lavaste el dedo"}],"focus":"g:possessive-dative","next":"t3"},{"id":"t3","npc":"Sí. Y mira, la máquina de espresso no funciona. Se nos dañó otra vez.","npcEn":"Yes. And look, the espresso machine isn't working. It broke on us again.","intent":"Say you doubt it broke by itself.","accept":["Dudo que se haya dañado sola.","No creo que se haya dañado sola.","Qué raro. No creo que se haya dañado sola."],"require":[{"type":"regex","pattern":"\\bha(ya|yas|yamos|yan)\\s+[a-zñáéíóú]+(ado|ido|to|cho)(?![a-zñáéíóú])","flags":"i","label":"doubting something that already happened: dudo que se haya dañado"}],"focus":"g:subj-perfect","next":"t4"},{"id":"t4","npc":"Perdón, qué desastre. Fue culpa mía.","npcEn":"Sorry, what a disaster. It was my fault.","intent":"Tell her it doesn't matter, these things happen.","accept":["No tiene importancia, son cosas que pasan.","Tranquila, no tiene importancia.","Son cosas que pasan, Vale."],"require":[{"type":"regex","pattern":"no tiene importancia|son cosas que pasan","flags":"i","label":"use the chunk: no tiene importancia, son cosas que pasan"}],"focus":"c:no-tiene-importancia","next":"t5"},{"id":"t5","npc":"Gracias, Tomás. Mientras llamo al técnico, ¿me regalas un tinto?","npcEn":"Thanks, Tomás. While I call the technician, can you give me a black coffee?","intent":"Offer to make her a tinto, then realise the café has run out of coffee.","accept":["Claro. Ay, no, se nos acabó el café.","Te hago un tinto. Uy, se nos acabó el café.","Claro, pero se nos terminó el café."],"require":[{"type":"regex","pattern":"\\bse nos (acabó|terminó)(?![a-zñáéíóú])","flags":"i","label":"running out by accident: se nos acabó"}],"focus":"g:se-accidental","next":null}],"r":["c:no-tiene-importancia","g:gender-articles","g:possessive-dative","g:present-ar","g:se-accidental","g:subj-perfect"],"d":342},
{"id":"sc-u34-c","unit":"u34","band":"B1","title":"Un reclamo","brief":"You're Tomás, calling your insurance company about the café. The agent is a stranger, so use usted. Say what happened to the window and the cups, and mention that your phone is gone.","turns":[{"id":"t1","npc":"Aseguradora Andina, habla Camila. ¿En qué le puedo ayudar?","npcEn":"Andina Insurance, this is Camila. How can I help you?","intent":"Say that someone broke the window of your café.","accept":["Buenas tardes. Nos rompieron la ventana del café.","Hola, alguien nos rompió la ventana.","Me rompieron la ventana del café anoche."],"require":[{"type":"regex","pattern":"\\b(nos|me) rompi(eron|ó)(?![a-zñáéíóú])","flags":"i","label":"something done to you: nos rompieron"}],"focus":"g:possessive-dative","next":"t2"},{"id":"t2","npc":"Lo siento mucho. ¿Cuándo ocurrió?","npcEn":"I'm very sorry. When did it happen?","intent":"Say it happened last night and you found the window broken this morning.","accept":["Anoche. Esta mañana encontré la ventana rota.","Pasó anoche. Encontré el vidrio roto al abrir el café.","Fue anoche, y encontré la ventana rota."],"require":[{"type":"regex","pattern":"\\bencontré(?![a-zñáéíóú])","flags":"i","label":"found it already broken: encontré la ventana rota"}],"focus":"p:encontrar-participle","next":"t3"},{"id":"t3","npc":"¿Se llevaron algo?","npcEn":"Did they take anything?","intent":"Say they took nothing, but some cups fell and broke.","accept":["No se llevaron nada, pero se nos cayeron unas tazas.","Nada, pero se nos rompieron unas tazas.","Nada. Pero se nos cayeron todas las tazas."],"require":[{"type":"regex","pattern":"\\bse nos \\w+","flags":"i","label":"an accident happening to us: se nos cayeron"}],"focus":"g:se-accidental","next":"t4"},{"id":"t4","npc":"Necesito la denuncia de la policía. ¿Ya la hizo?","npcEn":"I need the police report. Have you already filed it?","intent":"Say yes, you did it this afternoon, and you hope the police have already sent it.","accept":["Sí, la hice esta tarde. Espero que ya la hayan mandado.","Sí. Fui a la comisaría y espero que la policía ya la haya mandado.","Ya la hice hoy. Espero que ya se la hayan enviado."],"require":[{"type":"regex","pattern":"\\bha(ya|yas|yamos|yan)\\s+[a-zñáéíóú]+(ado|ido|to|cho)(?![a-zñáéíóú])","flags":"i","label":"hoping about something that already happened: espero que ya la hayan mandado"}],"focus":"g:subj-perfect","next":"t5"},{"id":"t5","npc":"No se preocupe, ya la recibimos. En tres días le llamamos.","npcEn":"Don't worry, we've already received it. We'll call you in three days.","intent":"Thank her and ask her to call you at the café, because your phone was stolen.","accept":["Gracias. Llámeme al café, porque me robaron el celular.","Muchas gracias. ¿Me puede llamar al café? Me robaron el celular.","Gracias. Me robaron el celular, así que mejor llámeme al café."],"require":[{"type":"containsWord","word":"gracias"},{"type":"regex","pattern":"\\bme (robaron|quitaron)(?![a-zñáéíóú])","flags":"i","label":"your phone was taken from you: me robaron el celular"}],"focus":"g:possessive-dative","next":null}],"r":["g:direct-objects","g:possessive-dative","g:present-ar","g:se-accidental","g:subj-perfect","p:encontrar-participle"],"d":342,"spare":true},
{"id":"sc-u35-a","unit":"u35","band":"B1","title":"Lo que dice la doctora","brief":"You're Tomás, in the clinic after Hernando's collapse. The doctor is a stranger, so use usted. Find out what he has to do, and understand the rules she gives you.","turns":[{"id":"t1","npc":"Soy la doctora Salcedo. Su amigo ya está mejor, pero tiene un problema del corazón.","npcEn":"I'm Doctor Salcedo. Your friend is better now, but he has a heart problem.","intent":"Thank her and ask what he must do now (use deber).","accept":["Gracias, doctora. ¿Qué debe hacer ahora?","Muchas gracias. ¿Y qué debe hacer él en estos días?","Gracias. ¿Qué es lo que debe hacer?"],"require":[{"type":"verbFormAny","inf":"deber","tense":"presente","label":"what he must do: debe"},{"type":"question","label":"ask a question"}],"focus":"g:deber-modal","next":"t2"},{"id":"t2","npc":"Debe descansar y comer menos sal. Y hay que tomar las pastillas tres veces por día.","npcEn":"He must rest and eat less salt. And you have to take the pills three times a day.","intent":"Say that for him, resting is very hard.","accept":["Para él, descansar es muy difícil.","Para Hernando descansar es lo más difícil.","Va a ser difícil. Para él, descansar es casi imposible."],"require":[{"type":"regex","pattern":"\\bpara\\b","flags":"i","label":"say for him: para él"}],"focus":"g:por-para-2","next":"t3"},{"id":"t3","npc":"Entiendo. ¿Tiene otra pregunta?","npcEn":"I understand. Do you have another question?","intent":"Ask if he can drink coffee.","accept":["¿Puede tomar café?","Perdone, ¿él puede tomar un café por la mañana?","¿Y el café? ¿Se puede tomar café?"],"require":[{"type":"question","label":"ask a question"}],"focus":"p:se-puede-me-dejas","next":"t4"},{"id":"t4","npc":"Un café por la mañana, sí. Pero nada de trasnochar: tiene que dormir bien.","npcEn":"One coffee in the morning, yes. But no staying up late: he has to sleep well.","intent":"Say that, then, one must not go to bed late (use se debe).","accept":["Entonces no se debe dormir tarde.","Entonces no se debe trasnochar.","Entonces no se debe ir a dormir tarde."],"require":[{"type":"regex","pattern":"\\bse debe\\b","flags":"i","label":"one must not: no se debe"}],"focus":"g:impersonal-obligation","next":"t5"},{"id":"t5","npc":"Exacto. ¿Le explico cómo tomar las pastillas?","npcEn":"Exactly. Shall I explain how to take the pills?","intent":"Say yes, please, and ask how many times a day he must take them.","accept":["Sí, por favor. ¿Cuántas veces por día debe tomarlas?","Claro. ¿Cuántas veces por día debe tomar las pastillas?","Sí, por favor. ¿Y cuántas veces por día debe tomarlas él?"],"require":[{"type":"regex","pattern":"\\bpor d[ií]a\\b","flags":"i","label":"times a day: por día"},{"type":"question","label":"ask a question"}],"focus":"g:por-para-2","next":"t6"},{"id":"t6","npc":"Tres veces por día, después de comer. Aquí está la receta.","npcEn":"Three times a day, after eating. Here is the prescription.","intent":"Thank her and say goodbye.","accept":["Muchas gracias, doctora. Hasta luego.","Gracias por todo, doctora. Hasta luego.","Muchas gracias por su ayuda, doctora."],"require":[],"focus":"g:deber-modal","next":null}],"r":["g:deber-modal","g:estar-location-states","g:gender-articles","g:impersonal-obligation","g:por-para-2","g:stem-boot","g:verb-infinitive","p:se-puede-me-dejas"],"d":240},
{"id":"sc-u35-b","unit":"u35","band":"B1","title":"En la recepción","brief":"You're at the clinic desk, asking for an appointment for your friend Hernando. The receptionist is a stranger, so use usted. Describe how he feels, ask politely and find out what rules apply.","turns":[{"id":"t1","npc":"Buenas tardes. ¿Para quién es la cita?","npcEn":"Good afternoon. Who is the appointment for?","intent":"Say it's for your friend Hernando and that he feels very bad.","accept":["Es para mi amigo Hernando. Se siente muy mal.","La cita es para un amigo, Hernando. Se siente fatal.","Es para Hernando. Se siente mal desde ayer."],"require":[{"type":"regex","pattern":"\\bpara\\b","flags":"i","label":"it is for: es para"},{"type":"regex","pattern":"\\bse siente\\b","flags":"i","label":"he feels: se siente"}],"focus":"p:sentirse-mal","next":"t2"},{"id":"t2","npc":"¿Qué síntomas tiene?","npcEn":"What symptoms does he have?","intent":"Describe a symptom: he is very tired, or he has a headache.","accept":["Está muy cansado y tiene dolor de cabeza.","Se cayó y tiene mucho dolor en el pecho.","Se siente mareado y no puede caminar bien."],"require":[{"type":"anyVerbInTense","tense":"presente","label":"say how he is now (present)"}],"focus":"p:sentirse-mal","next":"t3"},{"id":"t3","npc":"El doctor lo va a ver ahora. Una sola persona puede pasar con él.","npcEn":"The doctor will see him now. Only one person can go in with him.","intent":"Politely ask if you can go in with him (use usted).","accept":["¿Puedo pasar yo con él?","Perdón, ¿me deja entrar con él?","¿Se puede entrar con él? Yo soy su amigo."],"require":[{"type":"question","label":"ask a question"},{"type":"avoidsAny","words":["puedes","me dejas"],"label":"use usted: me deja, not me dejas"}],"focus":"p:se-puede-me-dejas","next":"t4"},{"id":"t4","npc":"Está bien. ¿Tiene la tarjeta de la EPS?","npcEn":"That's fine. Do you have the EPS card?","intent":"Say you don't have it and ask if you can pay in cash.","accept":["No la tengo. ¿Se puede pagar en efectivo?","No, la dejó en la casa. ¿Se puede pagar en efectivo?","¿Se puede pagar en efectivo? Hoy no la traje."],"require":[{"type":"regex","pattern":"\\bse puede\\b","flags":"i","label":"can one: se puede"},{"type":"question","label":"ask a question"}],"focus":"p:se-puede-me-dejas","next":"t5"},{"id":"t5","npc":"Sí, en la caja. Y mañana tiene que volver a las ocho.","npcEn":"Yes, at the cash desk. And he has to come back tomorrow at eight.","intent":"Ask whether he must bring anything (use deber).","accept":["¿Debe traer algo?","¿Él debe traer algo más?","Perfecto. ¿Hernando debe traer los medicamentos?"],"require":[{"type":"verbFormAny","inf":"deber","tense":"presente","label":"must he: debe"},{"type":"question","label":"ask a question"}],"focus":"g:deber-modal","next":"t6"},{"id":"t6","npc":"Nada más la tarjeta y su cédula.","npcEn":"Only the card and his ID.","intent":"Thank her and say see you tomorrow.","accept":["Muchas gracias por todo. Hasta mañana.","Gracias. Hasta mañana.","Muy amable, gracias. Hasta mañana."],"require":[{"type":"regex","pattern":"\\bgracias\\b","flags":"i","label":"say thanks"}],"focus":"p:se-puede-me-dejas","next":null}],"r":["g:deber-modal","g:gender-articles","g:stem-boot","g:verb-infinitive","p:se-puede-me-dejas","p:sentirse-mal"],"d":268},
{"id":"sc-u35-c","unit":"u35","band":"B1","title":"El salero de Hernando","brief":"You're in the café with Vale and Hernando, a few days after the clinic. Vale is a friend, so use tú with her. Hernando is older, so use usted. Keep the old man to his doctor's rules without losing his goodwill.","turns":[{"id":"t1","npc":"Hernando está aquí y quiere sopa con sal. Ni se te ocurra dársela.","npcEn":"Hernando is here and wants soup with salt. Don't you dare give it to him.","intent":"Say of course not and ask her what he can eat.","accept":["Claro que no. ¿Qué puede comer?","No, claro. ¿Y qué puede comer Hernando?","Claro que no. ¿Qué puede comer él?"],"require":[{"type":"question","label":"ask a question"}],"focus":"c:ni-se-te-ocurra","next":"t2"},{"id":"t2","npc":"Sopa sin sal, arroz y mucha fruta. Y las pastillas tres veces por día.","npcEn":"Soup without salt, rice and lots of fruit. And the pills three times a day.","intent":"Say you'll make a list for Hernando.","accept":["Voy a hacer una lista para Hernando.","Voy a escribir una lista para él.","Hago una lista para Hernando, para que no se olvide."],"require":[{"type":"regex","pattern":"\\bpara\\b","flags":"i","label":"a list for him: para"}],"focus":"g:por-para-2","next":"t3"},{"id":"t3","npc":"Joven, ¿le importa si me siento aquí, cerca de la cocina?","npcEn":"Young man, do you mind if I sit here, near the kitchen?","intent":"Say not at all, and tell him (usted) he must rest.","accept":["Para nada, don Hernando. Pero usted debe descansar.","No, claro que no. Debe sentarse y descansar.","Siéntese, don Hernando. Debe descansar un rato."],"require":[{"type":"verbForm","inf":"deber","tense":"presente","person":"él/ella","label":"he must: usted debe"},{"type":"avoidsAny","words":["debes","deberías"],"label":"use usted: debe"}],"focus":"g:deber-modal","next":"t4"},{"id":"t4","npc":"Descansar es para los que no tienen trabajo.","npcEn":"Resting is for people who have no work.","intent":"Tell him that the doctor said one has to rest (use hay que).","accept":["Don Hernando, la doctora dijo que hay que descansar.","Hay que descansar, don Hernando. Es por su corazón.","Don Hernando, hay que descansar. Lo dijo la doctora."],"require":[{"type":"regex","pattern":"\\bhay que\\b","flags":"i","label":"one has to: hay que"}],"focus":"g:impersonal-obligation","next":"t5"},{"id":"t5","npc":"Ya le quité la sal. Ahora hay que vigilar la cocina.","npcEn":"I've already taken his salt away. Now we have to watch the kitchen.","intent":"Tell Vale (tú) not to go and leave the salt near him.","accept":["No vayas a dejar la sal cerca de él.","Ten cuidado, no vayas a dejar la sal en la mesa.","Y no vayas a dejar la sal donde él la vea."],"require":[{"type":"regex","pattern":"\\bno vayas a\\b","flags":"i","label":"mind you do not: no vayas a"}],"focus":"p:no-vayas-a","next":"t6"},{"id":"t6","npc":"Está bien, joven. ¿Y un tinto para el camino?","npcEn":"All right, young man. And a black coffee for the road?","intent":"Say yes to one coffee, but only one.","accept":["Un tinto sí, don Hernando. Pero uno solo.","Claro, uno solo. Esta vez invito yo.","Sí, un tinto, pero uno solo."],"require":[{"type":"regex","pattern":"\\buno solo\\b","flags":"i","label":"only one: uno solo"}],"focus":"g:por-para-2","next":null}],"r":["c:ni-se-te-ocurra","g:deber-modal","g:estar-location-states","g:gender-articles","g:impersonal-obligation","g:por-para-2","g:stem-boot","g:verb-infinitive","p:no-vayas-a"],"d":240,"spare":true},
{"id":"sc-u36-a","unit":"u36","band":"B1","title":"Los números de Rosa","brief":"You're Tomás, sitting down with Vale after closing to go through the café's books. She's a friend, so use tú. Say what has been sold, compare this year to last, and draw a conclusion.","turns":[{"id":"t1","npc":"Vale: Ya cerré la caja. Mira, este mes se vendió muchísimo más. ¿Qué crees que pasó?","npcEn":"Vale: I closed the till. Look, a lot more was sold this month. What do you think happened?","intent":"Say that since the review, much more has been sold (use se).","accept":["Desde la reseña se vende mucho más.","Creo que desde la reseña se vendieron más cosas.","Se vende mucho más desde que salió la reseña."],"require":[{"type":"sePassive","label":"use se: se vendió, se vendieron"}],"focus":"g:passive-se","next":"t2"},{"id":"t2","npc":"Vale: Exacto. Y mira la cifra: vendimos mucho más que el año pasado.","npcEn":"Vale: Exactly. And look at the figure: we sold much more than last year.","intent":"Say that you can't believe it, and that it is more than you expected.","accept":["No lo puedo creer. Es más de lo que esperaba.","Es más de lo que pensaba, qué increíble.","Vendimos más de lo que yo esperaba."],"require":[{"type":"regex","pattern":"más de lo que","flags":"i","label":"more than I expected: más de lo que"}],"focus":"p:mas-de-lo-que","next":"t3"},{"id":"t3","npc":"Vale: Lo que vendo yo es la mitad del dinero que entra. Pero hay que pensar en los gastos.","npcEn":"Vale: What I sell is half of the money that comes in. But we have to think about the expenses.","intent":"Say that the expenses are higher than the sales, so there is no profit (use a connector).","accept":["Los gastos son más altos que las ventas, por lo tanto no hay ganancia.","Gastamos más de lo que ganamos, así que no queda ganancia.","Los gastos son mayores que las ventas, de modo que no ganamos nada."],"require":[{"type":"containsAny","words":["por lo tanto","así que","de modo que","por eso"],"label":"draw the conclusion with por lo tanto, así que or de modo que"}],"focus":"g:consequence-connectors","next":"t4"},{"id":"t4","npc":"Vale: Y los abogados cuestan una fortuna. Vendemos más, pero no alcanza.","npcEn":"Vale: And the lawyers cost a fortune. We're selling more, but it's not enough.","intent":"Say that the more you sell, the more you owe.","accept":["Mientras más vendemos, más debemos.","Es increíble: mientras más vendemos, más debemos.","Entre más vendemos, más debemos."],"require":[{"type":"regex","pattern":"(mientras|entre|cuanto) más","flags":"i","label":"the more..., the more...: mientras más..., más..."}],"focus":"g:comparatives-advanced","next":"t5"},{"id":"t5","npc":"Vale: Entonces hay que pensar algo. Gracias por quedarte hasta tarde.","npcEn":"Vale: Then we have to think of something. Thanks for staying late.","intent":"Thank her for her help (use gracias por).","accept":["Gracias por tu ayuda, Vale.","Gracias por todo, Vale. Hasta luego.","Gracias por la ayuda. Hasta luego."],"require":[{"type":"containsAny","words":["gracias por"],"label":"thank her: gracias por"}],"focus":"p:gracias-por","next":null}],"r":["g:comparatives-advanced","g:consequence-connectors","g:gender-articles","g:passive-se","g:present-ar","g:present-er-ir","g:preterite-er-ir","g:verb-infinitive","p:gracias-por","p:mas-de-lo-que"],"d":null},
{"id":"sc-u36-b","unit":"u36","band":"B1","title":"Una cita en el banco","brief":"You're Tomás, at the bank asking about a loan to cover the café's legal costs. The officer is a stranger, so use usted. Explain the situation, ask about the interest, and give your reasons.","turns":[{"id":"t1","npc":"Buenos días. Soy la señora Ortiz, del área de crédito. ¿En qué puedo ayudarle?","npcEn":"Good morning. I'm Mrs. Ortiz from the credit department. How can I help you?","intent":"Say you have a café and need a loan for legal costs.","accept":["Buenos días. Tengo un café y necesito un préstamo para los gastos legales.","Buenos días, señora. Necesito un crédito para pagar a un abogado.","Tengo un café en La Candelaria y necesito un préstamo."],"require":[{"type":"avoidsAny","words":["tienes","necesitas"],"label":"talk about yourself: tengo, necesito"}],"next":"t2"},{"id":"t2","npc":"Entiendo. Y su café, ¿cómo va? ¿Se vende bien?","npcEn":"I see. And your café, how is it doing? Does it sell well?","intent":"Say that sales have gone up a lot, so you have more customers than before.","accept":["Muy bien. Las ventas subieron mucho, así que tenemos más clientes que antes.","Se vende mucho más que el año pasado, por eso tenemos más clientes.","Bien. Tenemos más clientes que antes, por lo tanto vendemos más."],"require":[{"type":"containsAny","words":["por lo tanto","de modo que","de manera que","así que","por eso","tanto","tanta"],"label":"link the result with así que, por eso or por lo tanto"}],"focus":"g:consequence-connectors","next":"t3"},{"id":"t3","npc":"Qué bien. Pero un crédito depende de los gastos. ¿Cuánto debe usted ahora?","npcEn":"Good. But a loan depends on expenses. How much do you owe now?","intent":"Say you owe more than you earn each month.","accept":["Debo más de lo que gano cada mes.","Ahora debo más de lo que gano al mes.","Debemos más de lo que ganamos cada mes."],"require":[{"type":"regex","pattern":"más de lo que","flags":"i","label":"more than you earn: más de lo que gano"}],"focus":"p:mas-de-lo-que","next":"t4"},{"id":"t4","npc":"Ya veo. El interés es del veinticuatro por ciento. ¿Le parece alto?","npcEn":"I see. The interest is twenty-four percent. Does it seem high to you?","intent":"Say it seems higher than at the other bank, and ask what the monthly payment would be.","accept":["Me parece más alto que en el otro banco. ¿Cuánto sería la cuota mensual?","Es más alto que en el otro banco. ¿De cuánto es la cuota al mes?","Sí, es más alto que en el otro banco. ¿Cuánto pagaría cada mes?"],"require":[{"type":"question","label":"ask the monthly payment"},{"type":"regex","pattern":"más alt[oa] que","flags":"i","label":"higher than: más alto que"}],"focus":"g:comparatives-advanced","next":"t5"},{"id":"t5","npc":"Le preparo una oferta. Venga el viernes y la firmamos.","npcEn":"I'll prepare an offer for you. Come on Friday and we'll sign it.","intent":"Thank her and say you will be there on Friday.","accept":["Muchas gracias, señora. El viernes estaré aquí.","Gracias. Vengo el viernes sin falta.","Perfecto, gracias. Nos vemos el viernes."],"require":[],"next":null}],"r":["g:comparatives-advanced","g:consequence-connectors","g:gender-articles","g:indirect-objects","g:present-er-ir","g:questions","g:ser-identity","g:stem-boot","p:mas-de-lo-que"],"d":398},
{"id":"sc-u36-c","unit":"u36","band":"B1","title":"Más de lo que pedimos","brief":"You're Tomás, in the café with Mariana, who has an idea for raising money online. She's your friend, so use tú. Report what was raised, say what was sold, and compare the results with the goal.","turns":[{"id":"t1","npc":"Mariana: Tomás, mira el celular. La campaña lleva tres días y ya hay mucha gente donando.","npcEn":"Mariana: Tomás, look at your phone. The campaign has been going three days and lots of people are already donating.","intent":"Say that a lot of money has been raised in three days (use se).","accept":["Se consiguió muchísimo dinero en tres días.","Qué locura, se juntó muchísima plata en tres días.","Se juntó mucha plata en tres días."],"require":[{"type":"sePassive","label":"use se: se vendió, se vendieron"}],"focus":"g:passive-se","next":"t2"},{"id":"t2","npc":"Mariana: Y esto no es todo. Los clientes de siempre cuentan contigo.","npcEn":"Mariana: And that's not all. The regulars count on you.","intent":"Say that you didn't expect so much help, and that it is more than you hoped.","accept":["No esperaba tanta ayuda. Es más de lo que esperaba.","Es más ayuda de la que yo pensaba, de verdad.","Recibimos más de lo que esperábamos."],"require":[{"type":"regex","pattern":"más (\\w+ )?(de l[oa]s? que|del que)","flags":"i","label":"more than you hoped: más de lo que"}],"focus":"p:mas-de-lo-que","next":"t3"},{"id":"t3","npc":"Mariana: Vale preparó cien tortas para los clientes que ayudaron. Ya se agotaron.","npcEn":"Mariana: Vale made a hundred cakes for the customers who helped. They're already sold out.","intent":"Say that they sold out faster than she thought.","accept":["Se agotaron más rápido de lo que ella pensaba.","Se agotaron más rápido de lo que pensábamos.","Qué bien, se acabaron antes de lo que creíamos."],"require":[{"type":"containsAny","words":["más rápido","más pronto","antes de lo que"],"label":"faster than: más rápido de lo que, antes de lo que"},{"type":"regex","pattern":"de lo que","flags":"i","label":"than she thought: de lo que"}],"focus":"g:comparatives-advanced","next":"t4"},{"id":"t4","npc":"Mariana: La meta era doce millones y ya vamos por veinte. Es mucho más.","npcEn":"Mariana: The goal was twelve million and we're already at twenty. That's much more.","intent":"Say that you have enough now, so you can pay the lawyer.","accept":["Entonces ya tenemos suficiente, de modo que podemos pagar al abogado.","Con eso alcanza, así que le pagamos al abogado.","Tenemos más de lo que pedíamos, por lo tanto podemos pagar al abogado."],"require":[{"type":"containsAny","words":["por lo tanto","de modo que","de manera que","así que","por eso","tanto","tanta"],"label":"link the result with así que, de modo que or por lo tanto"}],"focus":"g:consequence-connectors","next":"t5"},{"id":"t5","npc":"Mariana: Escribí la nota. Va en el periódico mañana.","npcEn":"Mariana: I wrote the article. It goes in the paper tomorrow.","intent":"Tell her good job, and thank her for everything.","accept":["Bien hecho, Mariana. Gracias por todo.","¡Bien hecho! Mil gracias por tu ayuda.","Gracias por todo, Mariana. Bien hecho."],"require":[{"type":"containsAny","words":["bien hecho","buen trabajo"],"label":"praise her: bien hecho"}],"focus":"c:bien-hecho","next":null}],"r":["c:bien-hecho","g:comparatives-advanced","g:consequence-connectors","g:gender-articles","g:ir-a-plans","g:passive-se","g:ser-identity","p:mas-de-lo-que"],"d":null},
{"id":"sc-u36-d","unit":"u36","band":"B1","title":"Precios en la plaza","brief":"You're Tomás, shopping for the café's ingredients at the market. The seller is a stranger, so use usted. Ask prices, comment on figures and see what is left.","turns":[{"id":"t1","npc":"Pase, pase, joven. ¿Qué se le ofrece?","npcEn":"Come in, come in, young man. What can I get you?","intent":"Ask how much the kilo of pork is (a cuánto está).","accept":["¿A cuánto está el kilo de cerdo?","Buenas. ¿A cómo está el kilo de cerdo?","Hola, ¿a cuánto está el cerdo?"],"require":[{"type":"regex","pattern":"a (cuánto|cómo) est","flags":"i","label":"ask with ¿a cuánto está...?"}],"focus":"p:a-cuanto-esta","next":"t2"},{"id":"t2","npc":"Está a veinte mil el kilo. Pero la subida del precio no es mía, es de los proveedores.","npcEn":"It's twenty thousand a kilo. But the price rise isn't mine, it's the suppliers'.","intent":"Say the price went up a lot and is higher than last month.","accept":["Subió mucho. Está más caro que el mes pasado.","El precio subió, es más alto que el mes pasado.","Subió bastante, está más caro que antes."],"require":[{"type":"containsAny","words":["subió","aumentó","más caro","más cara","más alto","más alta"],"label":"say it went up: subió, más caro"}],"focus":"p:subir-subida","next":"t3"},{"id":"t3","npc":"Pues sí. La harina sí está en oferta, con un diez por ciento de descuento.","npcEn":"Well, yes. The flour is on sale, with a ten percent discount.","intent":"Say you'll take ten kilos, because most of what you use is flour.","accept":["Me llevo diez kilos, porque la mayoría de lo que uso es harina.","Entonces diez kilos de harina, por favor. La mayoría de mis recetas la llevan.","Deme diez kilos. La mayoría de lo que hacemos lleva harina."],"require":[{"type":"containsAny","words":["la mayoría","la mayor parte"],"label":"most of: la mayoría de"}],"focus":"p:la-mayoria-de","next":"t4"},{"id":"t4","npc":"Diez kilos... ¿y los huevos? Se agotaron esta mañana, ¡se vendieron todos!","npcEn":"Ten kilos... and the eggs? They sold out this morning, they all sold!","intent":"Ask when there will be eggs for sale again (use se).","accept":["¿Cuándo se vuelven a vender huevos?","¿Cuándo se venden huevos otra vez?","¿Mañana a qué hora se venden los huevos?"],"require":[{"type":"sePassive","label":"use se: se vendió, se vendieron"},{"type":"question","label":"ask a question"}],"focus":"g:passive-se","next":"t5"},{"id":"t5","npc":"Mañana llegan temprano. Son cuarenta mil por todo lo demás.","npcEn":"They arrive early tomorrow. That's forty thousand for the rest.","intent":"Pay, thank the seller and say goodbye until tomorrow.","accept":["Aquí tiene. Muchas gracias, hasta mañana.","Gracias, señor. Hasta mañana.","Perfecto, aquí está la plata. Hasta mañana."],"require":[],"next":null}],"r":["g:estar-location-states","g:gender-articles","g:passive-se","g:ser-identity","p:a-cuanto-esta","p:la-mayoria-de","p:subir-subida"],"d":null},
{"id":"sc-u36-e","unit":"u36","band":"B1","title":"Ajedrez con don Hernando","brief":"You're Tomás, with Don Hernando at the chess table. He's much older than you, so use usted. He wants to know how the business is doing and gives you his taxi-driver view of the economy.","turns":[{"id":"t1","npc":"Buenas tardes, Tomás. Veo que el café ahora se llena todos los días.","npcEn":"Good afternoon, Tomás. I see the café fills up every day now.","intent":"Greet him and say yes, many more people come now than before.","accept":["Buenas tardes, don Hernando. Sí, viene mucha más gente que antes.","Sí, don Hernando. Ahora viene más gente que antes.","Buenas tardes. Es verdad, hay más clientes que antes."],"require":[{"type":"regex","pattern":"más \\w+ que","flags":"i","label":"more than before: más gente que antes"}],"focus":"g:comparatives-advanced","next":"t2"},{"id":"t2","npc":"Cuando yo manejaba el taxi, los precios subían todos los años. ¿Cree que eso pasa hoy?","npcEn":"When I drove a taxi, prices went up every year. Do you think that happens today?","intent":"Say that yes, everything gets more expensive every year (use usted).","accept":["Sí, don Hernando. Cada vez todo es más caro.","Claro. Cada año todo cuesta más.","Sí, cada vez es más caro vivir."],"require":[{"type":"containsAny","words":["cada vez","cada año","más caro","más cara"],"label":"every time more: cada vez más"},{"type":"avoidsAny","words":["tienes","crees"],"label":"use usted"}],"focus":"g:comparatives-advanced","next":"t3"},{"id":"t3","npc":"Una carrera costaba mil pesos. Hoy se paga mucho más.","npcEn":"A ride cost a thousand pesos. Today you pay much more.","intent":"Say that now many things are paid with the phone (use se).","accept":["Hoy muchas cosas se pagan con el celular.","Ahora casi todo se paga con el celular.","Ahora se pagan muchas cosas con el celular."],"require":[{"type":"sePassive","label":"use se: se vendió, se vendieron"}],"focus":"g:passive-se","next":"t4"},{"id":"t4","npc":"Es verdad. Con razón a mí no me alcanza la plata. Debería ahorrar más.","npcEn":"True. No wonder my money isn't enough. I should save more.","intent":"Tell him not to worry, and that he can count on you.","accept":["No se preocupe, don Hernando. Cuente conmigo.","No se preocupe. Puede contar conmigo.","Tranquilo, don Hernando. Cuente con nosotros."],"require":[{"type":"containsAny","words":["cuente con","contar con","cuenta con"],"label":"count on: cuente conmigo"}],"focus":"p:contar-con","next":"t5"},{"id":"t5","npc":"Gracias, muchacho. Jaque mate en tres jugadas.","npcEn":"Thanks, lad. Checkmate in three moves.","intent":"Say bien hecho, and that today you're paying.","accept":["¡Bien hecho, don Hernando! Hoy pago yo.","Bien hecho. Hoy yo invito.","Bien hecho, don Hernando. Hoy le invito yo."],"require":[{"type":"containsAny","words":["bien hecho"],"label":"praise him: bien hecho"}],"focus":"c:bien-hecho","next":null}],"r":["c:bien-hecho","g:comparatives-advanced","g:gender-articles","g:imperfect-habitual","g:passive-se","g:present-ar","g:se-impersonal","g:that-clauses","p:contar-con"],"d":null},
{"id":"sc-u36-f","unit":"u36","band":"B1","title":"Preguntas de una periodista","brief":"You're Tomás, being interviewed by Mariana for an article on small businesses on your street. She's a friend, so use tú. Give figures, compare years and say what follows from them.","turns":[{"id":"t1","npc":"Mariana: Primero lo básico. ¿Qué cambió en el café este año?","npcEn":"Mariana: First the basics. What changed in the café this year?","intent":"Say that the prices were not raised, and that the number of customers went up.","accept":["No se subieron los precios, pero aumentó el número de clientes.","Los precios no subieron y los clientes aumentaron.","No subimos los precios, pero hay más clientes."],"require":[{"type":"containsAny","words":["aumentó","subió","más clientes","aumentaron"],"label":"say customers went up"}],"focus":"p:subir-subida","next":"t2"},{"id":"t2","npc":"Mariana: ¿Y de cuánto fue el aumento de las ventas?","npcEn":"Mariana: And how large was the increase in sales?","intent":"Say it was around forty percent.","accept":["Fue de un cuarenta por ciento.","Más o menos un cuarenta por ciento.","Fue casi un cuarenta por ciento."],"require":[{"type":"containsAny","words":["por ciento","%"],"label":"give the figure with por ciento"}],"focus":"p:por-ciento","next":"t3"},{"id":"t3","npc":"Mariana: Impresionante. ¿Y los gastos?","npcEn":"Mariana: Impressive. And the expenses?","intent":"Say the expenses went up too, so profit is lower than the sales suggest.","accept":["Los gastos también subieron, por lo tanto la ganancia es menor de lo que parece.","Subieron también, así que ganamos menos de lo que parece.","Los gastos subieron más que las ventas, de modo que ganamos menos."],"require":[{"type":"containsAny","words":["por lo tanto","de modo que","de manera que","así que","por eso","tanto","tanta"],"label":"link the result with por lo tanto, así que or de modo que"}],"focus":"g:consequence-connectors","next":"t4"},{"id":"t4","npc":"Mariana: ¿Qué se aprende de todo esto?","npcEn":"Mariana: What do we learn from all this?","intent":"Say that a small business should not spend more than it earns (use deber).","accept":["Un negocio pequeño no debe gastar más de lo que gana.","No se debe gastar más de lo que se gana.","Un negocio no debería gastar más de lo que gana."],"require":[{"type":"regex","pattern":"deb","flags":"i","label":"use deber"},{"type":"negation","label":"not spend more"}],"focus":"g:deber-modal","next":"t5"},{"id":"t5","npc":"Mariana: Perfecto, ya tengo la cita. Gracias por tu tiempo.","npcEn":"Mariana: Perfect, I have my quote. Thanks for your time.","intent":"Thank her and say you'll bring her a coffee.","accept":["Gracias a ti. Te traigo un tinto.","Gracias, Mariana. Ahora te traigo un café.","De nada. Te voy a traer un tinto."],"require":[],"next":null}],"r":["g:consequence-connectors","g:deber-modal","g:gender-articles","g:questions","p:por-ciento","p:subir-subida"],"d":317},
{"id":"sc-u37-a","unit":"u37","band":"B1","title":"Para don Evaristo","brief":"You're Tomás, calling a number in Santa Marta to reach a man who may know about the Herrera family. You don't know the woman who answers, so use usted. Ask for him, leave a message and check one detail.","turns":[{"id":"t1","npc":"Buenas tardes, habla Nelly.","npcEn":"Good afternoon, this is Nelly.","intent":"Greet her and politely ask if you could speak to don Evaristo.","accept":["Buenas tardes. ¿Podría hablar con don Evaristo, por favor?","¿Se encuentra don Evaristo?","Buenas tardes. Quería hablar con don Evaristo, por favor."],"require":[{"type":"regex","pattern":"podr[ií]a|encuentra|quer[ií]a","flags":"i","label":"ask politely: ¿Podría hablar con…?"}],"focus":"p:podria-hablar-con","next":"t2"},{"id":"t2","npc":"En este momento no se encuentra. ¿De parte de quién?","npcEn":"He isn't in at the moment. Who's calling?","intent":"Say you are Tomás, Rosa's grandson, and that you are calling from Bogotá.","accept":["Soy Tomás, el nieto de Rosa. Llamo desde Bogotá.","De parte de Tomás, el nieto de Rosa. Llamo de Bogotá.","Mi nombre es Tomás. Soy el nieto de Rosa y llamo desde Bogotá."],"require":[{"type":"containsWord","word":"Tomás"}],"focus":"p:podria-hablar-con","next":"t3"},{"id":"t3","npc":"Ah, el nieto de doña Rosa. ¿Quiere dejar un mensaje?","npcEn":"Ah, doña Rosa's grandson. Do you want to leave a message?","intent":"Ask her to tell don Evaristo to call you back.","accept":["Sí, dígale que me llame, por favor.","Por favor, dígale a don Evaristo que me llame.","Sí. Dígale que por favor me llame esta noche."],"require":[{"type":"regex","pattern":"\\bque\\b.*\\b(llame|devuelva)\\b","flags":"i","label":"pass on a request: dígale que me llame"}],"focus":"g:reported-requests","next":"t4"},{"id":"t4","npc":"Con gusto se lo digo.","npcEn":"Gladly, I'll tell him.","intent":"Politely ask if she knows whether he will be back tomorrow.","accept":["¿Sabe si vuelve mañana?","Y por casualidad, ¿sabe si don Evaristo viene mañana?","Una pregunta: ¿sabe si él regresa mañana?"],"require":[{"type":"regex","pattern":"\\bsi\\b","flags":"i","label":"ask indirectly with si: ¿Sabe si…?"}],"focus":"g:indirect-questions","next":"t5"},{"id":"t5","npc":"Creo que sí, viene todos los días. ¿Algo más?","npcEn":"I think so, he comes every day. Anything else?","intent":"Say that is all, thank her and say goodbye.","accept":["No, eso sería todo. Muchas gracias.","Eso sería todo, gracias. Hasta luego.","No, nada más. Muchas gracias por su ayuda."],"require":[{"type":"containsAny","words":["gracias"]}],"focus":"c:eso-seria-todo","next":null}],"r":["c:eso-seria-todo","g:gender-articles","g:indirect-questions","g:reported-requests","g:stem-boot","p:podria-hablar-con"],"d":null},
{"id":"sc-u37-b","unit":"u37","band":"B1","title":"Noticias de la costa","brief":"You're Tomás at the café. Hernando has news and he's older than you, so use usted. Show interest, ask what it's about, pass a request along and ask one careful question.","turns":[{"id":"t1","npc":"Tomás, tengo noticias de la costa.","npcEn":"Tomás, I have news from the coast.","intent":"Show interest and ask what it is about.","accept":["¿De qué se trata, señor?","¿Noticias? ¿De qué se trata?","Cuénteme. ¿De qué se trata?"],"require":[{"type":"regex","pattern":"\\bde qu[eé]","flags":"i","label":"ask what it is about: ¿De qué se trata?"}],"focus":"g:questions-prepositions","next":"t2"},{"id":"t2","npc":"Un primo de un amigo mío conoce a un pescador de Taganga. Su abuelo se llamaba Herrera.","npcEn":"A cousin of a friend of mine knows a fisherman in Taganga. His grandfather was called Herrera.","intent":"You can't believe the name. Echo his last sentence, putting the question word where the surprise is: His grandfather was called what?","accept":["¿Su abuelo se llamaba cómo?","¿Se llamaba cómo?","¿Perdón? ¿Se llamaba cómo?"],"require":[{"type":"regex","pattern":"c[oó]mo\\s*\\?","flags":"i","label":"put the question word last: ¿Se llamaba cómo?"}],"focus":"p:echo-question","next":"t3"},{"id":"t3","npc":"Herrera, sí señor. Se llama Jairo, y su hija Marisol tiene el celular. ¿Qué le digo a mi amigo?","npcEn":"Herrera, yes sir. His name is Jairo, and his daughter Marisol has the phone. What should I tell my friend?","intent":"Ask him to tell his friend to pass you Marisol's number.","accept":["Dígale a su amigo que me pase el número de Marisol.","Por favor, dígale que me dé el número de Marisol.","Dígale que me pase el número, por favor."],"require":[{"type":"regex","pattern":"\\bque me (pase|d[eé]|mande)","flags":"i","label":"pass on a request: dígale que me pase"}],"focus":"g:reported-requests","next":"t4"},{"id":"t4","npc":"Hecho. Marisol trabaja en un hotel, creo.","npcEn":"Done. Marisol works in a hotel, I think.","intent":"Ask politely if he happens to know whether the hotel is near the beach.","accept":["¿Por casualidad sabe si el hotel queda cerca de la playa?","Una pregunta: ¿por casualidad sabe si queda cerca de la playa?","¿Sabe por casualidad si el hotel está cerca de la playa?"],"require":[{"type":"regex","pattern":"casualidad","flags":"i","label":"soften with por casualidad"},{"type":"regex","pattern":"\\bsi\\b","flags":"i","label":"ask indirectly with si"}],"focus":"p:por-casualidad","next":"t5"},{"id":"t5","npc":"No sé, pero mañana se lo pregunto. ¿Le sirvo un tinto?","npcEn":"I don't know, but I'll ask him tomorrow. Shall I pour you a coffee?","intent":"Accept the coffee and thank him.","accept":["Sí, gracias, señor. Un tinto me cae bien.","Claro que sí, muchas gracias.","Con gusto, gracias. Me hace falta uno."],"require":[{"type":"containsAny","words":["gracias"]}],"focus":"g:indirect-questions","next":null}],"r":["g:gender-articles","g:indirect-objects","g:indirect-questions","g:present-ar","g:questions-prepositions","g:reflexive-routine","g:reported-requests","g:yo-irregular","p:echo-question","p:por-casualidad"],"d":null},
{"id":"sc-u37-c","unit":"u37","band":"B1","title":"Mala línea","brief":"You're Tomás, answering the café phone. The line is bad and the caller may be a stranger, so use usted. Say you can't hear well, take a message and check you understood it.","turns":[{"id":"t1","npc":"¿Aló? ¿Hola? Casi no se oye.","npcEn":"Hello? Hello? It's hard to hear.","intent":"Say you can't hear him well and ask if he can hear you.","accept":["No lo oigo bien. ¿Usted me escucha?","Lo oigo muy mal. ¿Me escucha?","Casi no lo escucho. ¿Me oye usted?"],"require":[{"type":"regex","pattern":"\\b(oigo|escucho)\\b","flags":"i","label":"say you hear badly: no lo oigo bien"}],"focus":"p:ver-oir-bien-mal","next":"t2"},{"id":"t2","npc":"Ahora sí. Habla Jairo. ¿Se encuentra don Hernando?","npcEn":"Now I can. This is Jairo. Is don Hernando there?","intent":"Say he isn't in right now and ask if he wants to leave a message.","accept":["En este momento no se encuentra. ¿Quiere dejarle un mensaje?","Ahorita no se encuentra. ¿Quiere dejar un mensaje?","No se encuentra ahora. ¿Quiere dejarle un mensaje?"],"require":[{"type":"regex","pattern":"no se encuentra","flags":"i","label":"he isn't in: no se encuentra"}],"focus":"c:no-se-encuentra","next":"t3"},{"id":"t3","npc":"Sí. Dígale que Marisol quiere hablar con Tomás, el nieto de Rosa.","npcEn":"Yes. Tell him Marisol wants to speak to Tomás, Rosa's grandson.","intent":"Say you are Tomás and ask what she wants to talk about.","accept":["Yo soy Tomás. ¿De qué quiere hablar ella?","Soy Tomás. ¿De qué quiere hablar conmigo?","Yo soy Tomás. ¿Para qué quiere hablar conmigo?"],"require":[{"type":"regex","pattern":"\\b(de|para|sobre) qu[eé]","flags":"i","label":"ask about what: ¿De qué quiere hablar?"}],"focus":"g:questions-prepositions","next":"t4"},{"id":"t4","npc":"Es por lo del abuelo Herrera. Ella prefiere hablar en persona, en Taganga.","npcEn":"It's about the Herrera grandfather. She prefers to talk in person, in Taganga.","intent":"Check you understood: ask if she wants you to go to Taganga.","accept":["¿Quiere que vaya a Taganga?","Entonces, ¿ella quiere que yo vaya a Taganga?","O sea, ¿me pide que vaya a Taganga?"],"require":[{"type":"regex","pattern":"que (yo )?vaya","flags":"i","label":"check what she asks: quiere que vaya"}],"focus":"g:reported-requests","next":"t5"},{"id":"t5","npc":"Exacto. Se va a cortar la llamada. Hasta pronto.","npcEn":"Exactly. The call is going to drop. See you soon.","intent":"Thank him and say goodbye.","accept":["Gracias, Jairo. Hasta pronto.","Muchas gracias por llamar. Hasta luego.","Gracias por el mensaje. Hasta pronto."],"require":[{"type":"containsAny","words":["gracias"]}],"focus":"p:gracias-por","next":null}],"r":["c:no-se-encuentra","g:gender-articles","g:questions-prepositions","g:reported-requests","g:stem-boot","p:gracias-por","p:ver-oir-bien-mal"],"d":null,"spare":true},
{"id":"sc-u38-a","unit":"u38","band":"B1","title":"Micrófono en el mostrador","brief":"You're Tomás. A TV reporter has come into the café with a camera. She doesn't know you, so use usted. Say when you found out, what happened to the houses, why the official was suspended, and what you think of Altamira's reaction.","turns":[{"id":"t1","npc":"Buenas tardes, soy Lucía Peña, del Canal 7. ¿Cuándo se enteró usted de la noticia?","npcEn":"Good afternoon, I'm Lucía Peña, from Channel 7. When did you find out about the news?","intent":"Say you found out this morning, when Mariana called you.","accept":["Me enteré esta mañana, cuando Mariana me llamó.","Me enteré esta mañana por Mariana.","Me enteré hoy por la mañana, porque Mariana me llamó."],"require":[{"type":"containsAny","words":["enteré"],"label":"found out: me enteré"}],"focus":"p:enterarse-de","next":"t2"},{"id":"t2","npc":"Dos casas antiguas desaparecieron en una sola noche. ¿Qué pasó exactamente?","npcEn":"Two old houses disappeared in a single night. What exactly happened?","intent":"Say the two houses were demolished at night (use ser + participle).","accept":["Las dos casas fueron demolidas de noche.","Fueron demolidas durante la noche, sin avisar a nadie.","El artículo dice que las casas fueron demolidas de noche."],"require":[{"type":"regex","pattern":"\\bfueron\\s+(demolidas|destruidas|tumbadas)\\b","flags":"i","label":"were demolished: fueron demolidas"}],"focus":"g:passive-ser","next":"t3"},{"id":"t3","npc":"El jefe de permisos de la alcaldía fue suspendido ayer. ¿Por qué lo suspendieron?","npcEn":"The head of permits at the mayor's office was suspended yesterday. Why was he suspended?","intent":"Say he was suspended because of the permits he signed (give the cause with debido a, a causa de, ya que or puesto que).","accept":["Fue suspendido debido a los permisos que firmó.","Lo suspendieron a causa de los permisos de los seis edificios.","Fue suspendido ya que firmó todos los permisos."],"require":[{"type":"containsAny","words":["debido a","a causa de","ya que","puesto que","dado que","por culpa de"],"label":"give the cause: debido a, a causa de, ya que, puesto que"}],"focus":"g:causal-advanced","next":"t4"},{"id":"t4","npc":"Altamira dice que el artículo es ficción. ¿Qué opina usted?","npcEn":"Altamira says the article is fiction. What do you think?","intent":"Say that, despite what Altamira says, the documents are real.","accept":["A pesar de lo que dice Altamira, los documentos son reales.","Altamira dice eso; sin embargo, los documentos son reales.","Los documentos son reales. Aun así, Altamira dice que es ficción."],"require":[{"type":"containsAny","words":["a pesar de","sin embargo","aun así"],"label":"despite: a pesar de, sin embargo, aun así"}],"focus":"g:concession-despite","next":"t5"},{"id":"t5","npc":"Muchas gracias por su tiempo. Ya apagamos la cámara.","npcEn":"Thank you very much for your time. We've switched the camera off.","intent":"Thank her, and invite her to sit down for a coffee, on the house.","accept":["Gracias a usted. Siéntese, el tinto lo invita la casa.","Gracias. Siéntese, por favor, que el café va por la casa.","A usted. Siéntese y tome un café, es una invitación de la casa."],"require":[{"type":"avoidsAny","words":["tienes","quieres","siéntate"],"label":"use usted with a stranger"}],"next":null}],"r":["g:causal-advanced","g:concession-despite","g:gender-articles","g:passive-ser","g:present-ar","g:preterite-ar","g:preterite-er-ir","g:questions","g:ser-identity","p:enterarse-de"],"d":556},
{"id":"sc-u38-b","unit":"u38","band":"B1","title":"El tinto de don Hernando","brief":"You're Tomás. Don Hernando comes in with the newspaper. You two use usted with each other now. Talk about how you found out, what you hadn't noticed, where tomorrow's march is and who deserves thanks.","turns":[{"id":"t1","npc":"Buenos días, Tomás. Todo el barrio habla del artículo. ¿Se enteró de que suspendieron al jefe de permisos?","npcEn":"Good morning, Tomás. The whole neighbourhood is talking about the article. Did you hear they suspended the head of permits?","intent":"Say yes, you found out from Mariana this morning.","accept":["Sí, me enteré por Mariana esta mañana.","Sí, me enteré esta mañana, por Mariana.","Sí, Mariana me lo contó esta mañana y me enteré."],"require":[{"type":"containsAny","words":["enteré"],"label":"found out: me enteré"}],"focus":"x:darse-cuenta-enterarse","next":"t2"},{"id":"t2","npc":"Yo no me di cuenta de nada. Esas casas estuvieron ahí toda la vida. ¿Y usted?","npcEn":"I didn't notice a thing. Those houses were there all my life. And you?","intent":"Say you didn't notice anything either until the article came out.","accept":["Yo tampoco me di cuenta de nada hasta que salió el artículo.","Yo no me di cuenta de nada hasta que Mariana publicó el artículo.","Tampoco me di cuenta de nada hasta el artículo."],"require":[{"type":"containsAny","words":["cuenta"],"label":"noticing: me di cuenta"}],"focus":"x:darse-cuenta-enterarse","next":"t3"},{"id":"t3","npc":"Mañana hay una manifestación. ¿Usted sabe dónde es?","npcEn":"Tomorrow there's a protest. Do you know where it is?","intent":"Say it is in the Plaza de Bolívar, at ten in the morning.","accept":["Es en la Plaza de Bolívar, a las diez de la mañana.","La manifestación es en la Plaza de Bolívar, a las diez.","Creo que es en la Plaza de Bolívar, a las diez."],"require":[{"type":"regex","pattern":"\\bes en\\b","flags":"i","label":"an event: es en, not está en"},{"type":"avoidsAny","words":["está en"],"label":"an event takes es en, not está en"}],"focus":"x:es-en-esta-en","next":"t4"},{"id":"t4","npc":"Altamira intentó callar la historia, pero ahora todo el país la conoce.","npcEn":"Altamira tried to silence the story, but now the whole country knows it.","intent":"Say that thanks to Mariana, the whole neighbourhood knows the truth.","accept":["Gracias a Mariana, todo el barrio sabe la verdad.","Sí, y gracias a ella sabemos la verdad.","Todo el barrio sabe la verdad gracias a Mariana."],"require":[{"type":"containsAny","words":["gracias a"],"label":"thanks to: gracias a"}],"focus":"x:gracias-a-debido-a","next":"t5"},{"id":"t5","npc":"Bueno, me siento junto a la ventana. Un tinto, por favor.","npcEn":"Well, I'll sit by the window. A black coffee, please.","intent":"Say of course, you'll bring it right away, and that the coffee is on the house today.","accept":["Claro, ya se lo traigo. Hoy lo invita la casa.","Enseguida se lo llevo. Hoy el tinto es de la casa.","Claro que sí. Ya se lo llevo, y hoy no le cobro."],"require":[{"type":"avoidsAny","words":["te lo","tienes"],"label":"use usted with Don Hernando"}],"next":null}],"r":["g:gender-articles","g:present-er-ir","g:preterite-ar","g:reflexive-routine","x:darse-cuenta-enterarse","x:es-en-esta-en","x:gracias-a-debido-a"],"d":null},
{"id":"sc-u38-c","unit":"u38","band":"B1","title":"Doce periodistas","brief":"You're Tomás, talking to Vale, who is in the kitchen while reporters crowd the door. She is a friend, so use tú. Decide what to tell the press, correct a detail, explain why the story matters and find out what she told Altamira.","turns":[{"id":"t1","npc":"Tomás, hay doce periodistas en la puerta y una cámara en el mostrador. ¿Qué les digo?","npcEn":"Tomás, there are twelve reporters at the door and a camera on the counter. What do I tell them?","intent":"Tell her to say the café is staying open, despite everything.","accept":["Diles que el café sigue abierto a pesar de todo.","Diles que el café abre, a pesar de todo.","Diles que seguimos abiertos, a pesar de todo."],"require":[{"type":"containsAny","words":["a pesar de","sin embargo","aun así"],"label":"despite: a pesar de"}],"focus":"g:concession-despite","next":"t2"},{"id":"t2","npc":"Uno pregunta si es verdad que las casas fueron demolidas aquí al lado.","npcEn":"One asks whether it's true that the houses were demolished right next door.","intent":"Say no, they were demolished on another street.","accept":["No, fueron demolidas en otra calle.","No, las casas fueron demolidas en otra calle.","No, aquí al lado no. Fueron demolidas en otra calle."],"require":[{"type":"regex","pattern":"\\bfueron\\s+(demolidas|destruidas|tumbadas)\\b","flags":"i","label":"were demolished: fueron demolidas"},{"type":"negation"}],"focus":"g:passive-ser","next":"t3"},{"id":"t3","npc":"Otro quiere saber por qué este artículo es tan importante para el barrio.","npcEn":"Another wants to know why this article is so important for the neighbourhood.","intent":"Say it matters because those houses are part of the neighbourhood's history (give the cause with ya que, puesto que, debido a or a causa de).","accept":["Es importante ya que esas casas son parte de la historia del barrio.","Es importante puesto que son parte de la historia del barrio.","Para el barrio es importante, ya que esas casas son su historia."],"require":[{"type":"containsAny","words":["debido a","a causa de","ya que","puesto que"],"label":"give the cause: ya que, puesto que, debido a, a causa de"}],"focus":"g:causal-advanced","next":"t4"},{"id":"t4","npc":"Ah, y Altamira acaba de llamar. Dice que todo es ficción. ¡Ficción! Pero yo ya les contesté.","npcEn":"Oh, and Altamira just called. They say it's all fiction. Fiction! But I already answered them.","intent":"Ask her what she told them.","accept":["¿Y qué les respondiste?","¿Qué les contestaste tú?","¿Qué les respondiste a ellos?"],"require":[{"type":"question"}],"focus":"x:lo-le","next":"t5"},{"id":"t5","npc":"Les respondí que, si esto es ficción, mis croissants también. Bueno, ya salgo con una bandeja de pan para los periodistas.","npcEn":"I told them that, if this is fiction, so are my croissants. Anyway, I'm coming out with a tray of bread for the reporters.","intent":"Say good idea, thank her, and say you'll make the coffee.","accept":["Buena idea, gracias. Yo preparo el café.","Gracias, Vale. Yo hago el café.","Me parece muy bien. Gracias, yo preparo el café."],"require":[],"next":null}],"r":["g:causal-advanced","g:concession-despite","g:gender-articles","g:indirect-objects","g:passive-ser","g:ser-identity","g:si-present","g:that-clauses","g:yo-irregular","x:lo-le"],"d":556,"spare":true},
{"id":"sc-u39-a","unit":"u39","band":"B1","title":"Ensayo general","brief":"You're Tomás, rehearsing tomorrow's talk to the heritage committee with Mariana, who plays the committee and edits as you go. Use a clear structure: an opening, your points in order, and a close. Speak to the committee as a group, so use ustedes and su.","turns":[{"id":"t1","npc":"Mariana: Mañana el comité te escucha a las diez. A ver, empieza.","npcEn":"Mariana: Tomorrow the committee listens to you at ten. Go on, begin.","intent":"Open the talk by saying that today you are going to talk to them about your grandmother's café.","accept":["Hoy les voy a hablar del café de mi abuela.","Buenos días. Hoy les voy a hablar del café de Rosa, mi abuela.","Hoy les voy a hablar de la historia del café de mi abuela."],"require":[{"type":"regex","pattern":"\\bhoy les voy a hablar\\b","flags":"iu","label":"open the talk: hoy les voy a hablar de..."}],"focus":"p:hoy-les-voy-a-hablar","next":"t2"},{"id":"t2","npc":"Bien. Ahora tu primera razón. ¿Por qué importa el café?","npcEn":"Good. Now your first reason. Why does the café matter?","intent":"Say that, first of all (start with Primero), the café is part of the neighbourhood.","accept":["Primero, el café forma parte del barrio.","Primero, el café forma parte de La Candelaria, mi barrio.","Primero, el café es parte del barrio."],"require":[{"type":"regex","pattern":"\\bprimero\\b","flags":"iu","label":"start with: primero"}],"focus":"g:discourse-structure","next":"t3"},{"id":"t3","npc":"¿Y la segunda?","npcEn":"And the second one?","intent":"Add that keeping the café open is important for the neighbours. Start your point with the verb: Mantener...","accept":["Además, mantener el café abierto es importante para los vecinos.","Mantener abierto el café es muy importante para los vecinos.","Además, abrir el café cada mañana es importante para el barrio."],"require":[{"type":"regex","pattern":"(^|[.,;:]\\s*)\\p{L}+(ar|er|ir)\\b[^.]*\\bes\\b","flags":"iu","label":"make the action the subject: mantener ... es importante"}],"focus":"g:infinitive-subject","next":"t4"},{"id":"t4","npc":"Bien. Ahora la historia de la casa. Léeme esa parte.","npcEn":"Good. Now the history of the house. Read me that part.","intent":"Read her the line from your text: Weinstein sold the house to Rosa, and the latter opened the café in 1979. Point back at Rosa with 'esta'.","accept":["Weinstein le vendió la casa a Rosa. Esta abrió el café en 1979.","Weinstein le vendió la casa a Rosa, y esta abrió el café en 1979.","Weinstein le vendió la casa a Rosa; esta abrió el café en 1979."],"require":[{"type":"regex","pattern":"\\besta\\b","flags":"iu","label":"point back with esta (the latter)"}],"focus":"g:referring-back","next":"t5"},{"id":"t5","npc":"Muy bien. ¿Y cómo terminas?","npcEn":"Very good. And how do you finish?","intent":"Close the talk by thanking the committee for their attention.","accept":["Muchas gracias por su atención.","Gracias por su atención. El café es de todos.","Y nada más. Muchas gracias por su atención."],"require":[{"type":"regex","pattern":"gracias por su atención","flags":"iu","label":"thank them: gracias por su atención"}],"focus":"c:gracias-por-su-atencion","next":null}],"r":["c:gracias-por-su-atencion","g:discourse-structure","g:gender-articles","g:infinitive-subject","g:present-ar","g:referring-back","p:hoy-les-voy-a-hablar"],"d":333},
{"id":"sc-u39-b","unit":"u39","band":"B1","title":"Tinta roja","brief":"You're Tomás in Vale's kitchen. She has your draft in one hand and a red pen in the other. She is your friend, so use tú. Explain what each part is about and fix the order and the repetition.","turns":[{"id":"t1","npc":"Vale: Leí tu primer párrafo en la cocina. ¿De qué trata?","npcEn":"Vale: I read your first paragraph in the kitchen. What is it about?","intent":"Say that it is about the history of the café.","accept":["Trata de la historia del café.","Se trata de la historia del café de Rosa.","Es el párrafo que trata de la historia del café."],"require":[{"type":"regex","pattern":"\\btrata de\\b","flags":"iu","label":"say what it's about: trata de / se trata de"}],"focus":"p:se-trata-de","next":"t2"},{"id":"t2","npc":"Vale: Falta orden. ¿Qué dices primero y qué dices después?","npcEn":"Vale: It needs some order. What do you say first and what do you say after?","intent":"Say that first you talk about the history and then about the neighbours.","accept":["Primero hablo de la historia y después de los vecinos.","Primero hablo de la historia; después, de los vecinos.","Primero, la historia. Después, los vecinos."],"require":[{"type":"regex","pattern":"\\b(en primer lugar|primero)\\b","flags":"iu","label":"order it: primero ... después"}],"focus":"g:discourse-structure","next":"t3"},{"id":"t3","npc":"Vale: Un comité quiere ver los dos lados. ¿Cuáles son?","npcEn":"Vale: A committee wants to see both sides. What are they?","intent":"Give both sides of the building: on one hand it is old and expensive, on the other it is beautiful.","accept":["Por un lado, el edificio es viejo y caro; por otro, es muy bonito.","Por un lado es viejo y caro. Por otro lado, es muy bonito.","Por un lado, es caro; por otro, es hermoso."],"require":[{"type":"regex","pattern":"\\bpor un lado\\b","flags":"iu","label":"one side: por un lado"},{"type":"regex","pattern":"\\bpor otro\\b","flags":"iu","label":"the other: por otro"}],"focus":"g:discourse-structure","next":"t4"},{"id":"t4","npc":"Vale: Perfecto. Pero escribes «el local» doce veces. ¿Qué haces?","npcEn":"Vale: Perfect. But you write \"the premises\" twelve times. What do you do?","intent":"Say you will write 'dicho local' (the premises in question) instead of repeating it.","accept":["Escribo dicho local.","Puedo poner dicho local en vez de repetir.","Entonces pongo dicho local."],"require":[{"type":"regex","pattern":"\\bdicho local\\b","flags":"iu","label":"point back formally: dicho local"}],"focus":"g:referring-back","next":"t5"},{"id":"t5","npc":"Vale: Toma un café por el esfuerzo. ¿Cómo vas?","npcEn":"Vale: Have a coffee for the effort. How is it going?","intent":"Thank her and say that writing a text like this in Spanish is hard, but easier with her.","accept":["Gracias, Vale. Escribir un texto así en español es difícil, pero contigo es más fácil.","Gracias. Escribir en español es difícil, pero tú me ayudas.","Muchas gracias. Escribir tanto es difícil, pero contigo todo es más fácil."],"require":[{"type":"regex","pattern":"(^|[.,;:]\\s*)\\p{L}+(ar|er|ir)\\b[^.]*\\b(es|resulta)\\b","flags":"iu","label":"make writing the subject: escribir ... es difícil"}],"focus":"g:infinitive-subject","next":null}],"r":["g:discourse-structure","g:gender-articles","g:infinitive-subject","g:present-ar","g:questions","g:referring-back","p:se-trata-de"],"d":185},
{"id":"sc-u39-c","unit":"u39","band":"B1","title":"Algo en el ojo","brief":"You're Tomás at the café counter. Don Hernando has read your statement and has things to say. He is older than you and courtly, so use usted. Explain why you wrote it and what it means to the neighbourhood.","turns":[{"id":"t1","npc":"Hernando: Buenos días, Tomás. Leí su texto de principio a fin. Dígame, ¿por qué escribió tanto sobre un café?","npcEn":"Hernando: Good morning, Tomás. I read your text from beginning to end. Tell me, why did you write so much about a café?","intent":"Say that despite the new buildings the café is part of the neighbourhood.","accept":["A pesar de los edificios nuevos, el café forma parte del barrio.","El café forma parte del barrio, a pesar de Altamira.","A pesar de todo, el café forma parte del barrio."],"require":[{"type":"regex","pattern":"\\ba pesar de\\b","flags":"iu","label":"concede: a pesar de..."},{"type":"regex","pattern":"\\b(forma|hace) parte\\b","flags":"iu","label":"the café is part of: forma parte de"}],"focus":"g:concession-despite","next":"t2"},{"id":"t2","npc":"Hernando: Mmm. ¿Fue fácil escribir sobre Rosa?","npcEn":"Hernando: Hmm. Was it easy to write about Rosa?","intent":"Say no, it is a topic that is hard to explain.","accept":["No, es un tema difícil de explicar.","No, fue un párrafo difícil de escribir.","No mucho. Rosa es difícil de resumir."],"require":[{"type":"regex","pattern":"difícil de \\p{L}+(ar|er|ir)\\b","flags":"iu","label":"use: difícil de + verb"}],"focus":"p:dificil-de-inf","next":"t3"},{"id":"t3","npc":"Hernando: Es cierto. ¿Y qué clientes tiene el café, según usted?","npcEn":"Hernando: That's true. And what customers does the café have, according to you?","intent":"Say there are several kinds of customers: some come for the coffee and others for Simón.","accept":["Hay varios tipos de clientes: unos vienen por el café y otros por Simón.","Hay dos tipos de clientes. Unos vienen por el tinto y otros por Simón.","Hay varios tipos de clientes. Unos vienen por el café; otros, por Simón."],"require":[{"type":"regex","pattern":"\\bhay (varios|dos|tres) (tipos|clases) de\\b","flags":"iu","label":"name the kinds: hay varios tipos de..."}],"focus":"p:hay-varios-tipos","next":"t4"},{"id":"t4","npc":"Hernando: Ejem. Perdone, tengo algo en el ojo. Es el polvo, nada más.","npcEn":"Hernando: Ahem. Excuse me, I have something in my eye. It's the dust, nothing more.","intent":"Kindly say that Rosa is part of every paragraph.","accept":["Entiendo. Rosa forma parte de cada párrafo, don Hernando.","Sí, es el polvo. Rosa forma parte de cada página.","No se preocupe. Rosa forma parte de todo el texto."],"require":[{"type":"regex","pattern":"\\bforma parte\\b","flags":"iu","label":"use: forma parte de"}],"focus":"p:formar-parte-de","next":"t5"},{"id":"t5","npc":"Hernando: Gracias, Tomás. ¿Y qué es lo más difícil para usted ahora?","npcEn":"Hernando: Thank you, Tomás. And what's the hardest thing for you now?","intent":"Say that waiting for the committee's answer is the hardest thing. Make the action the subject: Esperar...","accept":["Esperar la respuesta del comité es lo más difícil.","Esperar es lo más difícil, don Hernando.","Ahora, esperar la carta del comité es lo más difícil."],"require":[{"type":"regex","pattern":"(^|[.,;:]\\s*)\\p{L}+(ar|er|ir)\\b[^.]*\\bes\\b|\\bes (no )?\\p{L}+(ar|er|ir)\\b","flags":"iu","label":"make the action the subject: esperar ... es lo más difícil"}],"focus":"g:infinitive-subject","next":null}],"r":["g:commands-usted","g:concession-despite","g:gender-articles","g:infinitive-subject","g:prep-pronouns","g:questions","g:ser-identity","p:dificil-de-inf","p:formar-parte-de","p:hay-varios-tipos"],"d":371,"spare":true},
{"id":"sc-u40-a","unit":"u40","band":"B1","title":"Un barco propio","brief":"You're Tomás on the beach at Taganga, meeting Yesid, a diving instructor and the grandson of Joaquín, your grandmother Rosa's brother. The two old siblings stopped speaking decades ago. Yesid is young and direct, so use tú. Talk about what you would do if things were different.","turns":[{"id":"t1","npc":"Yesid: Tú eres Tomás, el nieto de Rosa, ¿verdad? Yo soy Yesid, el nieto de Joaquín. Somos familia, aunque nuestros abuelos no se hablaban.","npcEn":"Yesid: You're Tomás, Rosa's grandson, right? I'm Yesid, Joaquín's grandson. We're family, even though our grandparents didn't speak to each other.","intent":"Say that if your grandmother were here, she would be happy to meet him.","accept":["Si mi abuela estuviera aquí, estaría feliz de conocerte.","Mucho gusto, Yesid. Si Rosa estuviera aquí, estaría muy feliz de conocerte.","Sí, soy Tomás. Si ella estuviera aquí, se alegraría de conocerte."],"require":[{"type":"regex","pattern":"\\bsi\\b(?:\\s+\\p{L}+){0,3}?\\s+(?:(?!para\\b|cara\\b|clara\\b|rara\\b)\\p{L}+(?:ara|aras|áramos|aran|iera|ieras|iéramos|ieran)|fuera|fueras|fuéramos|fueran)\\b","flags":"iu","label":"start the 'if' part with si + the past form (si tuviera, si fuera)"},{"type":"regex","pattern":"\\b\\p{L}+r(?:ía|ías|íamos|ían)\\b","flags":"iu","label":"say what you would do: the -ría form (iría, haría)"}],"focus":"g:si-hypothetical","next":"t2"},{"id":"t2","npc":"Yesid: Gracias. Enseño buceo, pero trabajo para un hombre que tiene tres barcos y paga poco. Mi sueño es tener uno mío.","npcEn":"Yesid: Thanks. I teach diving, but I work for a man who has three boats and pays little. My dream is to have one of my own.","intent":"Ask him what he would do if he had his own boat.","accept":["¿Qué harías si tuvieras tu propio barco?","Si tuvieras un barco, ¿qué harías con él?","¿Y qué harías tú si el barco fuera tuyo?"],"require":[{"type":"question","label":"ask a question"},{"type":"regex","pattern":"\\bsi\\b(?:\\s+\\p{L}+){0,3}?\\s+(?:(?!para\\b|cara\\b|clara\\b|rara\\b)\\p{L}+(?:ara|aras|áramos|aran|iera|ieras|iéramos|ieran)|fuera|fueras|fuéramos|fueran)\\b","flags":"iu","label":"start the 'if' part with si + the past form (si tuviera, si fuera)"},{"type":"regex","pattern":"\\b\\p{L}+r(?:ía|ías|íamos|ían)\\b","flags":"iu","label":"say what you would do: the -ría form (iría, haría)"}],"focus":"g:imperfect-subj","next":"t3"},{"id":"t3","npc":"Yesid: Llevaría a la gente a ver las tortugas, sin ruido ni prisa. Y tú, si pudieras elegir, ¿qué harías con el café de Rosa?","npcEn":"Yesid: I would take people to see the turtles, with no noise and no hurry. And you, if you could choose, what would you do with Rosa's café?","intent":"Say that if you could choose, you would keep the café open.","accept":["Si pudiera elegir, dejaría el café abierto.","Mantendría el café abierto si pudiera elegir.","Si fuera por mí, el café seguiría abierto para siempre."],"require":[{"type":"regex","pattern":"\\bsi\\b(?:\\s+\\p{L}+){0,3}?\\s+(?:(?!para\\b|cara\\b|clara\\b|rara\\b)\\p{L}+(?:ara|aras|áramos|aran|iera|ieras|iéramos|ieran)|fuera|fueras|fuéramos|fueran)\\b","flags":"iu","label":"start the 'if' part with si + the past form (si tuviera, si fuera)"},{"type":"regex","pattern":"\\b\\p{L}+r(?:ía|ías|íamos|ían)\\b","flags":"iu","label":"say what you would do: the -ría form (iría, haría)"}],"focus":"g:si-hypothetical","next":"t4"},{"id":"t4","npc":"Yesid: Mi abuela habla de la discusión entre Joaquín y Rosa como si fuera un secreto. Yo nunca supe qué pasó.","npcEn":"Yesid: My grandmother talks about the argument between Joaquín and Rosa as if it were a secret. I never found out what happened.","intent":"Say you don't know either, and that in your family they talk about it as if nothing had happened.","accept":["Yo tampoco lo sé. En mi familia hablan de eso como si nada.","Tampoco sé nada. Mi tío habla de Joaquín como si nada.","No lo sé. Todos cambian de tema como si nada."],"require":[{"type":"regex","pattern":"\\bcomo si nada\\b","flags":"iu","label":"use: como si nada"}],"focus":"g:como-si","next":"t5"},{"id":"t5","npc":"Yesid: Entonces tenemos algo que averiguar juntos. Mañana te llevo a ver las tortugas, si quieres venir.","npcEn":"Yesid: Then we have something to find out together. Tomorrow I'll take you to see the turtles, if you want to come.","intent":"Say you would love to, and ask what time you leave.","accept":["Me encantaría. ¿A qué hora salimos?","Claro, me encantaría ir. ¿A qué hora nos vemos?","Gracias, me encantaría. ¿Cuándo salimos mañana?"],"require":[{"type":"question","label":"ask a question"},{"type":"regex","pattern":"\\bencantar[ií]a\\b|\\bgustar[ií]a\\b","flags":"iu","label":"say you would love to: me encantaría"}],"focus":"g:conditional","next":null}],"r":["g:como-si","g:conditional","g:gender-articles","g:imperfect-subj","g:present-ar","g:relative-que","g:ser-identity","g:si-hypothetical","g:verb-infinitive"],"d":510},
{"id":"sc-u40-b","unit":"u40","band":"B1","title":"Un horno con vista al mar","brief":"You're Tomás on the hotel patio in Santa Marta at nine in the morning, already hot. Vale, who is quick and dry, is teasing you. Complain about the heat, imagine something better and make a deal. You and Vale are friends, so use tú.","turns":[{"id":"t1","npc":"Vale: Buenos días. Hoy estamos a 34 grados y todavía es temprano. ¿Cómo dormiste?","npcEn":"Vale: Good morning. It's 34 degrees today and it's still early. How did you sleep?","intent":"Say you slept badly because the climate here is very humid.","accept":["Mal. El clima aquí es muy húmedo.","Dormí mal, porque todo es muy húmedo y hace mucho calor.","Casi no dormí. La humedad es terrible."],"require":[{"type":"regex","pattern":"\\b(húmedo|húmeda|húmedos|húmedas|humedad)\\b","flags":"iu","label":"describe it: húmedo / la humedad"}],"focus":"p:humedo-mojado","next":"t2"},{"id":"t2","npc":"Vale: Mira a Mariana en la piscina, tranquila, como si estuviéramos en Bogotá.","npcEn":"Vale: Look at Mariana in the pool, relaxed, as if we were in Bogotá.","intent":"Say you feel as if you were in an oven.","accept":["Yo me siento como si estuviera en un horno.","Pues yo estoy como si estuviera dentro de un horno.","Yo siento como si viviera dentro de un horno."],"require":[{"type":"regex","pattern":"\\bcomo si\\b(?:\\s+\\p{L}+){0,3}?\\s+(?:(?!para\\b|cara\\b|clara\\b|rara\\b)\\p{L}+(?:ara|aras|áramos|aran|iera|ieras|iéramos|ieran)|fuera|fueras|fuéramos|fueran)\\b","flags":"iu","label":"use como si + the past form (como si fuera)"}],"focus":"g:como-si","next":"t3"},{"id":"t3","npc":"Vale: Qué dramático eres. Mariana quiere ir en barco a Taganga hoy, pero dicen que hay olas grandes. Tú decides.","npcEn":"Vale: How dramatic you are. Mariana wants to go to Taganga by boat today, but they say there are big waves. You decide.","intent":"Say that if you had to decide, you wouldn't go today.","accept":["Si tuviera que decidir, no iría hoy.","Si yo decidiera, no iría hoy con estas olas.","No iría hoy si tuviera que decidir, con tantas olas."],"require":[{"type":"regex","pattern":"\\bsi\\b(?:\\s+\\p{L}+){0,3}?\\s+(?:(?!para\\b|cara\\b|clara\\b|rara\\b)\\p{L}+(?:ara|aras|áramos|aran|iera|ieras|iéramos|ieran)|fuera|fueras|fuéramos|fueran)\\b","flags":"iu","label":"start the 'if' part with si + the past form (si tuviera, si fuera)"},{"type":"regex","pattern":"\\b\\p{L}+r(?:ía|ías|íamos|ían)\\b","flags":"iu","label":"say what you would do: the -ría form (iría, haría)"},{"type":"negation","label":"say you wouldn't go"}],"focus":"g:si-hypothetical","next":"t4"},{"id":"t4","npc":"Vale: Bueno, tienes razón. Un pescador dice que en Taganga se ven tortugas por la tarde.","npcEn":"Vale: OK, you're right. A fisherman says you can see turtles in Taganga in the afternoon.","intent":"Ask Vale if she would come with you if you went in the afternoon.","accept":["¿Vendrías conmigo si fuéramos por la tarde?","Si fuéramos por la tarde, ¿vendrías?","¿Vendrías si saliéramos más tarde, cuando hay menos calor?"],"require":[{"type":"question","label":"ask a question"},{"type":"regex","pattern":"\\bsi\\b(?:\\s+\\p{L}+){0,3}?\\s+(?:(?!para\\b|cara\\b|clara\\b|rara\\b)\\p{L}+(?:ara|aras|áramos|aran|iera|ieras|iéramos|ieran)|fuera|fueras|fuéramos|fueran)\\b","flags":"iu","label":"start the 'if' part with si + the past form (si tuviera, si fuera)"},{"type":"regex","pattern":"\\b\\p{L}+r(?:ía|ías|íamos|ían)\\b","flags":"iu","label":"say what you would do: the -ría form (iría, haría)"}],"focus":"g:si-hypothetical","next":"t5"},{"id":"t5","npc":"Vale: Vendría. Pero tú pagas los jugos. No me mires como si fuera mucha plata. ¿Trato hecho?","npcEn":"Vale: I'd come. But you're paying for the juices. Don't look at me as if it were a lot of money. Deal?","intent":"Accept the deal and say you'll pay, as if you were rich.","accept":["Trato hecho. Pago yo, como si fuera rico.","Trato hecho, pago yo. Hoy soy generoso, como si fuera el dueño del hotel.","De acuerdo. Pago yo, como si fuera millonario."],"require":[{"type":"regex","pattern":"\\bcomo si\\b(?:\\s+\\p{L}+){0,3}?\\s+(?:(?!para\\b|cara\\b|clara\\b|rara\\b)\\p{L}+(?:ara|aras|áramos|aran|iera|ieras|iéramos|ieran)|fuera|fueras|fuéramos|fueran)\\b","flags":"iu","label":"use como si + the past form (como si fuera)"}],"focus":"g:como-si","next":null}],"r":["g:como-si","g:estar-location-states","g:gender-articles","g:imperfect-subj","g:present-er-ir","g:questions","g:ser-identity","g:si-hypothetical","g:stem-boot","g:stem-e-i","g:that-clauses","p:humedo-mojado"],"d":510},
{"id":"sc-u40-c","unit":"u40","band":"B1","title":"La playa de noche","brief":"You're Tomás on the beach in Taganga at night, alone with Vale. The tourists have gone home and the sea is loud. Say what you imagine and what you would do. You and Vale are friends, so use tú.","turns":[{"id":"t1","npc":"Vale: Escucha el mar. Ya no hay turistas, ni motos, ni nada.","npcEn":"Vale: Listen to the sea. There are no tourists any more, no motorbikes, nothing.","intent":"Say it feels like another world, as if you were in another country.","accept":["Parece otro mundo, como si estuviéramos en otro país.","Es verdad. Se siente como si fuera otro país.","Qué paz. Es como si estuviéramos en otro mundo."],"require":[{"type":"regex","pattern":"\\bcomo si\\b(?:\\s+\\p{L}+){0,3}?\\s+(?:(?!para\\b|cara\\b|clara\\b|rara\\b)\\p{L}+(?:ara|aras|áramos|aran|iera|ieras|iéramos|ieran)|fuera|fueras|fuéramos|fueran)\\b","flags":"iu","label":"use como si + the past form (como si fuera)"}],"focus":"g:como-si","next":"t2"},{"id":"t2","npc":"Vale: Oye, Tomás. Si no tuvieras el café, ¿dónde vivirías?","npcEn":"Vale: Hey, Tomás. If you didn't have the café, where would you live?","intent":"Say that if you didn't have the café, you would live here by the sea.","accept":["Si no tuviera el café, viviría aquí, junto al mar.","Viviría cerca del mar si no tuviera el café. Es mi sueño.","Si no tuviera el café, viviría en una casa en la playa."],"require":[{"type":"regex","pattern":"\\bsi\\b(?:\\s+\\p{L}+){0,3}?\\s+(?:(?!para\\b|cara\\b|clara\\b|rara\\b)\\p{L}+(?:ara|aras|áramos|aran|iera|ieras|iéramos|ieran)|fuera|fueras|fuéramos|fueran)\\b","flags":"iu","label":"start the 'if' part with si + the past form (si tuviera, si fuera)"},{"type":"regex","pattern":"\\b\\p{L}+r(?:ía|ías|íamos|ían)\\b","flags":"iu","label":"say what you would do: the -ría form (iría, haría)"}],"focus":"g:imperfect-subj","next":"t3"},{"id":"t3","npc":"Vale: Bonito. Pero si Altamira te ofreciera mucha plata por el café, ¿lo venderías?","npcEn":"Vale: Nice. But if Altamira offered you a lot of money for the café, would you sell it?","intent":"Say you would think about it, but you wouldn't sell the café to Altamira.","accept":["Lo pensaría, pero no vendería el café a Altamira.","No, nunca. No vendería el café a Altamira, ni con mucha plata.","Lo pensaría un momento, pero no lo vendería."],"require":[{"type":"regex","pattern":"\\b\\p{L}+r(?:ía|ías|íamos|ían)\\b","flags":"iu","label":"say what you would do: the -ría form (iría, haría)"},{"type":"negation","label":"say you wouldn't sell"}],"focus":"g:conditional","next":"t4"},{"id":"t4","npc":"Vale: Eres terco. Y estás muy callado. Estamos solos, el mar suena, y tú no dices nada. ¿Qué te pasa?","npcEn":"Vale: You're stubborn. And you're very quiet. We're alone, the sea is making noise, and you say nothing. What's wrong with you?","intent":"Admit that you feel as if you were fifteen years old.","accept":["Me siento como si tuviera quince años.","No sé. Estoy nervioso, como si tuviera quince años.","Es que me siento como si fuera un niño de quince años."],"require":[{"type":"regex","pattern":"\\bcomo si\\b(?:\\s+\\p{L}+){0,3}?\\s+(?:(?!para\\b|cara\\b|clara\\b|rara\\b)\\p{L}+(?:ara|aras|áramos|aran|iera|ieras|iéramos|ieran)|fuera|fueras|fuéramos|fueran)\\b","flags":"iu","label":"use como si + the past form (como si fuera)"}],"focus":"g:como-si","next":"t5"},{"id":"t5","npc":"Mariana: ¡Aquí están! Traje tres cervezas. ¿Hablaban de algo importante?","npcEn":"Mariana: There you are! I brought three beers. Were you talking about something important?","intent":"Say no, you were just talking about the sea, and thank her for the beers.","accept":["No, hablábamos del mar. Gracias por las cervezas.","Para nada, solo del mar. Muchas gracias, Mariana.","No, nada importante. Gracias por las cervezas."],"require":[{"type":"regex","pattern":"\\bgracias\\b","flags":"iu","label":"say thanks"}],"focus":"g:imperfect-subj","next":null}],"r":["g:como-si","g:conditional","g:estar-location-states","g:gender-articles","g:imperfect-subj","g:negation-words","g:si-hypothetical"],"d":510},
{"id":"sc-u40-d","unit":"u40","band":"B1","title":"Para la columna","brief":"You're Tomás on a bench by the sea. Mariana, a journalist, is recording a short interview for her column. Answer as yourself, in a relaxed way. She's a friend, so use tú.","turns":[{"id":"t1","npc":"Mariana: Grabo, ¿sí? Primera pregunta: ¿a cuántos grados estamos hoy, más o menos?","npcEn":"Mariana: I'm recording, okay? First question: roughly how many degrees is it today?","intent":"Say it's about 35 degrees and that the humidity is terrible.","accept":["Estamos a unos 35 grados, y la humedad es terrible.","Más o menos a 35 grados. La humedad es horrible.","Hace como 35 grados y todo es muy húmedo."],"require":[{"type":"regex","pattern":"\\bgrados\\b","flags":"iu","label":"give the number of degrees"}],"focus":"p:estar-a-grados","next":"t2"},{"id":"t2","npc":"Mariana: Segunda: ¿con qué sueñas cuando estás tan lejos de Bogotá?","npcEn":"Mariana: Second: what do you dream of when you're so far from Bogotá?","intent":"Say you dream of opening a terrace at the café.","accept":["Sueño con abrir una terraza en el café.","Mi sueño es abrir una terraza en el café.","Sueño con una terraza para el café, con mesas al sol."],"require":[{"type":"regex","pattern":"\\bsue[ñn]o con\\b|\\bmi sueño es\\b","flags":"iu","label":"use: sueño con... / mi sueño es..."}],"focus":"p:sonar-con","next":"t3"},{"id":"t3","npc":"Mariana: Tercera: si pudieras cambiar una cosa de Bogotá, ¿cuál sería?","npcEn":"Mariana: Third: if you could change one thing about Bogotá, what would it be?","intent":"Say that if you could change one thing, you would change the traffic.","accept":["Si pudiera cambiar una cosa, cambiaría el tráfico.","Cambiaría el tráfico, si pudiera cambiar algo.","Si pudiera cambiar algo de Bogotá, cambiaría el tráfico."],"require":[{"type":"regex","pattern":"\\bsi\\b(?:\\s+\\p{L}+){0,3}?\\s+(?:(?!para\\b|cara\\b|clara\\b|rara\\b)\\p{L}+(?:ara|aras|áramos|aran|iera|ieras|iéramos|ieran)|fuera|fueras|fuéramos|fueran)\\b","flags":"iu","label":"start the 'if' part with si + the past form (si tuviera, si fuera)"},{"type":"regex","pattern":"\\b\\p{L}+r(?:ía|ías|íamos|ían)\\b","flags":"iu","label":"say what you would do: the -ría form (iría, haría)"}],"focus":"g:si-hypothetical","next":"t4"},{"id":"t4","npc":"Mariana: Perfecto. Oye, ¿y Vale? Pasó muy rápido hacia el hotel.","npcEn":"Mariana: Perfect. Hey, what about Vale? She went by very fast towards the hotel.","intent":"Say you don't know, and that Vale always walks as if she were in a hurry.","accept":["No sé. Vale siempre camina como si tuviera prisa.","No tengo idea. Ella camina como si tuviera prisa todo el día.","Ni idea. Vale siempre va como si llegara tarde."],"require":[{"type":"regex","pattern":"\\bcomo si\\b(?:\\s+\\p{L}+){0,3}?\\s+(?:(?!para\\b|cara\\b|clara\\b|rara\\b)\\p{L}+(?:ara|aras|áramos|aran|iera|ieras|iéramos|ieran)|fuera|fueras|fuéramos|fueran)\\b","flags":"iu","label":"use como si + the past form (como si fuera)"}],"focus":"g:como-si","next":"t5"},{"id":"t5","npc":"Mariana: Bien. Apago la grabadora. ¿Quieres leer el texto antes de que lo publique?","npcEn":"Mariana: Good. I'm turning off the recorder. Do you want to read the text before I publish it?","intent":"Say yes and politely ask whether she could send you the text tonight.","accept":["Sí, claro. ¿Podrías mandarme el texto esta noche?","Me encantaría. ¿Podrías mandarme el texto hoy?","Sí. ¿Podrías mandarme el texto antes de dormir?"],"require":[{"type":"question","label":"ask a question"},{"type":"regex","pattern":"\\bpodr[ií]as\\b","flags":"iu","label":"ask politely: ¿podrías...?"}],"focus":"g:conditional","next":null}],"r":["g:como-si","g:conditional","g:estar-location-states","g:gender-articles","g:present-ar","g:si-hypothetical","g:stem-boot","g:verb-infinitive","p:estar-a-grados","p:sonar-con"],"d":510,"spare":true},
{"id":"sc-u40-e","unit":"u40","band":"B1","title":"Una llamada de Bogotá","brief":"You're Tomás on the phone from the coast with Don Hernando, who is back in Bogotá looking after the café and Simón. He is older and courtly, so use usted all the way through.","turns":[{"id":"t1","npc":"Hernando: Buenas noches, Tomás. ¿Llegaron bien? Simón pregunta por ustedes, grita sus nombres todo el día.","npcEn":"Hernando: Good evening, Tomás. Did you all get there safely? Simón asks about you all, he shouts your names all day.","intent":"Say yes, you arrived well, and ask how Simón is.","accept":["Sí, llegamos bien, don Hernando. ¿Cómo está Simón?","Buenas noches, Don Hernando. Llegamos bien. ¿Y cómo está Simón?","Todo bien, gracias. ¿Cómo está Simón con usted?"],"require":[{"type":"question","label":"ask a question"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"g:imperfect-subj","next":"t2"},{"id":"t2","npc":"Hernando: Está bien, aunque extraña a Rosa. Si yo tuviera cuarenta años menos, estaría ahí con ustedes, en la playa.","npcEn":"Hernando: He's fine, although he misses Rosa. If I were forty years younger, I'd be there with you all, on the beach.","intent":"Say that if he were there, you would show him the sea.","accept":["Si usted estuviera aquí, le mostraría el mar.","Si estuviera aquí, Don Hernando, le mostraría el mar.","Le mostraría el mar si usted estuviera con nosotros."],"require":[{"type":"regex","pattern":"\\bsi\\b(?:\\s+\\p{L}+){0,3}?\\s+(?:(?!para\\b|cara\\b|clara\\b|rara\\b)\\p{L}+(?:ara|aras|áramos|aran|iera|ieras|iéramos|ieran)|fuera|fueras|fuéramos|fueran)\\b","flags":"iu","label":"start the 'if' part with si + the past form (si tuviera, si fuera)"},{"type":"regex","pattern":"\\b\\p{L}+r(?:ía|ías|íamos|ían)\\b","flags":"iu","label":"say what you would do: the -ría form (iría, haría)"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"g:si-hypothetical","next":"t3"},{"id":"t3","npc":"Hernando: Qué amable. Dígame una cosa: el doctor dice que no debo viajar. ¿Usted qué haría en mi lugar?","npcEn":"Hernando: How kind. Tell me something: the doctor says I shouldn't travel. What would you do in my place?","intent":"Say that if you were him, you would rest and wait.","accept":["Si yo fuera usted, descansaría y esperaría.","Si fuera usted, descansaría un poco.","Yo descansaría, si fuera usted."],"require":[{"type":"regex","pattern":"\\bsi\\b(?:\\s+\\p{L}+){0,3}?\\s+(?:(?!para\\b|cara\\b|clara\\b|rara\\b)\\p{L}+(?:ara|aras|áramos|aran|iera|ieras|iéramos|ieran)|fuera|fueras|fuéramos|fueran)\\b","flags":"iu","label":"start the 'if' part with si + the past form (si tuviera, si fuera)"},{"type":"regex","pattern":"\\b\\p{L}+r(?:ía|ías|íamos|ían)\\b","flags":"iu","label":"say what you would do: the -ría form (iría, haría)"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"g:si-hypothetical","next":"t4"},{"id":"t4","npc":"Hernando: Tiene razón. Pero ya hablo como un viejo cansado, ¿no cree?","npcEn":"Hernando: You're right. But I already talk like a tired old man, don't you think?","intent":"Disagree politely: say he talks as if he were thirty years old.","accept":["No, usted habla como si tuviera treinta años.","Para nada, Don Hernando. Habla como si tuviera treinta años.","No lo creo. Usted habla como si fuera joven."],"require":[{"type":"regex","pattern":"\\bcomo si\\b(?:\\s+\\p{L}+){0,3}?\\s+(?:(?!para\\b|cara\\b|clara\\b|rara\\b)\\p{L}+(?:ara|aras|áramos|aran|iera|ieras|iéramos|ieran)|fuera|fueras|fuéramos|fueran)\\b","flags":"iu","label":"use como si + the past form (como si fuera)"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"g:como-si","next":"t5"},{"id":"t5","npc":"Hernando: Gracias, joven. Cuídense mucho y tráigame algo del mar.","npcEn":"Hernando: Thank you, young man. Take care, all of you, and bring me something from the sea.","intent":"Promise to bring him a coconut, and say goodnight.","accept":["Le traeré un coco, Don Hernando. Buenas noches.","Claro que sí, le traeré un coco. Que descanse, buenas noches.","Le traeré un coco de la playa. Buenas noches, Don Hernando."],"require":[{"type":"regex","pattern":"\\bcocos?\\b","flags":"iu","label":"promise a coco"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"g:future","next":null}],"r":["g:commands-usted","g:commands-with-pronouns","g:como-si","g:conditional","g:gender-articles","g:imperfect-subj","g:prep-pronouns","g:present-ar","g:present-er-ir","g:si-hypothetical"],"d":510,"spare":true},
{"id":"sc-u40-f","unit":"u40","band":"B1","title":"Al amanecer en el muelle","brief":"You're Tomás at the dock in Taganga, asking an older fisherman, Eliécer, to take your group to see the turtles. Be polite and use usted. Ask what things would cost and what would happen if things changed.","turns":[{"id":"t1","npc":"Eliécer: Buenas, joven. ¿Busca algo? Aquí solo hay pescado y sol.","npcEn":"Eliécer: Hello, young man. Are you looking for something? Here there's only fish and sun.","intent":"Say hello and ask whether he would take you to see the turtles tomorrow.","accept":["Buenas. ¿Usted me llevaría a ver las tortugas mañana?","Buenos días. ¿Me llevaría a ver las tortugas mañana?","Buenas, señor. ¿Nos llevaría mañana a ver las tortugas?"],"require":[{"type":"question","label":"ask a question"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"},{"type":"regex","pattern":"\\btortugas?\\b","flags":"iu","label":"mention the turtles"}],"focus":"g:conditional","next":"t2"},{"id":"t2","npc":"Eliécer: Las tortugas salen temprano. Si el mar estuviera tranquilo, saldríamos hoy mismo.","npcEn":"Eliécer: The turtles come out early. If the sea were calm, we'd leave today.","intent":"Ask how much it would cost for three people.","accept":["¿Cuánto costaría para tres personas?","¿Cuánto cobraría usted por tres personas?","Y para tres personas, ¿cuánto costaría?"],"require":[{"type":"question","label":"ask a question"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"},{"type":"regex","pattern":"\\bcostar[ií]a\\b|\\bcobrar[ií]a\\b|\\bcuesta\\b|\\bcobra\\b","flags":"iu","label":"ask about the price"}],"focus":"g:conditional","next":"t3"},{"id":"t3","npc":"Eliécer: Con el desayuno, cien mil pesos. Si fueran solo dos, ochenta mil.","npcEn":"Eliécer: With breakfast, one hundred thousand pesos. If it were only two, eighty thousand.","intent":"Say it's a bit expensive and ask whether he would lower the price if you were four.","accept":["Es un poco caro. ¿Bajaría el precio si fuéramos cuatro?","Es mucho. Si fuéramos cuatro, ¿bajaría el precio?","Es caro para nosotros. ¿Cobraría menos si fuéramos cuatro?"],"require":[{"type":"question","label":"ask a question"},{"type":"regex","pattern":"\\bsi\\b(?:\\s+\\p{L}+){0,3}?\\s+(?:(?!para\\b|cara\\b|clara\\b|rara\\b)\\p{L}+(?:ara|aras|áramos|aran|iera|ieras|iéramos|ieran)|fuera|fueras|fuéramos|fueran)\\b","flags":"iu","label":"start the 'if' part with si + the past form (si tuviera, si fuera)"},{"type":"regex","pattern":"\\b\\p{L}+r(?:ía|ías|íamos|ían)\\b","flags":"iu","label":"say what you would do: the -ría form (iría, haría)"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"g:si-hypothetical","next":"t4"},{"id":"t4","npc":"Eliécer: Para cuatro, noventa mil. Mi hijo quiere ser guía, pero no sabe nadar, como si fuera de Bogotá.","npcEn":"Eliécer: For four, ninety thousand. My son wants to be a guide, but he can't swim, as if he were from Bogotá.","intent":"Laugh and say you don't swim very well either, so you hope the sea is calm tomorrow.","accept":["Yo tampoco nado muy bien. Ojalá el mar esté tranquilo mañana.","Ja, yo tampoco nado bien. Espero que el mar esté tranquilo.","A mí me pasa lo mismo, nado muy mal. Ojalá no haya muchas olas."],"require":[{"type":"regex","pattern":"\\bnad[oa]\\w*\\b","flags":"iu","label":"say you don't swim well: nado"}],"focus":"g:subj-wishes","next":"t5"},{"id":"t5","npc":"Eliécer: Entonces mañana a las cinco, en el muelle. Y traiga una chaqueta, que temprano hay niebla.","npcEn":"Eliécer: Then tomorrow at five, at the dock. And bring a jacket, because early on there's fog.","intent":"Confirm tomorrow at five at the dock, thank him and say goodbye.","accept":["Perfecto, mañana a las cinco en el muelle. Muchas gracias, hasta mañana.","Listo, a las cinco en el muelle. Gracias, señor, hasta mañana.","De acuerdo, mañana a las cinco. Muchas gracias y hasta mañana."],"require":[{"type":"regex","pattern":"\\bcinco\\b","flags":"iu","label":"confirm the time: a las cinco"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"g:imperfect-subj","next":null}],"r":["g:conditional","g:gender-articles","g:hay-vs-esta","g:imperfect-subj","g:present-ar","g:present-er-ir","g:ser-identity","g:si-hypothetical","g:subj-wishes"],"d":339,"spare":true},
{"id":"sc-u41-a","unit":"u41","band":"B1","title":"Lo que pidió Joaquín","brief":"You're Tomás, in the sitting room of Yesid's grandmother, who has just told you what Joaquín wanted before he died. She is much older than you, so use usted. Say what you wish, ask what else he asked of her, report what Yesid asked of you, and say what you would like.","turns":[{"id":"t1","npc":"Gracias por venir hasta aquí, Tomás. Joaquín siempre quería que alguien de la familia volviera a Bogotá.","npcEn":"Thank you for coming all the way here, Tomás. Joaquín always wanted someone from the family to go back to Bogotá.","intent":"Say you wish he were still alive so you could meet him.","accept":["Ojalá estuviera vivo, señora. Me gustaría conocerlo.","Ojalá él viviera todavía para que yo pudiera conocerlo.","Ojalá pudiera conocerlo, señora."],"require":[{"type":"regex","pattern":"ojal[aá](?![\\p{L}])","flags":"iu","label":"start the wish with ojalá"},{"type":"anyVerbInTense","tense":"impsubj","label":"use the past subjunctive (-ra form) after the trigger"}],"focus":"g:ojala-past","next":"t2"},{"id":"t2","npc":"Antes de morir me pidió que hiciéramos las paces con la familia de Rosa. Me lo pidió tres veces.","npcEn":"Before he died he asked me to make peace with Rosa's family. He asked me three times.","intent":"Ask her what else he asked her to do.","accept":["¿Qué más le pidió que hiciera?","Y a usted, ¿qué más le pidió que hiciera?","¿Le pidió que hiciera algo más, señora?"],"require":[{"type":"question","label":"ask a question"},{"type":"regex","pattern":"pidi[óo] que","flags":"iu","label":"use pidió que + past subjunctive"},{"type":"anyVerbInTense","tense":"impsubj","label":"use the past subjunctive (-ra form) after the trigger"}],"focus":"g:reported-commands-past","next":"t3"},{"id":"t3","npc":"Mi nieto Yesid habló con usted en el barco. ¿Qué le pidió?","npcEn":"My grandson Yesid talked to you on the boat. What did he ask you?","intent":"Say he asked you not to lie to him.","accept":["Me pidió que no le mintiera.","Yesid me pidió que no le mintiera, señora.","Me dijo que no le mintiera nunca."],"require":[{"type":"regex","pattern":"(dijo|pidi[óo]) que","flags":"iu","label":"report it with dijo que or pidió que"},{"type":"anyVerbInTense","tense":"impsubj","label":"use the past subjunctive (-ra form) after the trigger"},{"type":"negation","label":"he asked you not to"}],"focus":"g:reported-commands-past","next":"t4"},{"id":"t4","npc":"Es orgulloso, como su abuelo. Ahora pregunta qué gana él con todo esto. ¿Usted qué le diría?","npcEn":"He is proud, like his grandfather. Now he asks what he gets out of all this. What would you tell him?","intent":"Say you would like him to come to Bogotá to meet the family.","accept":["Me gustaría que viniera a Bogotá para conocer a la familia.","Le diría que me gustaría que viniera a Bogotá con ustedes.","Me gustaría que viniera a Bogotá, señora, y conociera a todos."],"require":[{"type":"regex","pattern":"gustar[ií]a que","flags":"iu","label":"say me gustaría que"},{"type":"anyVerbInTense","tense":"impsubj","label":"use the past subjunctive (-ra form) after the trigger"}],"focus":"g:subj-past-triggers","next":"t5"},{"id":"t5","npc":"Está bien. Hablaré con él. Pero antes, ¿le sirvo un café?","npcEn":"All right. I'll talk to him. But first, may I serve you a coffee?","intent":"Accept the coffee, thank her, and tell her she can count on you.","accept":["Claro, gracias. Cuente conmigo, señora.","Con mucho gusto, gracias. Cuente conmigo.","Sí, gracias, señora. Cuente conmigo para lo que necesite."],"require":[{"type":"regex","pattern":"cuente conmigo","flags":"iu","label":"say she can count on you: cuente conmigo"}],"focus":"c:cuenta-conmigo","next":null}],"r":["c:cuenta-conmigo","g:gender-articles","g:imperfect-subj","g:indirect-objects","g:ojala-past","g:preterite-spelling-stem","g:questions","g:reported-commands-past","g:subj-past-triggers"],"d":431},
{"id":"sc-u41-b","unit":"u41","band":"B1","title":"El abrigo de Hernando","brief":"You're Tomás, in the café kitchen on a cold morning. Vale is up to her elbows in flour, and Don Hernando has wandered off without his coat. She is your friend, so use tú. Report what Mariana asked you, make a wish, ask if she'd mind if you left, and promise to bring him back.","turns":[{"id":"t1","npc":"Llegaste tarde. ¿Qué te pidió Mariana por teléfono?","npcEn":"You're late. What did Mariana ask you to do on the phone?","intent":"Say she asked you to bring the papers to her office.","accept":["Me pidió que llevara los papeles a su oficina.","Mariana me pidió que le llevara los papeles.","Me dijo que llevara los papeles a la oficina, Vale."],"require":[{"type":"regex","pattern":"(pidi[óo]|dijo) que","flags":"iu","label":"report it with pidió que or dijo que"},{"type":"anyVerbInTense","tense":"impsubj","label":"use the past subjunctive (-ra form) after the trigger"}],"focus":"g:reported-commands-past","next":"t2"},{"id":"t2","npc":"Hernando no está. Le dije que esperara aquí, y se fue sin abrigo, con este frío.","npcEn":"Hernando isn't here. I told him to wait here, and he left without his coat, in this cold.","intent":"Say you wish he were less stubborn.","accept":["Ojalá fuera menos terco.","Ojalá él fuera menos terco, Vale.","Ojalá nos escuchara de vez en cuando."],"require":[{"type":"regex","pattern":"ojal[aá](?![\\p{L}])","flags":"iu","label":"start the wish with ojalá"},{"type":"anyVerbInTense","tense":"impsubj","label":"use the past subjunctive (-ra form) after the trigger"}],"focus":"g:ojala-past","next":"t3"},{"id":"t3","npc":"Tengo las manos llenas de harina y no puedo salir. ¿Tú qué piensas hacer?","npcEn":"My hands are covered in flour and I can't go out. What are you going to do?","intent":"Ask whether she would mind if you went to look for him now.","accept":["¿Te importaría que fuera a buscarlo ahora?","Vale, ¿te importaría que saliera a buscarlo ahora mismo?","¿Te importaría que me fuera ahora para buscarlo?"],"require":[{"type":"question","label":"ask a question"},{"type":"regex","pattern":"importar[ií]a que","flags":"iu","label":"ask with ¿te importaría que...?"},{"type":"anyVerbInTense","tense":"impsubj","label":"use the past subjunctive (-ra form) after the trigger"}],"focus":"p:te-importaria-que","next":"t4"},{"id":"t4","npc":"Para nada, ve. Hoy lo vi hablando con Simón como si fuera su abogado.","npcEn":"Not at all, go. Today I saw him talking to Simón as if he were his lawyer.","intent":"Agree: he always talks as if he were the owner.","accept":["Siempre habla como si fuera el dueño.","Sí, habla como si fuera el dueño del café.","Es verdad, actúa como si fuera el jefe."],"require":[{"type":"regex","pattern":"como si","flags":"iu","label":"use como si"},{"type":"anyVerbInTense","tense":"impsubj","label":"use the past subjunctive (-ra form) after the trigger"}],"focus":"g:como-si","next":"t5"},{"id":"t5","npc":"Llévale el abrigo y avísame cuando lo encuentres. Te guardo pan caliente.","npcEn":"Take him his coat and let me know when you find him. I'll save you some warm bread.","intent":"Thank her and say she can count on you to bring him back.","accept":["Gracias. Cuenta conmigo, te lo traigo.","Cuenta conmigo, Vale, lo traigo pronto.","Gracias por el pan. Cuenta conmigo."],"require":[{"type":"regex","pattern":"cuenta conmigo","flags":"iu","label":"say count on me: cuenta conmigo"}],"focus":"c:cuenta-conmigo","next":null}],"r":["c:cuenta-conmigo","g:como-si","g:direct-objects","g:gender-articles","g:imperfect-subj","g:indirect-objects","g:ojala-past","g:questions","g:reported-commands-past","p:te-importaria-que"],"d":510},
{"id":"sc-u41-c","unit":"u41","band":"B1","title":"Una llamada a Taganga","brief":"You're Tomás, on the phone to Wilson, Yesid's uncle, the one who sold Joaquín's ID card. He is older than you and ashamed, so use usted. Introduce yourself with a wish, tell him what his mother asked of you, be honest about what you can promise, and thank him.","turns":[{"id":"t1","npc":"¿Aló? ¿Quién habla? Mi mamá me dijo que usted me iba a llamar.","npcEn":"Hello? Who's speaking? My mom told me you were going to call me.","intent":"Say you're Tomás, Rosa's grandson, and you wish you could talk in person.","accept":["Soy Tomás, el nieto de Rosa. Ojalá pudiéramos hablar en persona.","Habla Tomás, el nieto de Rosa. Ojalá pudiéramos vernos en persona.","Buenas tardes, don Wilson. Soy Tomás. Ojalá pudiera hablar con usted en persona."],"require":[{"type":"regex","pattern":"ojal[aá](?![\\p{L}])","flags":"iu","label":"start the wish with ojalá"},{"type":"anyVerbInTense","tense":"impsubj","label":"use the past subjunctive (-ra form) after the trigger"}],"focus":"g:ojala-past","next":"t2"},{"id":"t2","npc":"Yo sé por qué llama. Mi papá me pedía que no hablara con nadie de Bogotá, y ahora mi mamá me pide lo contrario.","npcEn":"I know why you're calling. My dad used to ask me not to talk to anyone from Bogotá, and now my mom asks me for the opposite.","intent":"Say you understand, and that his mother asked you not to bring a lawyer.","accept":["Lo entiendo. Su mamá me pidió que no viniera con abogado.","Entiendo, don Wilson. A mí su mamá me pidió que no trajera abogado.","Lo entiendo. Y su mamá me pidió que no trajera a ningún abogado."],"require":[{"type":"regex","pattern":"pidi[óo] que","flags":"iu","label":"use pidió que + past subjunctive"},{"type":"anyVerbInTense","tense":"impsubj","label":"use the past subjunctive (-ra form) after the trigger"},{"type":"negation","label":"she asked you not to"}],"focus":"g:reported-commands-past","next":"t3"},{"id":"t3","npc":"Está bien. Le digo la verdad: tengo deudas, y ese señor Duarte me pagó. ¿Qué gano yo si hablo?","npcEn":"All right. I'll tell you the truth: I have debts, and that man Duarte paid me. What do I get if I talk?","intent":"Be honest: you promise nothing, but you would like him to tell the truth.","accept":["No le prometo nada, pero me gustaría que dijera la verdad.","No puedo prometerle nada. Me gustaría que contara la verdad.","No le prometo nada, don Wilson. Pero me gustaría que dijera todo."],"require":[{"type":"negation","label":"promise nothing"},{"type":"regex","pattern":"gustar[ií]a que","flags":"iu","label":"say what you would like him to do: me gustaría que..."},{"type":"anyVerbInTense","tense":"impsubj","label":"use the past subjunctive (-ra form) after the trigger"}],"focus":"g:subj-past-triggers","next":"t4"},{"id":"t4","npc":"Bueno. ¿Le importaría que hablara primero con mi sobrino Yesid?","npcEn":"All right. Would you mind if I talked to my nephew Yesid first?","intent":"Say not at all, you would like him to talk to Yesid first.","accept":["Para nada. Me gustaría que hablara con él primero.","No, claro que no. Me gustaría que hablaran los dos.","Para nada, don Wilson. Ojalá hablara con él hoy mismo."],"require":[{"type":"anyVerbInTense","tense":"impsubj","label":"use the past subjunctive (-ra form) after the trigger"}],"focus":"p:te-importaria-que","next":"t5"},{"id":"t5","npc":"Bueno. Pero que quede claro: si hablo, hablo por mi papá, no por Altamira ni por usted.","npcEn":"All right. But let's be clear: if I talk, I talk for my dad, not for Altamira or for you.","intent":"Thank him and tell him he can count on you.","accept":["Gracias, don Wilson. Cuente conmigo.","Muchas gracias. Cuente conmigo para lo que necesite.","Gracias por su papá y por Rosa. Cuente conmigo."],"require":[{"type":"regex","pattern":"cuente conmigo","flags":"iu","label":"say he can count on you: cuente conmigo"}],"focus":"c:cuenta-conmigo","next":null}],"r":["c:cuenta-conmigo","g:imperfect-habitual","g:imperfect-subj","g:ojala-past","g:present-ar","g:questions","g:reported-commands-past","g:si-present","g:subj-past-triggers","g:that-clauses","g:yo-irregular","p:te-importaria-que"],"d":431,"spare":true}
];
